window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2024-1"]={"track":"written","round":"2024-1","questions":[{"id":"written-2024-1-1","no":1,"unit":"소프트웨어 설계","q":"XP(eXtreme Programming)에 관한 설명으로 옳지 않은 것은?","choices":["개발 책임자가 모든 책임을 가지기 때문에 팀원들은 책임 없이 자유롭게 개발할 수 있다.","코드들은 하나의 작업이 마무리될 때마다 지속적으로 통합된다.","테스트가 지속적으로 진행되도록 테스트 자동화 도구를 사용한다.","짧은 릴리즈 기간을 반복하여 고객의 요구 변화에 빠르게 대응한다."],"ans":1,"exp":{"concept":"XP(eXtreme Programming)는 짧은 주기로 자주 릴리즈하고, 테스트와 통합을 계속 반복하는 애자일 방법론이다. 코드는 특정 한 사람의 것이 아니라 팀 전체가 함께 소유하고 함께 책임진다(공동 소유). 축구팀이 감독 한 명이 아니라 선수 모두가 함께 경기 결과를 책임지는 것과 비슷하다.","choices":[{"verdict":"정답","why":"XP는 공동 소유(Collective Ownership)를 실천 사항으로 두어 팀원 모두가 코드에 대한 책임을 나눠 가진다. 책임자 한 명이 모든 책임을 지고 팀원은 책임이 없다는 설명은 XP와 반대다."},{"verdict":"오답","why":"지속적인 통합(Continuous Integration)은 XP의 실천 사항으로, 작업 하나가 끝날 때마다 코드를 통합한다."},{"verdict":"오답","why":"XP는 테스트 주도 개발을 강조하며, 테스트를 자동화해 계속 수행한다. 맞는 설명이다."},{"verdict":"오답","why":"XP는 짧은 릴리즈(Small Releases)를 반복해 고객 요구 변화에 빠르게 대응한다. 맞는 설명이다."}],"keywords":[{"term":"XP 5가지 핵심 가치","desc":"용기, 단순성, 의사소통, 피드백, 존중"},{"term":"공동 소유(Collective Ownership)","desc":"시스템의 코드는 팀 전체가 공동으로 소유하고 누구든 수정할 수 있다"},{"term":"지속적인 통합(Continuous Integration)","desc":"작업이 끝날 때마다 모듈 단위로 나눠 개발한 코드를 계속 통합한다"},{"term":"짝 프로그래밍(Pair Programming)","desc":"두 사람이 한 컴퓨터로 함께 코딩해 책임을 나누고 품질을 높인다"}],"memo":"XP의 핵심 가치 '용기, 단순성, 의사소통, 피드백, 존중'을 떠올리면, 한 사람에게 책임을 몰아주는 보기는 바로 걸러진다."}},{"id":"written-2024-1-2","no":2,"unit":"소프트웨어 설계","q":"폭포수 모형의 특징과 거리가 먼 것은?","choices":["모형의 적용 경험 및 성공사례가 많다.","순차적 접근방법을 이용한다.","단계별 정의와 산출물이 명확하다.","나선형 모형의 단점을 보완하고자 만든 모형이다."],"ans":4,"exp":{"concept":"폭포수 모형은 요구 분석, 설계, 구현, 테스트, 유지보수를 폭포가 떨어지듯 한 단계씩 순서대로 진행하는 가장 오래된 고전적 생명 주기 모형이다. 앞 단계가 끝나야 다음 단계로 넘어가고, 각 단계의 결과물이 명확하다. 나선형 모형은 폭포수 모형과 프로토타입 모형의 장점에 위험 분석을 더해 나중에 나온 모형이다.","choices":[{"verdict":"오답","why":"폭포수 모형은 가장 오래되고 널리 쓰인 모형이라 적용 경험과 성공 사례가 많다. 맞는 특징이다."},{"verdict":"오답","why":"폭포수 모형은 이전 단계로 돌아가기 어려운 순차적(선형) 접근 방법을 쓴다. 맞는 특징이다."},{"verdict":"오답","why":"각 단계가 끝날 때 결과물(산출물)이 명확하게 나와야 다음 단계로 넘어간다. 맞는 특징이다."},{"verdict":"정답","why":"나선형 모형이 폭포수 모형과 프로토타입 모형의 장점에 위험 분석을 추가해 만든 모형이다. 방향이 거꾸로 되어 있으므로 폭포수 모형의 특징이 아니다."}],"keywords":[{"term":"폭포수 모형(Waterfall Model)","desc":"단계를 순차적으로 진행하는 고전적 생명 주기 모형, 선형 순차적 모형"},{"term":"나선형 모형(Spiral Model)","desc":"폭포수와 프로토타입 모형의 장점에 위험 분석을 더한 점진적 모형"},{"term":"프로토타입 모형(Prototype Model)","desc":"견본품을 만들어 사용자 요구를 확인하며 개발하는 모형"}],"memo":"출현 순서는 폭포수가 먼저, 나선형이 나중이다. '먼저 나온 모형이 나중 모형의 단점을 보완'한다는 보기는 시간 순서가 틀렸다."}},{"id":"written-2024-1-3","no":3,"unit":"소프트웨어 설계","q":"UML 모델에서 어느 한 사물의 명세가 변경되면 다른 사물에 영향을 미치며, 보통 한 클래스가 다른 클래스를 오퍼레이션의 매개 변수로 사용할 때 나타나는 관계는?","choices":["Dependency","Association","Realization","Generalization"],"ans":1,"exp":{"concept":"UML의 관계 중 의존(Dependency) 관계는 한 사물이 다른 사물을 잠깐 사용하는 관계라서, 사용되는 쪽이 바뀌면 사용하는 쪽도 영향을 받는다. 보통 한 클래스가 다른 클래스를 메소드의 매개 변수나 지역 변수로 짧게 쓸 때 나타나며, 점선 화살표로 그린다.","choices":[{"verdict":"정답","why":"의존(Dependency) 관계는 한 클래스가 다른 클래스를 오퍼레이션의 매개 변수 등으로 잠시 사용할 때 생기며, 명세가 바뀌면 사용하는 쪽에 영향을 준다."},{"verdict":"오답","why":"연관(Association) 관계는 2개 이상의 사물이 서로 관련되어 있는 관계로, 실선으로 표시한다."},{"verdict":"오답","why":"실체화(Realization) 관계는 인터페이스가 정의한 기능을 클래스가 실제로 구현하는 관계다."},{"verdict":"오답","why":"일반화(Generalization) 관계는 상위(부모)와 하위(자식) 사이의 is-a 관계, 즉 상속 관계다."}],"keywords":[{"term":"의존(Dependency)","desc":"한 사물이 다른 사물을 짧게 사용하는 관계, 점선 화살표"},{"term":"연관(Association)","desc":"사물들이 서로 관련된 관계, 실선"},{"term":"실체화(Realization)","desc":"인터페이스의 기능을 클래스가 구현하는 관계, 점선과 빈 삼각형"},{"term":"일반화(Generalization)","desc":"상속을 나타내는 is-a 관계, 실선과 빈 삼각형"}],"memo":"'매개 변수로 사용', '변경되면 영향'이라는 말이 나오면 의존 관계다."}},{"id":"written-2024-1-4","no":4,"unit":"소프트웨어 설계","q":"애자일(Agile) 프로세스 모델에 관한 설명 중 틀린 것은?","choices":["문서 중심이 아닌 실행 가능한 소프트웨어를 중시한다.","변화에 대한 대응보다는 자세한 계획을 중심으로 하여 소프트웨어를 개발한다.","프로세스와 도구 중심이 아니라 개개인과의 상호소통을 통해 의견을 수렴한다.","협상과 계약보다 고객과의 협력을 중시한다."],"ans":2,"exp":{"concept":"애자일(Agile)은 정해진 계획을 끝까지 따르기보다 고객과 자주 소통하며 변화에 빠르게 대응하는 개발 방식이다. 애자일 선언문은 프로세스와 도구보다 개인과 상호작용, 포괄적 문서보다 작동하는 소프트웨어, 계약 협상보다 고객과의 협력, 계획을 따르기보다 변화에 대응하기를 더 중요하게 여긴다.","choices":[{"verdict":"오답","why":"애자일 선언문의 '포괄적인 문서보다 작동하는 소프트웨어'에 해당하는 맞는 설명이다."},{"verdict":"정답","why":"애자일은 '계획을 따르기보다 변화에 대응하기'를 중시한다. 변화 대응보다 자세한 계획을 중심으로 한다는 설명은 반대다."},{"verdict":"오답","why":"애자일 선언문의 '프로세스와 도구보다 개인과 상호작용'에 해당하는 맞는 설명이다."},{"verdict":"오답","why":"애자일 선언문의 '계약 협상보다 고객과의 협력'에 해당하는 맞는 설명이다."}],"keywords":[{"term":"애자일 선언문 4가지 가치","desc":"개인과 상호작용, 작동하는 소프트웨어, 고객과의 협력, 변화에 대응"},{"term":"XP(eXtreme Programming)","desc":"짧은 반복과 고객 참여를 강조하는 대표적인 애자일 방법론"},{"term":"스크럼(Scrum)","desc":"스프린트라는 짧은 주기로 일하는 팀 중심 애자일 방법론"}],"memo":"애자일 문항은 '계획, 문서, 도구, 계약'을 앞세우는 보기가 틀린 보기다."}},{"id":"written-2024-1-5","no":5,"unit":"소프트웨어 설계","q":"아키텍처 설계 과정을 올바른 순서대로 나열한 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul class=\"is-labeled\"><li>가. 설계 목표 설정</li><li>나. 시스템 타입 결정</li><li>다. 스타일 적용 및 커스터마이즈</li><li>라. 서브시스템의 기능, 인터페이스 동작 작성</li><li>마. 아키텍처 설계 검토</li></ul></div>","choices":["㉮ → ㉯ → ㉰ → ㉱ → ㉲","㉲ → ㉮ → ㉯ → ㉱ → ㉰","㉮ → ㉲ → ㉯ → ㉱ → ㉰","㉮ → ㉯ → ㉰ → ㉲ → ㉱"],"ans":1,"exp":{"concept":"아키텍처 설계는 큰 목표에서 출발해 점점 구체화한 뒤 마지막에 검토하는 순서로 진행한다. 먼저 무엇을 이룰지 설계 목표를 정하고, 어떤 종류의 시스템인지 타입을 결정한 다음, 알맞은 아키텍처 스타일을 적용해 다듬고, 서브시스템의 기능과 인터페이스를 작성한 뒤, 마지막으로 전체 설계를 검토한다.","choices":[{"verdict":"정답","why":"설계 목표 설정 → 시스템 타입 결정 → 스타일 적용 및 커스터마이즈 → 서브시스템의 기능·인터페이스 동작 작성 → 아키텍처 설계 검토 순서로, 아키텍처 설계 과정의 올바른 순서다."},{"verdict":"오답","why":"설계 검토는 설계 결과물이 나온 뒤에 하는 마지막 단계이므로 맨 앞에 올 수 없다."},{"verdict":"오답","why":"설계 검토가 두 번째로 오고 스타일 적용이 맨 마지막에 와 있어 순서가 맞지 않는다."},{"verdict":"오답","why":"서브시스템의 기능과 인터페이스를 작성하기 전에 설계 검토를 할 수는 없다. 검토는 마지막 단계다."}],"keywords":[{"term":"아키텍처 설계 과정","desc":"설계 목표 설정 → 시스템 타입 결정 → 스타일 적용 및 커스터마이즈 → 서브시스템 기능·인터페이스 작성 → 설계 검토"},{"term":"아키텍처 스타일(패턴)","desc":"레이어, 클라이언트-서버, 파이프-필터, MVC 등 자주 쓰는 구조의 틀"}],"memo":"'목표 → 타입 → 스타일 → 서브시스템 → 검토', 검토는 언제나 마지막이다."}},{"id":"written-2024-1-6","no":6,"unit":"소프트웨어 설계","q":"다음 중 CASE(Computer-Aided Software Engineering)의 원천 기술에 해당하지 않는 것은?","choices":["정보 저장소 기술","프로토타이핑 기술","구조적 기법","일괄처리 기술"],"ans":4,"exp":{"concept":"CASE(Computer-Aided Software Engineering)는 소프트웨어 개발 과정의 작업을 컴퓨터 도구로 자동화해 주는 것이다. CASE를 가능하게 한 바탕 기술(원천 기술)로는 구조적 기법, 프로토타이핑 기술, 자동 프로그래밍 기술, 정보 저장소 기술, 분산 처리 기술이 있다.","choices":[{"verdict":"오답","why":"정보 저장소(Repository) 기술은 개발 산출물을 저장하고 공유하게 해 주는 CASE의 원천 기술이다."},{"verdict":"오답","why":"프로토타이핑 기술은 견본품을 빠르게 만드는 CASE의 원천 기술이다."},{"verdict":"오답","why":"구조적 기법은 CASE의 원천 기술이다."},{"verdict":"정답","why":"일괄처리 기술은 데이터를 모아 한꺼번에 처리하는 방식으로, CASE의 원천 기술에 포함되지 않는다. 원천 기술은 분산 처리 기술이다."}],"keywords":[{"term":"CASE","desc":"소프트웨어 개발 과정을 컴퓨터와 전용 도구로 자동화하는 것"},{"term":"CASE 원천 기술","desc":"구조적 기법, 프로토타이핑 기술, 자동 프로그래밍 기술, 정보 저장소 기술, 분산 처리 기술"},{"term":"정보 저장소(Repository)","desc":"개발 과정의 산출물과 정보를 저장하고 공유하는 곳"}],"memo":"원천 기술 중 '처리' 기술은 '분산' 처리다. '일괄' 처리로 바꿔 내는 함정이 자주 나온다."}},{"id":"written-2024-1-7","no":7,"unit":"소프트웨어 설계","q":"객체지향 기법에서 같은 형의 특성을 지닌 객체들을 모아 구성한 것으로, 객체와 클래스 간의 ‘is instance of’ 관계로 설명되는 연관성을 가리키는 용어는?","choices":["연관화","분류화","일반화","집단화"],"ans":2,"exp":{"concept":"객체지향의 추상화 관계에는 분류화, 일반화, 집단화, 연관화가 있다. 분류화는 같은 특성을 가진 객체들을 모아 하나의 클래스로 묶는 것으로, '이 객체는 그 클래스의 한 사례이다(is instance of)'라는 관계로 표현된다. 예를 들어 '철수'와 '영희'는 '학생' 클래스의 인스턴스다.","choices":[{"verdict":"오답","why":"연관화(Association)는 서로 관련 있는 개체들을 묶는 것으로, 'is member of' 관계로 설명된다."},{"verdict":"정답","why":"분류화(Classification)는 같은 형의 특성을 지닌 객체들을 모아 클래스를 구성하는 것으로, 'is instance of' 관계로 설명된다."},{"verdict":"오답","why":"일반화(Generalization)는 공통 성질을 가진 클래스들을 상위 클래스로 묶는 것으로, 'is a kind of(is-a)' 관계로 설명된다."},{"verdict":"오답","why":"집단화(Aggregation)는 여러 부분 객체가 모여 하나의 전체 객체를 이루는 것으로, 'is part of' 관계로 설명된다."}],"keywords":[{"term":"분류화(Classification)","desc":"is instance of, 객체와 클래스의 관계"},{"term":"일반화(Generalization)","desc":"is a kind of, 하위 클래스와 상위 클래스의 관계"},{"term":"집단화(Aggregation)","desc":"is part of, 부분과 전체의 관계"},{"term":"연관화(Association)","desc":"is member of, 관련된 개체들의 모임"}],"memo":"instance는 분류화, kind는 일반화, part는 집단화, member는 연관화로 짝지어 외운다."}},{"id":"written-2024-1-8","no":8,"unit":"소프트웨어 설계","q":"클래스(Class)에 관한 다음 설명의 괄호(㉠, ㉡)에 들어갈 용어로 알맞은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>클래스는 개별 객체들이 가지는 ( ㉠ )과 ( ㉡ )을 표현함</li><li>( ㉠ ) : 클래스의 상태나 정보를 나타냄</li><li>( ㉡ ) : 클래스가 수행 가능한 동작으로, 함수 (메소드, Method)라고도 불림</li></ul></div>","choices":["㉠-제약조건, ㉡-속성","㉠-속성, ㉡-관계","㉠-속성, ㉡-오퍼레이션","㉠-오퍼레이션, ㉡-제약조건"],"ans":3,"exp":{"concept":"클래스는 같은 종류의 객체를 만들기 위한 설계도다. 클래스에는 객체의 상태나 정보를 나타내는 속성(Attribute)과, 객체가 할 수 있는 동작인 오퍼레이션(Operation)이 들어 있다. 자동차로 치면 색상과 속도는 속성이고, 달리기와 멈추기는 오퍼레이션이다.","choices":[{"verdict":"오답","why":"제약 조건은 클래스의 상태나 정보가 아니며, 동작을 나타내는 것은 속성이 아니라 오퍼레이션이다."},{"verdict":"오답","why":"㉠ 속성은 맞지만, 관계(Relationship)는 클래스끼리의 연결을 나타내는 것이지 클래스가 수행하는 동작이 아니다."},{"verdict":"정답","why":"상태나 정보를 나타내는 것은 속성(Attribute), 수행 가능한 동작으로 메소드라고도 불리는 것은 오퍼레이션(Operation)이다."},{"verdict":"오답","why":"상태나 정보를 나타내는 것은 오퍼레이션이 아니라 속성이며, 제약 조건은 동작이 아니다."}],"keywords":[{"term":"속성(Attribute)","desc":"클래스의 상태나 정보를 나타내는 값, 멤버 변수"},{"term":"오퍼레이션(Operation)","desc":"클래스가 수행할 수 있는 동작, 메소드"},{"term":"클래스(Class)","desc":"공통 속성과 오퍼레이션을 가진 객체들의 틀"}],"memo":"UML 클래스 다이어그램의 세 칸은 위에서부터 '이름, 속성, 오퍼레이션' 순서다."}},{"id":"written-2024-1-9","no":9,"unit":"소프트웨어 설계","q":"디자인 패턴 사용의 장٠단점에 관한 설명으로 거리가 먼 것은?","choices":["소프트웨어의 구조를 파악하기 용이하다.","객체지향 설계와 구현의 생산성을 높이는 데 적합하다.","절차형 언어와 함께 사용될 때 효율이 극대화된다.","재사용을 위한 개발 시간을 단축할 수 있다."],"ans":3,"exp":{"concept":"디자인 패턴은 객체지향 설계에서 자주 생기는 문제와 그 해결 방법을 이름 붙여 정리해 둔 모범 답안이다. 구조를 이해하기 쉽고, 재사용으로 개발 시간을 줄일 수 있다는 장점이 있다. 다만 객체지향 설계와 구현을 전제로 만든 것이라 절차형 언어와는 잘 맞지 않는다.","choices":[{"verdict":"오답","why":"디자인 패턴을 쓰면 설계 구조가 이름 붙은 패턴으로 정리되어 소프트웨어의 구조를 파악하기 쉽다. 장점에 해당한다."},{"verdict":"오답","why":"디자인 패턴은 객체지향 설계와 구현의 생산성을 높이는 데 적합하다. 장점에 해당한다."},{"verdict":"정답","why":"디자인 패턴은 객체지향 설계를 대상으로 하므로 절차형 언어와 함께 쓰면 효율이 극대화되지 않는다. 오히려 객체지향이 아닌 환경에서는 활용하기 어렵다는 것이 단점이다."},{"verdict":"오답","why":"검증된 해결 방법을 재사용하므로 개발 시간을 단축할 수 있다. 장점에 해당한다."}],"keywords":[{"term":"디자인 패턴(Design Pattern)","desc":"자주 생기는 설계 문제와 해결 방법을 정리한 재사용 가능한 모범 설계"},{"term":"GoF 디자인 패턴","desc":"생성 패턴, 구조 패턴, 행위 패턴의 3가지 유형으로 나눈다"}],"memo":"디자인 패턴은 '객체지향' 전용 도구다. '절차형'과 짝지은 보기는 틀린다."}},{"id":"written-2024-1-10","no":10,"unit":"소프트웨어 설계","q":"사용자 인터페이스(UI) 가운데 명령과 출력이 오직 텍스트 형태로 이루어지는 인터페이스는 무엇인가?","choices":["NUI","CLI","GUI","OUI"],"ans":2,"exp":{"concept":"사용자 인터페이스(UI)는 사람이 컴퓨터와 소통하는 방식이다. 키보드로 글자 명령을 입력하고 결과도 글자로만 받는 방식이 CLI이고, 마우스로 아이콘과 창을 누르는 방식이 GUI다. 윈도우의 명령 프롬프트나 리눅스 터미널이 CLI의 예다.","choices":[{"verdict":"오답","why":"NUI(Natural User Interface)는 터치, 음성, 몸짓처럼 사람의 자연스러운 행동으로 조작하는 인터페이스다."},{"verdict":"정답","why":"CLI(Command Line Interface)는 명령어를 텍스트로 입력하고 결과도 텍스트로 출력되는 인터페이스다."},{"verdict":"오답","why":"GUI(Graphical User Interface)는 아이콘, 메뉴 등 그래픽 요소를 마우스로 조작하는 인터페이스다."},{"verdict":"오답","why":"OUI(Organic User Interface)는 모든 사물과 사용자 간의 상호작용을 위한 인터페이스다."}],"keywords":[{"term":"CLI(Command Line Interface)","desc":"텍스트 명령어로 입력하고 텍스트로 출력되는 UI"},{"term":"GUI(Graphical User Interface)","desc":"그래픽 요소를 마우스로 조작하는 UI"},{"term":"NUI(Natural User Interface)","desc":"터치, 음성, 동작 등 자연스러운 행동으로 조작하는 UI"},{"term":"OUI(Organic User Interface)","desc":"사물과 사용자 간 상호작용을 위한 UI"}],"memo":"C는 Command(명령어 글자), G는 Graphic(그림), N은 Natural(손짓·말), O는 Organic(사물과의 유기적 상호작용)로 기억한다."}},{"id":"written-2024-1-11","no":11,"unit":"소프트웨어 설계","q":"HIPO(Hierarchy Input Process Output)에 관한 설명 중 거리가 먼 것은?","choices":["기능과 자료의 의존 관계를 함께 표현할 수 있다.","상향식 소프트웨어 개발을 위한 문서화 도구에 해당한다.","보기 쉽고 이해하기도 쉽다.","HIPO 차트의 종류로는 가시적 도표, 총체적 도표, 세부적 도표가 있다."],"ans":2,"exp":{"concept":"HIPO(Hierarchy Input Process Output)는 시스템의 기능을 위에서 아래로 계층적으로 나누고, 각 기능의 입력, 처리, 출력을 도표로 나타내는 문서화 도구다. 하향식(Top-Down) 개발을 위한 도구이며, 가시적 도표, 총체적 도표, 세부적 도표로 구성된다.","choices":[{"verdict":"오답","why":"HIPO는 기능과 자료의 의존 관계를 동시에 표현할 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"HIPO는 상향식이 아니라 하향식 소프트웨어 개발을 위한 문서화 도구다."},{"verdict":"오답","why":"HIPO 차트는 보기 쉽고 이해하기 쉬워 변경과 유지보수가 쉽다. 맞는 설명이다."},{"verdict":"오답","why":"HIPO 차트는 가시적 도표(Visual Table of Contents), 총체적 도표(Overview Diagram), 세부적 도표(Detail Diagram)로 이루어진다. 맞는 설명이다."}],"keywords":[{"term":"HIPO","desc":"기능을 계층적으로 나누고 입력·처리·출력을 표현하는 하향식 문서화 도구"},{"term":"가시적 도표(Visual Table of Contents)","desc":"시스템의 전체 기능과 흐름을 트리(나무) 형태로 보여 준다"},{"term":"총체적 도표(Overview Diagram)","desc":"프로그램을 구성하는 기능의 입력, 처리, 출력 정보를 제시한다"},{"term":"세부적 도표(Detail Diagram)","desc":"총체적 도표의 기능을 구성하는 기본 요소를 상세히 기술한다"}],"memo":"Hierarchy(계층)는 위에서 아래로 내려가는 구조라 HIPO는 '하향식'이다."}},{"id":"written-2024-1-12","no":12,"unit":"소프트웨어 설계","q":"자료 흐름도(Data Flow Diagram)를 이루는 구성 요소로 옳게 나열된 것은?","choices":["data flow, data store, terminator, data dictionary","process, data store, terminator, mini-spec","process, data flow, data store, comment","process, data flow, data store, terminator"],"ans":4,"exp":{"concept":"자료 흐름도(DFD, Data Flow Diagram)는 시스템 안에서 자료가 어떻게 흘러가고 처리되는지를 그림으로 나타낸 것이다. 구성 요소는 처리 과정(Process), 자료 흐름(Data Flow), 자료 저장소(Data Store), 단말(Terminator) 네 가지다. 공장으로 치면 작업대(처리), 컨베이어 벨트(흐름), 창고(저장소), 거래처(단말)에 해당한다.","choices":[{"verdict":"오답","why":"자료 사전(Data Dictionary)은 DFD에 나오는 자료를 자세히 정의한 문서로, DFD의 구성 요소가 아니다. 또 처리 과정(Process)이 빠져 있다."},{"verdict":"오답","why":"소단위 명세서(Mini-Spec)는 처리 과정의 논리를 기술한 별도 문서로, DFD의 구성 요소가 아니다. 또 자료 흐름이 빠져 있다."},{"verdict":"오답","why":"주석(Comment)은 DFD의 구성 요소가 아니며, 단말(Terminator)이 빠져 있다."},{"verdict":"정답","why":"처리 과정(Process), 자료 흐름(Data Flow), 자료 저장소(Data Store), 단말(Terminator)이 DFD의 4가지 구성 요소다."}],"keywords":[{"term":"처리 과정(Process)","desc":"자료를 변환하는 작업, 원으로 표시"},{"term":"자료 흐름(Data Flow)","desc":"자료의 이동, 화살표로 표시"},{"term":"자료 저장소(Data Store)","desc":"자료가 저장되는 곳, 평행선으로 표시"},{"term":"단말(Terminator)","desc":"시스템과 교신하는 외부 개체, 사각형으로 표시"},{"term":"자료 사전(DD, Data Dictionary)","desc":"DFD에 나오는 자료의 정의를 기록한 사전으로 DFD 구성 요소는 아니다"}],"memo":"DFD 구성 요소는 '처리, 흐름, 저장소, 단말' 네 가지다. 자료 사전과 소단위 명세서는 DFD를 보충하는 별도 도구다."}},{"id":"written-2024-1-13","no":13,"unit":"소프트웨어 설계","q":"분산 시스템에서의 미들웨어(Middleware)에 관한 설명으로 옳지 않은 것은?","choices":["애플리케이션과 사용자 사이에서만 분산 서비스를 제공한다.","위치 투명성(Location Transparency)을 제공한다.","분산 시스템의 여러 컴포넌트가 요구하는 재사용 가능한 서비스의 구현을 제공해 준다.","분산 시스템의 다양한 부분을 관리하고 통신하며 데이터를 교환할 수 있게 해주는 소프트웨어로 볼 수 있다."],"ans":1,"exp":{"concept":"미들웨어(Middleware)는 서로 다른 운영체제, 하드웨어, 응용 프로그램 사이에서 통신과 데이터 교환을 중개해 주는 소프트웨어다. 분산 시스템에서 여러 컴포넌트가 함께 쓰는 서비스를 제공하고, 상대가 어디에 있는지 몰라도 쓸 수 있게 하는 위치 투명성을 제공한다. 통역사처럼 양쪽 사이에서 말을 전달해 주는 역할이다.","choices":[{"verdict":"정답","why":"미들웨어는 사용자와 애플리케이션 사이에서만 동작하는 것이 아니라, 운영체제와 애플리케이션 사이, 클라이언트와 서버 사이 등 다양한 컴포넌트 사이에서 분산 서비스를 제공한다."},{"verdict":"오답","why":"미들웨어는 접근하려는 자원의 물리적 위치를 몰라도 사용할 수 있게 하는 위치 투명성(Location Transparency)을 제공한다. 맞는 설명이다."},{"verdict":"오답","why":"미들웨어는 분산 시스템의 여러 컴포넌트가 공통으로 요구하는 재사용 가능한 서비스를 구현해 제공한다. 맞는 설명이다."},{"verdict":"오답","why":"미들웨어는 분산 시스템의 여러 부분을 관리하고 서로 통신하며 데이터를 교환하게 해 주는 소프트웨어다. 맞는 설명이다."}],"keywords":[{"term":"미들웨어(Middleware)","desc":"운영체제와 응용 프로그램, 또는 서버와 클라이언트 사이에서 중간 매개 역할을 하는 소프트웨어"},{"term":"위치 투명성(Location Transparency)","desc":"자원의 물리적 위치를 몰라도 접근할 수 있는 성질"},{"term":"미들웨어 종류","desc":"DB, RPC, MOM, TP-Monitor, ORB, WAS 등"}],"memo":"보기에 '~에서만', '오직'처럼 범위를 좁히는 말이 있으면 틀린 보기일 가능성이 크다."}},{"id":"written-2024-1-14","no":14,"unit":"소프트웨어 설계","q":"프로젝트 비용 산정 기법 중 Rayleigh-Norden 곡선의 노력 분포도를 이용하는 것은?","choices":["Putnam 모형","기능점수 모형","델파이 모형","COCOMO 모형"],"ans":1,"exp":{"concept":"소프트웨어 비용 산정 모형 중 Putnam 모형은 개발 기간에 따라 노력(투입 인력)이 어떻게 분포하는지를 Rayleigh-Norden 곡선으로 가정해 비용을 예측한다. 이 곡선은 처음에는 인력이 점점 늘다가 정점을 지나면 줄어드는 모양이다. Putnam 모형을 바탕으로 자동화한 도구가 SLIM이다.","choices":[{"verdict":"정답","why":"Putnam 모형은 소프트웨어 생명 주기 전 과정에 사용될 노력의 분포를 Rayleigh-Norden 곡선으로 가정한 비용 산정 기법이다."},{"verdict":"오답","why":"기능 점수(FP, Function Point) 모형은 소프트웨어 기능을 입력, 출력, 질의, 파일, 인터페이스 등으로 나눠 가중치를 매겨 점수를 구하는 기법이다."},{"verdict":"오답","why":"델파이 기법은 여러 전문가의 의견을 조정자가 모아 조율하는 하향식 비용 산정 기법이다."},{"verdict":"오답","why":"COCOMO 모형은 보엠(Boehm)이 제안한 것으로, 원시 코드 라인 수(LOC)를 바탕으로 비용을 산정한다."}],"keywords":[{"term":"Putnam 모형","desc":"Rayleigh-Norden 곡선의 노력 분포를 이용하는 비용 산정 모형, 자동화 도구는 SLIM"},{"term":"COCOMO 모형","desc":"LOC를 기준으로 Organic, Semi-Detached, Embedded 유형별로 비용을 산정"},{"term":"기능 점수(FP) 모형","desc":"기능별 가중치로 점수를 구해 비용을 산정, 자동화 도구는 ESTIMACS"},{"term":"델파이 기법","desc":"여러 전문가의 의견을 조정자가 종합하는 하향식 기법"}],"memo":"Putnam과 Rayleigh-Norden, SLIM을 한 묶음으로 외운다."}},{"id":"written-2024-1-15","no":15,"unit":"소프트웨어 설계","q":"다음은 어떤 프로그램의 구조를 나타낸 것이다. 모듈 F의 fan-in과 fan-out 수는 각각 얼마인가?<img class=\"q-img\" src=\"data/img/2e4c9e2a67bec1aba0dbc34766ad660c.png\" width=\"498\" alt=\"문항 원본 자료\">","choices":["fan-in : 2, fan-out : 3","fan-in : 3, fan-out : 2","fan-in : 1, fan-out : 2","fan-in : 2, fan-out : 1"],"ans":2,"exp":{"concept":"팬인(Fan-In)은 어떤 모듈을 위에서 호출(제어)하는 상위 모듈의 수이고, 팬아웃(Fan-Out)은 그 모듈이 아래로 호출하는 하위 모듈의 수다. 그림에서 F로 들어오는 선과 F에서 나가는 선을 세면 된다.","choices":[{"verdict":"오답","why":"F를 호출하는 상위 모듈은 2개가 아니라 3개이고, F가 호출하는 하위 모듈은 3개가 아니라 2개다."},{"verdict":"정답","why":"F 위쪽으로 B, C, D 세 모듈이 연결되어 있어 팬인은 3이고, F 아래쪽으로 G, H 두 모듈이 연결되어 있어 팬아웃은 2다."},{"verdict":"오답","why":"F를 호출하는 상위 모듈은 B, C, D 세 개이므로 팬인은 1이 아니다."},{"verdict":"오답","why":"팬인과 팬아웃이 모두 틀렸다. 팬인은 3(B, C, D), 팬아웃은 2(G, H)다."}],"keywords":[{"term":"팬인(Fan-In)","desc":"어떤 모듈을 제어(호출)하는 상위 모듈의 수"},{"term":"팬아웃(Fan-Out)","desc":"어떤 모듈이 제어(호출)하는 하위 모듈의 수"},{"term":"좋은 설계","desc":"팬인은 높게, 팬아웃은 낮게 하는 것이 바람직하다"}],"memo":"In은 위에서 들어오는 선, Out은 아래로 나가는 선이다. 위아래를 바꿔 세는 실수를 조심한다."}},{"id":"written-2024-1-16","no":16,"unit":"소프트웨어 설계","q":"소프트웨어 설계 시 구축된 플랫폼의 성능 특성을 분석하는 데 사용되는 측정 항목으로 옳지 않은 것은?","choices":["서버 튜닝(Server Tuning)","사용률(Utilization)","가용성(Availability)","응답 시간(Response Time)"],"ans":1,"exp":{"concept":"구축된 플랫폼(시스템)의 성능을 분석할 때는 수치로 측정할 수 있는 항목을 본다. 대표적으로 일정 시간에 처리한 양(처리량), 요청 후 첫 응답까지의 시간(응답 시간), 요청부터 처리 완료까지 걸린 시간(경과 시간), 자원을 얼마나 쓰는지(사용률), 언제든 쓸 수 있는 정도(가용성)가 있다.","choices":[{"verdict":"정답","why":"서버 튜닝은 성능을 개선하려고 설정을 조정하는 작업이지, 성능 특성을 분석하는 측정 항목이 아니다."},{"verdict":"오답","why":"사용률(Utilization)은 CPU, 메모리 등 자원을 얼마나 사용하는지를 나타내는 성능 측정 항목이다."},{"verdict":"오답","why":"가용성(Availability)은 시스템을 사용하려 할 때 사용할 수 있는 정도를 나타내는 성능 측정 항목이다."},{"verdict":"오답","why":"응답 시간(Response Time)은 요청을 보낸 뒤 응답이 오기까지 걸린 시간을 나타내는 성능 측정 항목이다."}],"keywords":[{"term":"처리량(Throughput)","desc":"일정 시간 동안 처리하는 일의 양"},{"term":"응답 시간(Response Time)","desc":"요청 후 응답이 올 때까지 걸린 시간"},{"term":"경과 시간(Turnaround Time)","desc":"작업을 의뢰한 시간부터 처리가 완료될 때까지 걸린 시간"},{"term":"사용률(Utilization)","desc":"의뢰한 작업을 처리하는 동안의 자원 사용 정도"},{"term":"가용성(Availability)","desc":"서비스를 요청했을 때 사용할 수 있는 정도"}],"memo":"측정 항목은 '시간, 양, 비율'처럼 숫자로 재는 것이다. '튜닝'은 재는 것이 아니라 고치는 행위다."}},{"id":"written-2024-1-17","no":17,"unit":"소프트웨어 설계","q":"객체지향 분석 방법론 가운데 Coad-Yourdon 방법에 해당하는 것은?","choices":["미시적 개발 프로세스와 거시적 개발 프로세스를 모두 활용하는 방법이다.","Use-Case를 강조해 사용하는 방법이다.","객체, 동적, 기능 모델로 나눠 수행하는 방법이다.","E-R 다이어그램을 사용해 객체의 행위를 데이터 모델링하는 데 초점을 두는 방법이다."],"ans":4,"exp":{"concept":"객체지향 분석 방법론에는 Rumbaugh, Booch, Jacobson, Coad-Yourdon, Wirfs-Brock 방법 등이 있다. Coad-Yourdon 방법은 E-R 다이어그램을 사용해 객체의 행위를 모델링하며, 객체 식별, 구조 식별, 주제 정의, 속성과 인스턴스 연결 정의, 연산과 메시지 연결 정의 순으로 분석한다.","choices":[{"verdict":"오답","why":"미시적(Micro) 개발 프로세스와 거시적(Macro) 개발 프로세스를 모두 사용하는 것은 Booch 방법이다."},{"verdict":"오답","why":"유스케이스(Use Case)를 강조해 사용하는 것은 Jacobson 방법이다."},{"verdict":"오답","why":"객체 모델링, 동적 모델링, 기능 모델링으로 나눠 수행하는 것은 Rumbaugh 방법(OMT)이다."},{"verdict":"정답","why":"E-R 다이어그램을 사용해 객체의 행위를 모델링하는 데 초점을 두는 것이 Coad-Yourdon 방법이다."}],"keywords":[{"term":"Rumbaugh(OMT)","desc":"객체 모델링 → 동적 모델링 → 기능 모델링 순으로 분석"},{"term":"Booch","desc":"미시적, 거시적 개발 프로세스를 모두 사용"},{"term":"Jacobson","desc":"유스케이스를 강조"},{"term":"Coad-Yourdon","desc":"E-R 다이어그램으로 객체의 행위를 모델링"},{"term":"Wirfs-Brock","desc":"분석과 설계 구분 없이 고객 명세서를 평가해 설계 작업까지 연속 수행"}],"memo":"Jacobson은 유스케이스(J-U), Coad-Yourdon은 E-R(코드-ER), Rumbaugh는 객체·동적·기능 3모델로 짝지어 외운다."}},{"id":"written-2024-1-18","no":18,"unit":"소프트웨어 설계","q":"UML 확장 모델에서 스테레오 타입 객체를 표현하기 위해 사용하는 기호로 옳은 것은?","choices":["[[ ]]","&lt;&lt; &gt;&gt;","{{ }}","(( ))"],"ans":2,"exp":{"concept":"스테레오타입(Stereotype)은 UML의 기본 요소에 추가로 의미를 붙여 확장하는 방법이다. 길러멧(Guillemet)이라 부르는 겹화살괄호 << >> 안에 이름을 적어 표현하며, <<include>>, <<extend>>, <<interface>> 등이 대표적이다.","choices":[{"verdict":"오답","why":"[[ ]]는 UML에서 스테레오타입을 표현하는 기호가 아니다."},{"verdict":"정답","why":"스테레오타입은 << >>(길러멧) 안에 이름을 적어 표현한다. 예: <<include>>, <<extend>>, <<interface>>."},{"verdict":"오답","why":"{{ }}는 UML에서 스테레오타입을 표현하는 기호가 아니다. 중괄호 { }는 제약 조건 표기에 쓴다."},{"verdict":"오답","why":"(( ))는 UML에서 스테레오타입을 표현하는 기호가 아니다."}],"keywords":[{"term":"스테레오타입(Stereotype)","desc":"UML 기본 요소에 의미를 추가해 확장하는 표현, << >> 사용"},{"term":"길러멧(Guillemet)","desc":"스테레오타입을 감싸는 겹화살괄호 << >>"},{"term":"<<include>>, <<extend>>","desc":"유스케이스 다이어그램의 포함 관계와 확장 관계 표기"}],"memo":"유스케이스의 <<include>>, <<extend>>를 떠올리면 스테레오타입 기호가 << >>임을 바로 알 수 있다."}},{"id":"written-2024-1-19","no":19,"unit":"소프트웨어 설계","q":"객체지향 소프트웨어를 설계할 때 디자인 패턴을 구성하는 요소로 보기 가장 어려운 것은?","choices":["재사용할 수 있는 샘플코드","개발자의 성명","실제로 적용된 사례","문제와 배경"],"ans":2,"exp":{"concept":"디자인 패턴은 문제와 해결책을 재사용할 수 있도록 일정한 형식으로 정리한 것이다. 그 구성 요소로는 패턴의 이름, 문제 및 배경, 해법(솔루션), 실제로 적용된 사례, 적용 결과, 재사용할 수 있는 샘플 코드 등이 있다. 요리 레시피에 요리 이름, 언제 쓰는지, 만드는 법, 예시 사진이 들어가는 것과 비슷하다.","choices":[{"verdict":"오답","why":"재사용할 수 있는 샘플 코드는 디자인 패턴의 구성 요소다."},{"verdict":"정답","why":"패턴을 만든 개발자의 성명은 패턴을 이해하고 적용하는 데 필요한 정보가 아니므로 디자인 패턴의 구성 요소가 아니다."},{"verdict":"오답","why":"실제로 적용된 사례는 디자인 패턴의 구성 요소다."},{"verdict":"오답","why":"패턴이 해결하려는 문제와 배경은 디자인 패턴의 구성 요소다."}],"keywords":[{"term":"디자인 패턴 구성 요소","desc":"패턴 이름, 문제 및 배경, 솔루션, 사례, 결과, 샘플 코드"},{"term":"GoF(Gang of Four)","desc":"디자인 패턴 23가지를 정리한 4명의 저자를 부르는 이름"}],"memo":"구성 요소는 '패턴을 쓰는 데 필요한 정보'다. 만든 사람 이름처럼 적용과 상관없는 것은 빠진다."}},{"id":"written-2024-1-20","no":20,"unit":"소프트웨어 설계","q":"사용자의 요구사항을 정확하게 파악하고자 실제 개발할 소프트웨어의 견본품을 만들어 최종 결과물을 예측하는 모형은?","choices":["프로토타입 모형","폭포수 모형","애자일 모형","나선형 모형"],"ans":1,"exp":{"concept":"프로토타입 모형은 실제 소프트웨어를 만들기 전에 견본품(시제품)을 먼저 만들어 사용자에게 보여 주고, 의견을 받아 요구사항을 정확히 파악하는 개발 모형이다. 집을 짓기 전에 모델하우스를 먼저 보여 주는 것과 같다.","choices":[{"verdict":"정답","why":"프로토타입 모형은 견본품(Prototype)을 만들어 최종 결과물을 미리 예측하고 사용자 요구사항을 정확히 파악하는 모형이다."},{"verdict":"오답","why":"폭포수 모형은 각 단계를 순서대로 진행하는 고전적 모형으로, 견본품을 만들지 않는다."},{"verdict":"오답","why":"애자일 모형은 고객과 협력하며 짧은 주기로 반복 개발해 변화에 대응하는 방식이다."},{"verdict":"오답","why":"나선형 모형은 계획 수립, 위험 분석, 개발 및 검증, 고객 평가를 반복하며 위험을 줄이는 모형이다."}],"keywords":[{"term":"프로토타입 모형(Prototype Model)","desc":"견본품을 만들어 사용자 요구를 확인하는 모형"},{"term":"폭포수 모형(Waterfall Model)","desc":"단계를 순차적으로 진행하는 고전적 모형"},{"term":"나선형 모형(Spiral Model)","desc":"위험 분석을 반복하며 점진적으로 개발하는 모형"}],"memo":"'견본품', '시제품', '미리 보여 준다'는 말이 나오면 프로토타입 모형이다."}},{"id":"written-2024-1-21","no":21,"unit":"소프트웨어 개발","q":"다음 Postfix 연산식의 연산 결과로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p><code>3 4 * 5 6 * +</code></p></div>","choices":["35","42","77","360"],"ans":2,"exp":{"concept":"후위 표기식(Postfix)은 연산자가 피연산자 뒤에 오는 표기법이다. 앞에서부터 읽으면서 숫자는 스택에 넣고, 연산자를 만나면 스택에서 숫자 두 개를 꺼내 계산한 뒤 결과를 다시 넣는다.","choices":[{"verdict":"오답","why":"35는 계산 결과가 아니다. 3*4=12, 5*6=30을 더하면 42다."},{"verdict":"정답","why":"3 4 *에서 3*4=12, 5 6 *에서 5*6=30, 마지막 +에서 12+30=42가 된다. 중위 표기로 바꾸면 (3*4)+(5*6)이다."},{"verdict":"오답","why":"77은 (3+4)*(5+6)=77처럼 연산자를 잘못 적용한 값이다. 정답은 42다."},{"verdict":"오답","why":"360은 3*4*5*6처럼 모두 곱한 값이다. 마지막 연산자는 +이므로 정답은 42다."}],"keywords":[{"term":"후위 표기법(Postfix)","desc":"연산자를 피연산자 뒤에 쓰는 표기, 예: A B +"},{"term":"중위 표기법(Infix)","desc":"연산자를 피연산자 사이에 쓰는 일반적인 표기, 예: A + B"},{"term":"전위 표기법(Prefix)","desc":"연산자를 피연산자 앞에 쓰는 표기, 예: + A B"}],"memo":"후위식은 '숫자 둘 다음 연산자'를 만나면 바로 계산해서 하나로 합친다."}},{"id":"written-2024-1-22","no":22,"unit":"소프트웨어 개발","q":"물리데이터 저장소의 파티션 설계에서 파티션 유형에 해당하지 않는 것은?","choices":["유닛 분할(Unit Partitioning)","범위 분할(Range Partitioning)","조합 분할(Composite Partitioning)","해시 분할(Hash Partitioning)"],"ans":1,"exp":{"concept":"파티션(Partition)은 큰 테이블을 작은 조각으로 나눠 저장해 성능과 관리 효율을 높이는 방법이다. 나누는 기준에 따라 값의 범위로 나누는 범위 분할, 해시 함수로 나누는 해시 분할, 값 목록으로 나누는 목록 분할, 두 방식을 섞는 조합 분할, 순서대로 돌아가며 나누는 라운드 로빈 분할이 있다.","choices":[{"verdict":"정답","why":"유닛 분할(Unit Partitioning)은 파티션 유형에 해당하지 않는다."},{"verdict":"오답","why":"범위 분할(Range Partitioning)은 날짜처럼 지정한 열 값의 범위를 기준으로 나누는 파티션 유형이다."},{"verdict":"오답","why":"조합 분할(Composite Partitioning)은 범위 분할 후 해시 분할을 하는 것처럼 두 가지 이상의 분할 방법을 조합하는 파티션 유형이다."},{"verdict":"오답","why":"해시 분할(Hash Partitioning)은 해시 함수 값에 따라 데이터를 고르게 나누는 파티션 유형이다."}],"keywords":[{"term":"범위 분할(Range)","desc":"지정한 열 값의 범위로 분할, 예: 월별·연도별"},{"term":"해시 분할(Hash)","desc":"해시 함수 값으로 분할해 데이터를 고르게 분산"},{"term":"목록 분할(List)","desc":"지정한 값의 목록을 기준으로 분할"},{"term":"조합 분할(Composite)","desc":"두 개 이상의 분할 기법을 조합"},{"term":"라운드 로빈 분할(Round Robin)","desc":"레코드를 순서대로 돌아가며 균등하게 분배"}],"memo":"파티션 유형은 '범위, 해시, 목록, 조합, 라운드 로빈'이다. '유닛'은 없다."}},{"id":"written-2024-1-23","no":23,"unit":"소프트웨어 개발","q":"소스 코드 정적 분석(Static Analysis)에 관한 설명 중 틀린 것은?","choices":["코드 분석은 하드웨어적인 방법으로만 가능하다.","자료 흐름이나 논리 흐름을 분석해 비정상적인 패턴을 찾아낼 수 있다.","소스 코드를 실행하지 않은 상태에서 분석한다.","코드에 존재하는 오류나 잠재적인 오류를 찾아내려는 활동이다."],"ans":1,"exp":{"concept":"정적 분석(Static Analysis)은 프로그램을 실행하지 않고 소스 코드 자체를 살펴 코딩 표준 위반, 오류나 잠재적 오류를 찾아내는 활동이다. 사람이 직접 검토하거나 소프트웨어 분석 도구로 자료 흐름과 논리 흐름을 분석한다. 반대로 프로그램을 실제로 실행하며 분석하는 것은 동적 분석이다.","choices":[{"verdict":"정답","why":"정적 분석은 하드웨어적인 방법으로만 하는 것이 아니라 사람의 검토나 정적 분석 도구 같은 소프트웨어로 수행한다."},{"verdict":"오답","why":"자료 흐름이나 논리 흐름을 분석해 비정상적인 패턴을 찾는 것은 정적 분석의 맞는 설명이다."},{"verdict":"오답","why":"정적 분석은 소스 코드를 실행하지 않고 분석한다. 맞는 설명이다."},{"verdict":"오답","why":"정적 분석은 코드에 있는 오류나 잠재적 오류를 찾아내는 활동이다. 맞는 설명이다."}],"keywords":[{"term":"정적 분석(Static Analysis)","desc":"프로그램을 실행하지 않고 소스 코드를 분석"},{"term":"동적 분석(Dynamic Analysis)","desc":"프로그램을 실행하면서 메모리 누수, 스레드 결함 등을 분석"},{"term":"정적 분석 도구","desc":"pmd, cppcheck, SonarQube, checkstyle 등"}],"memo":"정적(Static)은 '멈춰 있는 코드를 본다', 동적(Dynamic)은 '돌려 보며 본다'로 구분한다."}},{"id":"written-2024-1-24","no":24,"unit":"소프트웨어 개발","q":"아래 그래프에서 정점 A를 시작점으로 하여 깊이 우선 탐색(DFS)으로 운행했을 때의 결과는?<img class=\"q-img\" src=\"data/img/04f17e1b7c7d8d63fc9f25faae44358f.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["ABEFGCD","ABECDFG","ABECFDG","ABCDEFG"],"ans":1,"exp":{"concept":"깊이 우선 탐색(DFS, Depth First Search)은 시작 정점에서 갈 수 있는 이웃으로 계속 깊이 들어가다가, 더 갈 곳(방문하지 않은 이웃)이 없을 때에만 바로 전 정점으로 되돌아가는 방식이다. 미로에서 막다른 길이 나올 때까지 한 길로 쭉 가 보고, 막히면 돌아와 다른 길로 가는 것과 같다. 따라서 어떤 정점에 방문하지 않은 이웃이 남아 있으면 그 정점에서 되돌아갈 수 없다.","choices":[{"verdict":"정답","why":"A→B→E→F→G로 깊이 들어간 뒤, G는 F와만 연결되어 막다른 곳이므로 F로 되돌아가 F의 남은 이웃 C를 방문하고, C에서 D를 방문한다. 모든 이동이 그래프의 간선을 따르고 되돌아가는 규칙도 지키므로 DFS 결과가 될 수 있다."},{"verdict":"오답","why":"A→B→E까지 간 뒤 E에는 방문하지 않은 이웃 F가 남아 있는데 F로 가지 않고 C로 넘어갔다. E와 C는 연결되어 있지 않으므로 DFS 순서가 될 수 없다."},{"verdict":"오답","why":"A→B→E 다음에 E의 미방문 이웃 F를 두고 C로 넘어갔다. E와 C 사이에는 간선이 없으므로 DFS 순서가 될 수 없다."},{"verdict":"오답","why":"A→B→C→D 다음에 E로 갔지만 D와 E는 연결되어 있지 않고, D에는 방문하지 않은 이웃 F가 남아 있다. 이 순서는 DFS가 아니다."}],"keywords":[{"term":"깊이 우선 탐색(DFS)","desc":"한 방향으로 끝까지 들어간 뒤 되돌아오는 탐색, 스택(또는 재귀) 사용"},{"term":"너비 우선 탐색(BFS)","desc":"시작 정점과 가까운 이웃부터 차례로 방문하는 탐색, 큐 사용"},{"term":"백트래킹(Backtracking)","desc":"더 갈 곳이 없을 때 직전 정점으로 되돌아가는 것"}],"memo":"DFS 보기를 판별할 때는 '다음 정점이 현재 정점과 연결되어 있는가', '되돌아갈 때 미방문 이웃이 남아 있지 않은가' 두 가지를 확인한다.","doubt":"문제에 이웃 방문 순서가 정해져 있지 않다. 그림의 그래프(A-B, A-C, A-D, B-C, B-E, C-D, C-F, D-F, E-F, F-G)에서 이웃을 알파벳 순으로 방문하면 ABCDFEG가 되어 보기에 없고, 1번은 B에서 C보다 E를, F에서 C보다 G를 먼저 고른 순서다. 보기 중 DFS 규칙을 지키는 순서는 1번뿐이라 정답은 1번이다."}},{"id":"written-2024-1-25","no":25,"unit":"소프트웨어 개발","q":"반정규화(Denormalization) 유형 가운데 중복 테이블을 추가하는 방법에 해당되지 않는 것은?","choices":["집계 테이블의 추가","특정 부분만을 포함하는 테이블 추가","빌드 테이블의 추가","진행 테이블의 추가"],"ans":3,"exp":{"concept":"반정규화(Denormalization)는 정규화된 데이터 모델을 성능 향상을 위해 일부러 통합, 중복, 분리하는 작업이다. 그중 중복 테이블 추가 방법에는 합계 등을 미리 계산해 두는 집계 테이블, 이력 관리 등 진행 상황을 담는 진행 테이블, 자주 쓰는 일부 열만 모은 특정 부분만 포함하는 테이블 추가가 있다.","choices":[{"verdict":"오답","why":"집계 테이블 추가는 합계, 평균 등 집계 데이터를 위한 테이블을 별도로 두는 중복 테이블 추가 방법이다."},{"verdict":"오답","why":"특정 부분만을 포함하는 테이블 추가는 데이터가 많은 테이블에서 자주 쓰는 특정 부분만 따로 모은 테이블을 두는 중복 테이블 추가 방법이다."},{"verdict":"정답","why":"빌드 테이블 추가는 반정규화의 중복 테이블 추가 방법에 해당하지 않는다."},{"verdict":"오답","why":"진행 테이블 추가는 이력 관리 등의 목적으로 추가하는 중복 테이블 추가 방법이다."}],"keywords":[{"term":"반정규화(Denormalization)","desc":"성능 향상을 위해 정규화 원칙을 일부러 위배하는 작업"},{"term":"중복 테이블 추가 방법","desc":"집계 테이블, 진행 테이블, 특정 부분만을 포함하는 테이블 추가"},{"term":"반정규화 방법","desc":"테이블 통합, 테이블 분할, 중복 테이블 추가, 중복 속성 추가"}],"memo":"중복 테이블 추가는 '집계, 진행, 특정 부분' 세 가지다. '빌드'는 없다."}},{"id":"written-2024-1-26","no":26,"unit":"소프트웨어 개발","q":"소프트웨어 테스트에 대한 설명 중 틀린 것은?","choices":["블랙박스 테스트는 프로그램의 구조를 고려하지 않는 테스트이다.","화이트박스 테스트는 모듈의 논리적 구조를 체계적으로 점검할 수 있다.","테스트 케이스에는 일반적으로 시험 조건, 테스트 데이터, 예상 결과가 포함되어야 한다.","화이트박스 테스트에서 기본 경로(Basis Path)란 흐름 그래프의 시작 노드에서 종료 노드까지 서로 독립된 경로로서, 싸이클을 허용하지 않는 경로를 말한다."],"ans":4,"exp":{"concept":"블랙박스 테스트는 프로그램 내부를 보지 않고 입력과 출력만 보며 기능을 확인하고, 화이트박스 테스트는 프로그램 내부 구조와 논리 흐름을 보며 확인한다. 화이트박스 기법 중 기초 경로 검사에서 말하는 기본 경로(Basis Path)는 시작 노드에서 종료 노드까지 서로 독립된 경로로, 사이클은 최대 한 번만 지나도록 허용한다.","choices":[{"verdict":"오답","why":"블랙박스 테스트는 프로그램의 내부 구조를 고려하지 않고 명세(기능)를 기준으로 테스트한다. 맞는 설명이다."},{"verdict":"오답","why":"화이트박스 테스트는 모듈 안의 논리적 경로를 체계적으로 점검할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"테스트 케이스에는 일반적으로 테스트 조건, 테스트 데이터, 예상 결과가 포함된다. 맞는 설명이다."},{"verdict":"정답","why":"기본 경로는 시작 노드에서 종료 노드까지의 서로 독립된 경로로, 사이클을 허용하지 않는 것이 아니라 최대 한 번까지 허용한다."}],"keywords":[{"term":"블랙박스 테스트","desc":"내부 구조를 보지 않고 기능(입출력)을 검사, 예: 동치 분할, 경계값 분석"},{"term":"화이트박스 테스트","desc":"내부 논리 구조를 검사, 예: 기초 경로 검사, 제어 구조 검사"},{"term":"기본 경로(Basis Path)","desc":"시작부터 종료까지의 독립 경로, 사이클은 최대 한 번 허용"},{"term":"순환 복잡도(Cyclomatic Complexity)","desc":"독립 경로의 수, V(G) = E - N + 2"}],"memo":"기본 경로의 사이클은 '금지'가 아니라 '최대 한 번'이다."}},{"id":"written-2024-1-27","no":27,"unit":"소프트웨어 개발","q":"패키지 소프트웨어의 일반적인 제품 품질 요구사항과 테스트에 관한 국제 표준은 무엇인가?","choices":["ISO/IEC 14959","ISO/IEC 12119","ISO/IEC 2196","IEEE 19554"],"ans":2,"exp":{"concept":"ISO/IEC 12119는 패키지 소프트웨어의 품질 요구사항과 테스트에 관한 국제 표준이다. 소프트웨어 품질 관련 표준으로는 이 밖에 품질 특성을 정의한 ISO/IEC 9126, 9126을 이어받아 통합한 ISO/IEC 25000(SQuaRE), 소프트웨어 제품 평가 절차를 다룬 ISO/IEC 14598 등이 있다.","choices":[{"verdict":"오답","why":"ISO/IEC 14959는 패키지 소프트웨어 품질 표준이 아니다. 제품 평가 표준은 ISO/IEC 14598이므로 번호를 헷갈리지 않도록 한다."},{"verdict":"정답","why":"ISO/IEC 12119는 패키지 소프트웨어의 일반적인 제품 품질 요구사항과 테스트를 다루는 국제 표준이다."},{"verdict":"오답","why":"ISO/IEC 2196은 패키지 소프트웨어 품질 표준이 아니며, 출제 범위의 표준 번호가 아니다."},{"verdict":"오답","why":"IEEE 19554는 패키지 소프트웨어 품질 표준이 아니며, 출제 범위의 표준 번호가 아니다."}],"keywords":[{"term":"ISO/IEC 12119","desc":"패키지 소프트웨어 품질 요구사항 및 테스트 표준"},{"term":"ISO/IEC 9126","desc":"소프트웨어 품질 특성과 평가 표준, 기능성·신뢰성·사용성·효율성·유지보수성·이식성"},{"term":"ISO/IEC 14598","desc":"소프트웨어 제품 평가 절차 표준"},{"term":"ISO/IEC 25000(SQuaRE)","desc":"9126, 14598, 12119 등을 통합한 소프트웨어 품질 평가 통합 모델"}],"memo":"'패키지'는 12119, '품질 특성'은 9126, '평가 절차'는 14598로 짝지어 외운다."}},{"id":"written-2024-1-28","no":28,"unit":"소프트웨어 개발","q":"다음 중 형상 관리 도구의 주요 기능과 거리가 먼 것은?","choices":["커밋(commit)","체크아웃(Check-out)","체크인(Check-in)","정규화(Normalization)"],"ans":4,"exp":{"concept":"형상 관리(SCM)는 소프트웨어 개발 중 생기는 변경 사항을 관리하는 활동이고, 형상 관리 도구는 Git, SVN처럼 버전을 관리해 준다. 주요 기능으로는 저장소에서 파일을 가져오는 체크아웃, 수정한 파일을 저장소에 올리는 체크인, 변경 내용을 저장소에 반영하는 커밋 등이 있다.","choices":[{"verdict":"오답","why":"커밋(Commit)은 수정한 내용을 저장소에 최종 반영하는 형상 관리 도구의 주요 기능이다."},{"verdict":"오답","why":"체크아웃(Check-Out)은 저장소에서 파일을 받아오는 형상 관리 도구의 주요 기능이다."},{"verdict":"오답","why":"체크인(Check-In)은 체크아웃한 파일의 수정을 끝내고 저장소의 파일을 새 버전으로 갱신하는 형상 관리 도구의 주요 기능이다."},{"verdict":"정답","why":"정규화(Normalization)는 데이터베이스에서 이상 현상을 없애려고 릴레이션을 분해하는 과정으로, 형상 관리 도구의 기능과 관계가 없다."}],"keywords":[{"term":"체크아웃(Check-Out)","desc":"저장소에서 파일을 받아오는 것"},{"term":"체크인(Check-In)","desc":"수정한 파일을 저장소에 새 버전으로 갱신하는 것"},{"term":"커밋(Commit)","desc":"변경 내용을 저장소에 최종 반영하는 것"},{"term":"형상 관리 도구","desc":"Git, SVN, CVS 등"}],"memo":"형상 관리 도구 기능은 파일이 '들어가고 나가는' 동작(체크인, 체크아웃, 커밋)이다. 정규화는 DB 용어다."}},{"id":"written-2024-1-29","no":29,"unit":"소프트웨어 개발","q":"다음 중 디지털 저작권 관리(DRM)의 기술 요소에 해당하지 않는 것은?","choices":["암호화 기술","크랙 방지 기술","정책 관리 기술","방화벽 기술"],"ans":4,"exp":{"concept":"디지털 저작권 관리(DRM)는 디지털 콘텐츠를 허가받은 사람만 정해진 범위 안에서 쓰도록 보호하는 기술이다. 기술 요소로는 암호화, 키 관리, 암호화 파일 생성(Packager), 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증이 있다.","choices":[{"verdict":"오답","why":"암호화(Encryption) 기술은 콘텐츠와 라이선스를 암호화하고 전자 서명을 할 수 있게 하는 DRM 기술 요소다."},{"verdict":"오답","why":"크랙 방지(Tamper Resistance) 기술은 크랙에 의한 콘텐츠 사용 방지 기술로, DRM 기술 요소다."},{"verdict":"오답","why":"정책 관리(Policy Management) 기술은 라이선스 발급과 사용에 대한 정책을 표현하고 관리하는 DRM 기술 요소다."},{"verdict":"정답","why":"방화벽 기술은 내부 네트워크로 들어오는 트래픽을 걸러 외부 침입을 막는 네트워크 보안 기술로, DRM 기술 요소가 아니다."}],"keywords":[{"term":"DRM(Digital Rights Management)","desc":"디지털 콘텐츠의 사용 권한을 관리하고 보호하는 기술"},{"term":"DRM 기술 요소","desc":"암호화, 키 관리, 암호화 파일 생성, 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증"},{"term":"패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 배포 가능한 형태로 묶어 암호화하는 프로그램"}],"memo":"DRM은 '콘텐츠'를 지키는 기술이고 방화벽은 '네트워크'를 지키는 기술이다."}},{"id":"written-2024-1-30","no":30,"unit":"소프트웨어 개발","q":"다음 중 블랙박스 테스트 기법과 거리가 먼 것은?","choices":["경계값 분석","기초 경로 검사","동치 클래스 분해","원인 결과 그래프"],"ans":2,"exp":{"concept":"블랙박스 테스트는 프로그램 내부를 보지 않고 요구사항 명세만 보고 입력과 출력을 검사하는 테스트다. 기법으로는 동치 분할 검사, 경계값 분석, 원인-효과 그래프 검사, 오류 예측 검사, 비교 검사가 있다. 기초 경로 검사는 내부 논리 경로를 따지는 화이트박스 기법이다.","choices":[{"verdict":"오답","why":"경계값 분석(Boundary Value Analysis)은 입력 범위의 경계 근처 값을 집중적으로 테스트하는 블랙박스 기법이다."},{"verdict":"정답","why":"기초 경로 검사(Basis Path Testing)는 프로그램의 논리적 복잡성을 측정해 실행 경로를 정의하는 화이트박스 테스트 기법이다."},{"verdict":"오답","why":"동치 클래스 분해(동치 분할, Equivalence Partitioning)는 입력 데이터를 같은 결과를 내는 그룹으로 나눠 대표 값으로 테스트하는 블랙박스 기법이다."},{"verdict":"오답","why":"원인 결과 그래프(Cause-Effect Graph)는 입력 조건과 출력 결과의 관계를 그래프로 분석해 테스트 케이스를 만드는 블랙박스 기법이다."}],"keywords":[{"term":"블랙박스 테스트 기법","desc":"동치 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사"},{"term":"화이트박스 테스트 기법","desc":"기초 경로 검사, 제어 구조 검사(조건 검사, 루프 검사, 데이터 흐름 검사)"},{"term":"기초 경로 검사","desc":"순환 복잡도를 이용해 독립 경로를 모두 테스트하는 화이트박스 기법"}],"memo":"'경로', '조건', '루프'처럼 코드 내부 구조를 다루는 말이 들어가면 화이트박스다."}},{"id":"written-2024-1-31","no":31,"unit":"소프트웨어 개발","q":"여러 선택 항목 가운데 하나만 선택할 수 있는 경우에 사용하는 사용자 인터페이스(UI) 요소는?","choices":["체크 박스","라디오 버튼","텍스트 박스","토글 버튼"],"ans":2,"exp":{"concept":"사용자 인터페이스(UI) 요소는 화면에서 사용자가 값을 입력하거나 선택하게 해 주는 부품이다. 여러 항목 중 하나만 고를 때는 라디오 버튼, 여러 개를 동시에 고를 때는 체크 박스를 쓴다. 옛 라디오의 채널 버튼처럼 하나를 누르면 다른 것이 튀어나오는 데서 이름이 왔다.","choices":[{"verdict":"오답","why":"체크 박스(Check Box)는 여러 항목 중 두 개 이상을 동시에 선택할 수 있는 UI 요소다."},{"verdict":"정답","why":"라디오 버튼(Radio Button)은 여러 항목 중 하나만 선택할 수 있는 UI 요소다."},{"verdict":"오답","why":"텍스트 박스(Text Box)는 사용자가 글자를 직접 입력하는 UI 요소다."},{"verdict":"오답","why":"토글 버튼(Toggle Button)은 켜기와 끄기처럼 두 가지 상태를 번갈아 바꾸는 UI 요소다."}],"keywords":[{"term":"라디오 버튼(Radio Button)","desc":"여러 항목 중 하나만 선택"},{"term":"체크 박스(Check Box)","desc":"여러 항목 중 여러 개를 선택"},{"term":"토글 버튼(Toggle Button)","desc":"두 가지 상태(On/Off)를 전환"},{"term":"콤보 상자(Combo Box)","desc":"목록에서 선택하거나 직접 입력하는 요소"}],"memo":"'하나만' 고르면 라디오 버튼, '여러 개' 고르면 체크 박스다."}},{"id":"written-2024-1-32","no":32,"unit":"소프트웨어 개발","q":"외계인 코드(Alien Code)에 관한 설명으로 옳은 것은?","choices":["아주 오래되었거나 참고문서 또는 개발자가 없어서 유지보수 작업이 어려운 프로그램을 말한다.","오류가 없어서 디버깅 과정이 필요 없는 프로그램을 말한다.","프로그램의 로직이 복잡해 이해하기 어려운 프로그램을 말한다.","사용자가 직접 작성한 프로그램을 말한다."],"ans":1,"exp":{"concept":"외계인 코드(Alien Code)는 아주 오래되었거나 참고 문서나 개발자가 없어서 이해하고 유지보수하기가 매우 어려운 프로그램을 말한다. 외계인이 쓴 글처럼 아무도 읽을 수 없다는 뜻이다. 이를 막으려면 처음부터 문서화를 철저히 해야 한다.","choices":[{"verdict":"정답","why":"외계인 코드는 아주 오래되었거나 참고 문서 또는 개발자가 없어 유지보수 작업이 어려운 프로그램을 말한다."},{"verdict":"오답","why":"오류가 없어 디버깅이 필요 없는 프로그램을 가리키는 말이 아니다. 외계인 코드는 유지보수가 어려운 오래된 프로그램이다."},{"verdict":"오답","why":"로직이 복잡하게 얽혀 이해하기 어려운 코드는 스파게티 코드(Spaghetti Code)라고 부른다."},{"verdict":"오답","why":"사용자가 직접 작성한 프로그램을 가리키는 용어가 아니다."}],"keywords":[{"term":"외계인 코드(Alien Code)","desc":"오래되었거나 문서·개발자가 없어 유지보수가 어려운 프로그램"},{"term":"스파게티 코드(Spaghetti Code)","desc":"로직이 복잡하게 얽혀 이해하기 어려운 코드"},{"term":"레거시 시스템(Legacy System)","desc":"오래전에 개발되어 계속 쓰이고 있는 기존 시스템"}],"memo":"외계인 코드의 핵심 단서는 '오래됨'과 '문서·개발자 없음', 스파게티 코드의 단서는 '얽힌 로직'이다."}},{"id":"written-2024-1-33","no":33,"unit":"소프트웨어 개발","q":"가상의 사용자를 생성하여 테스트를 수행함으로써 애플리케이션의 처리량, 응답 시간, 경과 시간, 자원 사용률에 대한 성능 목표가 달성되었는지를 확인하는 테스트 자동화 도구는?","choices":["코드 기반 테스트 설계 도구","성능 테스트 도구","기능 테스트 수행 도구","명세 기반 테스트 설계 도구"],"ans":2,"exp":{"concept":"테스트 자동화 도구는 테스트를 사람 대신 도구로 수행하는 것으로, 용도에 따라 정적 분석 도구, 테스트 실행 도구, 성능 테스트 도구, 테스트 통제 도구 등이 있다. 성능 테스트 도구는 가상의 사용자를 많이 만들어 동시에 접속시키고, 처리량, 응답 시간, 경과 시간, 자원 사용률이 목표에 맞는지 확인한다.","choices":[{"verdict":"오답","why":"코드 기반 테스트 설계 도구는 소스 코드를 분석해 테스트 케이스를 설계하는 도구로, 가상 사용자를 만들어 성능을 측정하지 않는다."},{"verdict":"정답","why":"성능 테스트 도구는 가상의 사용자를 만들어 테스트를 수행하고 처리량, 응답 시간, 경과 시간, 자원 사용률 등 성능 목표 달성 여부를 확인한다."},{"verdict":"오답","why":"기능 테스트 수행 도구는 애플리케이션의 기능이 요구대로 동작하는지 검사하는 도구다."},{"verdict":"오답","why":"명세 기반 테스트 설계 도구는 요구사항 명세를 바탕으로 테스트 케이스를 설계하는 도구다."}],"keywords":[{"term":"성능 테스트 도구","desc":"가상 사용자를 만들어 처리량, 응답 시간, 경과 시간, 자원 사용률을 측정"},{"term":"정적 분석 도구","desc":"프로그램을 실행하지 않고 소스 코드를 분석"},{"term":"테스트 하네스 도구","desc":"테스트를 위해 필요한 환경과 드라이버, 스텁 등을 제공"}],"memo":"'가상 사용자'와 '처리량·응답 시간'이 보이면 성능 테스트 도구다."}},{"id":"written-2024-1-34","no":34,"unit":"소프트웨어 개발","q":"다음 중 인터페이스 구현 검증 도구에 해당하지 않는 것은?","choices":["xUnit","NTAF","STAF","ESB"],"ans":4,"exp":{"concept":"인터페이스 구현 검증 도구는 모듈이나 시스템 간 인터페이스가 제대로 동작하는지 테스트하는 도구다. xUnit, STAF, FitNesse, NTAF, Selenium, watir 등이 있다. ESB는 검증 도구가 아니라 시스템들을 연결해 주는 인터페이스 연계 방식이다.","choices":[{"verdict":"오답","why":"xUnit은 JUnit, CppUnit 등 여러 언어를 지원하는 단위 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"오답","why":"NTAF는 STAF와 FitNesse의 장점을 통합한 NHN의 테스트 자동화 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"오답","why":"STAF는 서비스 호출과 컴포넌트 재사용 등 다양한 환경을 지원하는 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"정답","why":"ESB(Enterprise Service Bus)는 애플리케이션 사이를 버스 형태로 연결해 표준 기반의 인터페이스를 제공하는 연계 솔루션으로, 검증 도구가 아니다."}],"keywords":[{"term":"인터페이스 구현 검증 도구","desc":"xUnit, STAF, FitNesse, NTAF, Selenium, watir"},{"term":"ESB(Enterprise Service Bus)","desc":"애플리케이션 간 연계를 버스 형태로 표준화해 제공하는 미들웨어 솔루션"},{"term":"Selenium","desc":"다양한 브라우저와 개발 언어를 지원하는 웹 애플리케이션 테스트 프레임워크"}],"memo":"검증 도구 목록 'xUnit, STAF, FitNesse, NTAF, Selenium, watir'에 없는 ESB는 '연계' 방식이다."}},{"id":"written-2024-1-35","no":35,"unit":"소프트웨어 개발","q":"이진 검색 알고리즘에 관한 설명 중 옳지 않은 것은?","choices":["비교를 거듭할 때마다 검색 대상 데이터의 수가 절반씩 줄어든다.","피보나치 수열에 따라 다음 비교 대상을 선정하여 검색을 수행한다.","검색 대상 데이터가 미리 정렬되어 있어야 한다.","탐색 효율이 좋으며 탐색 시간이 적게 걸린다."],"ans":2,"exp":{"concept":"이진 검색(Binary Search)은 정렬된 데이터의 가운데 값과 찾는 값을 비교해, 찾는 값이 있을 수 없는 절반을 버리며 범위를 줄여 가는 검색 방법이다. 사전에서 단어를 찾을 때 가운데를 펼쳐 앞쪽인지 뒤쪽인지 판단하는 것과 같다.","choices":[{"verdict":"오답","why":"가운데 값과 비교할 때마다 검색 범위가 절반으로 줄어든다. 이진 검색의 맞는 설명이다."},{"verdict":"정답","why":"피보나치 수열에 따라 비교 위치를 정하는 것은 피보나치 검색(Fibonacci Search)이다. 이진 검색은 중간 위치를 비교 대상으로 삼는다."},{"verdict":"오답","why":"이진 검색은 데이터가 미리 정렬되어 있어야 쓸 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"이진 검색은 비교 횟수가 적어 탐색 효율이 좋고 탐색 시간이 적게 걸린다. 맞는 설명이다."}],"keywords":[{"term":"이진 검색(Binary Search)","desc":"정렬된 데이터를 절반씩 나눠 검색, 시간 복잡도 O(log n)"},{"term":"피보나치 검색(Fibonacci Search)","desc":"피보나치 수열로 다음 비교 위치를 정하는 검색"},{"term":"순차 검색(Sequential Search)","desc":"처음부터 하나씩 비교하는 검색, 정렬이 필요 없음"}],"memo":"이진 검색의 조건은 '정렬'이고, 비교 위치는 '가운데'다."}},{"id":"written-2024-1-36","no":36,"unit":"소프트웨어 개발","q":"형상 관리의 개념 및 절차에 관한 설명 중 틀린 것은?","choices":["형상 감사는 형상 관리 계획대로 형상 관리가 진행되고 있는지, 형상 항목의 변경이 요구사항에 맞게 제대로 이뤄졌는지 등을 살펴보는 활동이다.","형상 식별은 형상 관리 계획을 바탕으로 형상 관리의 대상이 무엇인지를 식별하는 과정이다.","형상 통제 과정에서는 형상 목록의 변경 요구를 즉시 수용하고 반영해야 한다.","형상 관리를 통해 가시성과 추적성을 보장하여 소프트웨어의 생산성과 품질을 높일 수 있다."],"ans":3,"exp":{"concept":"형상 관리는 소프트웨어 개발 중 생기는 변경 사항을 관리하는 활동으로, 형상 식별, 형상 통제, 형상 감사, 형상 기록(상태 보고)의 절차로 이루어진다. 형상 통제는 변경 요청이 들어오면 바로 반영하지 않고, 형상 통제 위원회(CCB)가 검토하고 승인한 뒤에 반영하는 과정이다.","choices":[{"verdict":"오답","why":"형상 감사는 기준선(Baseline)의 무결성을 평가하고, 변경이 요구대로 제대로 이뤄졌는지 확인하는 활동이다. 맞는 설명이다."},{"verdict":"오답","why":"형상 식별은 형상 관리 대상에 이름과 관리 번호를 붙여 무엇을 관리할지 정하는 과정이다. 맞는 설명이다."},{"verdict":"정답","why":"형상 통제에서는 변경 요구를 즉시 수용하지 않는다. 형상 통제 위원회(CCB)의 검토와 승인을 거쳐 현재의 기준선에 반영한다."},{"verdict":"오답","why":"형상 관리는 변경 사항을 눈에 보이게(가시성) 하고 추적할 수 있게(추적성) 해서 생산성과 품질을 높인다. 맞는 설명이다."}],"keywords":[{"term":"형상 식별","desc":"관리 대상을 정하고 이름과 번호를 붙이는 활동"},{"term":"형상 통제","desc":"변경 요구를 검토·승인해 기준선에 반영하는 활동, 형상 통제 위원회(CCB)가 담당"},{"term":"형상 감사","desc":"기준선의 무결성과 변경의 적절성을 확인하는 활동"},{"term":"형상 기록(상태 보고)","desc":"변경 사항을 기록하고 보고하는 활동"}],"memo":"'통제'라는 이름처럼 변경은 마음대로 즉시 하지 않고 승인을 받아서 한다."}},{"id":"written-2024-1-37","no":37,"unit":"소프트웨어 개발","q":"피봇(pivot)을 사용하는 분할 정복(Divide and Conquer) 기반의 알고리즘으로, 최악의 경우 n(n-1)/2회의 비교가 필요한 정렬(Sort)은?","choices":["Bubble Sort","Insert Sort","Selection Sort","Quick Sort"],"ans":4,"exp":{"concept":"퀵 정렬(Quick Sort)은 기준 값인 피봇(Pivot)을 하나 정해, 피봇보다 작은 값은 왼쪽, 큰 값은 오른쪽으로 나눈 뒤 각 부분을 다시 같은 방식으로 정렬하는 분할 정복 알고리즘이다. 평균 시간 복잡도는 O(n log n)이지만, 피봇이 매번 최솟값이나 최댓값으로 잡히는 최악의 경우에는 n(n-1)/2회 비교가 필요해 O(n²)이 된다.","choices":[{"verdict":"오답","why":"버블 정렬은 이웃한 두 값을 비교해 교환하는 정렬이다. 비교 횟수는 n(n-1)/2회이지만 피봇이나 분할 정복을 쓰지 않는다."},{"verdict":"오답","why":"삽입 정렬은 이미 정렬된 부분에 새 값을 알맞은 위치에 끼워 넣는 정렬로, 피봇과 분할 정복을 쓰지 않는다."},{"verdict":"오답","why":"선택 정렬은 남은 값 중 최솟값을 찾아 맨 앞과 교환하는 정렬이다. 비교 횟수는 n(n-1)/2회이지만 피봇이나 분할 정복을 쓰지 않는다."},{"verdict":"정답","why":"퀵 정렬은 피봇을 기준으로 나누는 분할 정복 기반 정렬이며, 최악의 경우 n(n-1)/2회의 비교가 필요하다."}],"keywords":[{"term":"퀵 정렬(Quick Sort)","desc":"피봇 기준 분할 정복, 평균 O(n log n), 최악 O(n²)"},{"term":"피봇(Pivot)","desc":"분할의 기준이 되는 값"},{"term":"분할 정복(Divide and Conquer)","desc":"문제를 작게 나눠 해결한 뒤 결과를 합치는 방식"},{"term":"합병 정렬(Merge Sort)","desc":"분할 정복 기반이지만 피봇 대신 반으로 나눠 합치는 정렬, O(n log n)"}],"memo":"'피봇'이 나오면 퀵 정렬이다. 같은 분할 정복이라도 합병 정렬은 피봇을 쓰지 않는다."}},{"id":"written-2024-1-38","no":38,"unit":"소프트웨어 개발","q":"아래 트리에서 차수(Degree)와 단말 노드(Terminal Node)의 수를 바르게 나타낸 것은?<img class=\"q-img\" src=\"data/img/1b4356124f0eef450c4bb58a22da0bf3.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["차수 : 4, 단말 노드 : 4","차수 : 2, 단말 노드 : 4","차수 : 4, 단말 노드 : 8","차수 : 2, 단말 노드 : 8"],"ans":2,"exp":{"concept":"트리의 차수(Degree)는 각 노드가 가진 자식 수 중 가장 큰 값이고, 단말 노드(Terminal Node, 리프 노드)는 자식이 하나도 없는 노드다. 그림에서 노드마다 아래로 뻗은 가지를 세면 된다.","choices":[{"verdict":"오답","why":"자식이 가장 많은 노드도 자식이 2개이므로 차수는 4가 아니라 2다."},{"verdict":"정답","why":"A(B, C), C(E, F), E(G, H)가 각각 자식 2개, B(D)가 자식 1개이므로 트리의 차수는 2다. 자식이 없는 단말 노드는 D, G, H, F의 4개다."},{"verdict":"오답","why":"차수는 2이고 단말 노드는 4개다. 4와 8 모두 틀렸다."},{"verdict":"오답","why":"차수 2는 맞지만 단말 노드는 D, G, H, F의 4개이고, 8은 전체 노드 수다."}],"keywords":[{"term":"노드의 차수(Degree)","desc":"한 노드가 가진 자식(서브트리)의 수"},{"term":"트리의 차수","desc":"노드들의 차수 중 가장 큰 값"},{"term":"단말 노드(Terminal Node)","desc":"자식이 없는 노드, 리프(Leaf) 노드"},{"term":"트리의 깊이(Depth)","desc":"트리에서 가장 깊은 노드의 레벨"}],"memo":"트리의 차수는 '자식 수의 최댓값'이지 노드의 개수가 아니다. 전체 노드 수 8과 헷갈리지 않는다."}},{"id":"written-2024-1-39","no":39,"unit":"소프트웨어 개발","q":"다음 중 스택을 활용하는 연산과 거리가 먼 것은?","choices":["재귀 호출","깊이 우선 탐색","선택 정렬","후위 표현(Post-Fix Expression)의 연산"],"ans":3,"exp":{"concept":"스택(Stack)은 나중에 넣은 것을 먼저 꺼내는 후입선출(LIFO) 구조다. 함수 호출 시 돌아갈 위치를 저장하는 재귀 호출, 되돌아갈 정점을 기억하는 깊이 우선 탐색, 피연산자를 쌓아 두고 계산하는 후위 표기식 연산 등에 쓰인다.","choices":[{"verdict":"오답","why":"재귀 호출은 함수가 호출될 때마다 복귀 주소와 지역 변수를 스택에 쌓으므로 스택을 활용한다."},{"verdict":"오답","why":"깊이 우선 탐색은 되돌아갈 정점을 스택(또는 재귀)으로 기억하므로 스택을 활용한다."},{"verdict":"정답","why":"선택 정렬은 배열에서 최솟값을 찾아 앞자리와 교환하는 과정을 반복할 뿐, 스택을 활용하지 않는다."},{"verdict":"오답","why":"후위 표기식 연산은 피연산자를 스택에 넣었다가 연산자를 만나면 꺼내 계산하므로 스택을 활용한다."}],"keywords":[{"term":"스택(Stack)","desc":"후입선출(LIFO) 구조, Push와 Pop 연산"},{"term":"큐(Queue)","desc":"선입선출(FIFO) 구조, 너비 우선 탐색이나 작업 스케줄링에 활용"},{"term":"스택의 응용","desc":"재귀 호출, 깊이 우선 탐색, 후위 표기식 연산, 서브루틴 복귀 주소 저장, 인터럽트 처리"}],"memo":"DFS는 스택, BFS는 큐로 짝지어 외운다."}},{"id":"written-2024-1-40","no":40,"unit":"소프트웨어 개발","q":"일반적으로 테스트 케이스에 포함되는 항목이 아닌 것은?","choices":["테스트 데이터","테스트 조건","테스트 비용","예상 결과"],"ans":3,"exp":{"concept":"테스트 케이스(Test Case)는 소프트웨어가 요구사항대로 동작하는지 확인하기 위해 설계한 입력 값, 실행 조건, 기대 결과의 묶음이다. 일반적으로 테스트 조건, 테스트 데이터, 예상 결과가 포함되며, 비용은 테스트 케이스의 구성 항목이 아니다.","choices":[{"verdict":"오답","why":"테스트 데이터는 테스트에 사용할 입력 값으로, 테스트 케이스에 포함되는 항목이다."},{"verdict":"오답","why":"테스트 조건은 테스트를 수행하기 위한 전제 조건과 환경으로, 테스트 케이스에 포함되는 항목이다."},{"verdict":"정답","why":"테스트 비용은 테스트 계획이나 프로젝트 관리에서 다루는 것으로, 테스트 케이스의 구성 항목이 아니다."},{"verdict":"오답","why":"예상 결과는 테스트를 실행했을 때 나와야 하는 결과로, 테스트 케이스에 포함되는 항목이다."}],"keywords":[{"term":"테스트 케이스(Test Case)","desc":"입력 값, 실행 조건, 기대 결과로 구성된 테스트 항목 명세"},{"term":"테스트 오라클(Test Oracle)","desc":"테스트 결과가 맞는지 판단하는 기준"},{"term":"테스트 시나리오(Test Scenario)","desc":"테스트 케이스를 실행 순서에 따라 묶은 것"}],"memo":"테스트 케이스는 '조건, 데이터, 예상 결과' 세 가지다. 돈(비용)은 들어가지 않는다."}},{"id":"written-2024-1-41","no":41,"unit":"데이터베이스 구축","q":"릴레이션 R은 차수가 4, 카디널리티가 5이고 릴레이션 S는 차수가 6, 카디널리티가 7일 때, 이 두 릴레이션을 카티션 프로덕트하여 얻은 새로운 릴레이션의 차수와 카디널리티는 각각 얼마인가?","choices":["24, 35","24, 12","10, 35","10, 12"],"ans":3,"exp":{"concept":"카티션 프로덕트(Cartesian Product, 교차곱)는 두 릴레이션의 튜플을 가능한 모든 조합으로 연결하는 연산이다. 결과 릴레이션의 차수(속성 수)는 두 릴레이션의 차수를 더한 값이고, 카디널리티(튜플 수)는 두 릴레이션의 카디널리티를 곱한 값이다.","choices":[{"verdict":"오답","why":"24는 차수를 곱한 값(4×6)이다. 차수는 더해야 하므로 10이다."},{"verdict":"오답","why":"차수를 곱하고 카디널리티를 더해 거꾸로 계산했다. 차수는 4+6=10, 카디널리티는 5×7=35다."},{"verdict":"정답","why":"차수는 4+6=10, 카디널리티는 5×7=35다."},{"verdict":"오답","why":"차수 10은 맞지만, 카디널리티는 더하는 것이 아니라 곱해서 5×7=35다."}],"keywords":[{"term":"차수(Degree)","desc":"릴레이션의 속성(열) 개수"},{"term":"카디널리티(Cardinality)","desc":"릴레이션의 튜플(행) 개수"},{"term":"카티션 프로덕트(×)","desc":"두 릴레이션의 모든 튜플 조합, 차수는 합, 카디널리티는 곱"}],"memo":"카티션 프로덕트는 '차수는 더하고, 카디널리티는 곱한다'. 열은 옆으로 붙고 행은 모든 조합이 생긴다고 생각한다."}},{"id":"written-2024-1-42","no":42,"unit":"데이터베이스 구축","q":"데이터 사전에 관한 설명 중 틀린 것은?","choices":["데이터 사전의 데이터에 실제로 접근하는 데 필요한 위치 정보는 데이터 디렉토리(Data Directory)라는 곳에서 관리된다.","데이터베이스에 대한 데이터인 메타데이터(Metadata)를 저장한다.","시스템 카탈로그 또는 시스템 데이터베이스라고도 부른다.","데이터 사전도 데이터베이스의 일종이므로 일반 사용자가 생성, 유지 및 수정을 할 수 있다."],"ans":4,"exp":{"concept":"데이터 사전(Data Dictionary)은 데이터베이스 안의 모든 객체(테이블, 뷰, 인덱스, 사용자 등)에 대한 정보, 즉 데이터에 대한 데이터인 메타데이터를 저장하는 곳이다. 시스템 카탈로그라고도 하며, DBMS가 스스로 생성하고 유지한다. 일반 사용자는 내용을 조회(검색)만 할 수 있고 직접 수정할 수는 없다.","choices":[{"verdict":"오답","why":"데이터 사전의 데이터에 실제로 접근하는 데 필요한 위치 정보는 데이터 디렉토리(Data Directory)에서 관리한다. 맞는 설명이다."},{"verdict":"오답","why":"데이터 사전은 데이터에 대한 데이터인 메타데이터를 저장한다. 맞는 설명이다."},{"verdict":"오답","why":"데이터 사전은 시스템 카탈로그 또는 시스템 데이터베이스라고도 부른다. 맞는 설명이다."},{"verdict":"정답","why":"데이터 사전은 DBMS가 스스로 생성하고 유지하며, 일반 사용자는 SQL로 검색만 할 수 있고 직접 생성, 수정할 수는 없다."}],"keywords":[{"term":"데이터 사전(Data Dictionary)","desc":"메타데이터를 저장하는 시스템 데이터베이스, 시스템 카탈로그"},{"term":"메타데이터(Metadata)","desc":"데이터에 대한 데이터, 데이터를 설명하는 정보"},{"term":"데이터 디렉토리(Data Directory)","desc":"데이터 사전에 접근하는 데 필요한 정보를 관리하며 시스템만 접근 가능"}],"memo":"데이터 사전은 '시스템이 관리하고 사용자는 읽기만' 한다."}},{"id":"written-2024-1-43","no":43,"unit":"데이터베이스 구축","q":"정규화에 관한 설명 중 적절하지 않은 것은?","choices":["데이터베이스의 개념적 설계 단계보다 앞서 수행한다.","데이터를 삽입할 때 릴레이션을 재구성해야 할 필요성을 줄인다.","중복을 배제함으로써 삽입, 삭제, 갱신 이상이 발생하는 것을 방지한다.","데이터 구조의 안정성을 최대한 높인다."],"ans":1,"exp":{"concept":"정규화(Normalization)는 하나의 릴레이션에 섞여 있는 데이터를 여러 릴레이션으로 나눠 중복을 없애고, 삽입·삭제·갱신 이상을 막는 과정이다. 데이터베이스 설계는 요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 순으로 진행되며, 정규화는 논리적 설계 단계에서 수행한다.","choices":[{"verdict":"정답","why":"정규화는 개념적 설계보다 앞서 수행하는 것이 아니라 논리적 설계 단계에서 수행한다."},{"verdict":"오답","why":"정규화로 릴레이션을 잘 나눠 두면 새 데이터를 삽입할 때 릴레이션을 재구성할 필요가 줄어든다. 맞는 설명이다."},{"verdict":"오답","why":"정규화는 중복을 없애 삽입, 삭제, 갱신 이상이 생기는 것을 막는다. 맞는 설명이다."},{"verdict":"오답","why":"정규화는 데이터 구조의 안정성을 최대화하는 것을 목적으로 한다. 맞는 설명이다."}],"keywords":[{"term":"정규화(Normalization)","desc":"중복을 줄이고 이상 현상을 없애기 위해 릴레이션을 분해하는 과정"},{"term":"이상(Anomaly)","desc":"중복 때문에 생기는 삽입 이상, 삭제 이상, 갱신 이상"},{"term":"데이터베이스 설계 순서","desc":"요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현"}],"memo":"정규화는 '논리적 설계' 단계다. 개념적 설계(E-R 모델)를 만든 다음 릴레이션으로 바꾸면서 정규화한다."}},{"id":"written-2024-1-44","no":44,"unit":"데이터베이스 구축","q":"두 테이블을 조인하여 뷰 V_1을 정의한 뒤, V_1을 이용해 뷰 V_2를 정의하였다. 다음 명령을 수행한 결과로 옳은 것은?<pre class=\"q-sql\"><code class=\"language-sql\">DROP VIEW V_1 CASCADE;</code></pre>","choices":["V_1만 삭제된다.","V_2만 삭제된다.","V_1과 V_2가 모두 삭제된다.","V_1과 V_2 모두 삭제되지 않는다."],"ans":3,"exp":{"concept":"뷰(View)는 다른 테이블이나 뷰를 바탕으로 만든 가상 테이블이다. DROP VIEW에 CASCADE 옵션을 붙이면 삭제할 뷰뿐 아니라 그 뷰를 참조하는 다른 뷰나 제약 조건까지 연쇄적으로 함께 삭제된다. RESTRICT 옵션은 참조하는 객체가 있으면 삭제를 취소한다.","choices":[{"verdict":"오답","why":"CASCADE 옵션은 V_1을 참조하는 객체까지 함께 삭제하므로 V_1만 삭제되지 않는다. V_1만 삭제되는 것은 V_1을 참조하는 객체가 없을 때의 결과다."},{"verdict":"오답","why":"삭제 대상은 V_1이므로 V_1이 남고 V_2만 삭제되는 일은 없다."},{"verdict":"정답","why":"CASCADE 옵션에 따라 V_1이 삭제되고, V_1을 이용해 정의한 V_2도 연쇄적으로 함께 삭제된다."},{"verdict":"오답","why":"모두 삭제되지 않는 것은 RESTRICT 옵션을 썼을 때 V_1을 참조하는 V_2가 있어 삭제가 취소되는 경우다."}],"keywords":[{"term":"CASCADE","desc":"삭제할 요소를 참조하는 다른 요소까지 연쇄적으로 함께 삭제"},{"term":"RESTRICT","desc":"다른 개체가 참조 중이면 삭제를 취소"},{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"}],"memo":"CASCADE는 '폭포처럼 연쇄적으로', RESTRICT는 '제한해서 막는다'로 기억한다."}},{"id":"written-2024-1-45","no":45,"unit":"데이터베이스 구축","q":"다음 설명에 해당하는 스키마(Schema)는 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>데이터베이스 전체를 정의한 것으로, 데이터 개체, 관계, 제약조건, 접근권한, 무결성 규칙 등을 명세한 것</p></div>","choices":["내부 스키마","내용 스키마","외부 스키마","개념 스키마"],"ans":4,"exp":{"concept":"스키마(Schema)는 데이터베이스의 구조와 제약 조건을 정의한 것으로, 보는 관점에 따라 외부, 개념, 내부 스키마로 나눈다. 개념 스키마는 조직 전체의 관점에서 데이터베이스 전체를 정의한 것으로, 개체, 관계, 제약 조건, 접근 권한, 무결성 규칙 등을 명세한다. 하나의 데이터베이스에는 개념 스키마가 하나만 존재한다.","choices":[{"verdict":"오답","why":"내부 스키마는 물리적 저장 장치 관점에서 레코드 형식, 인덱스 유무, 저장 순서 등 실제로 저장되는 방법을 정의한다."},{"verdict":"오답","why":"내용 스키마는 3단계 스키마에 해당하지 않으며, 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"외부 스키마는 사용자나 응용 프로그래머 각자의 관점에서 필요한 데이터베이스의 일부를 정의한 것으로, 서브 스키마라고도 한다."},{"verdict":"정답","why":"개념 스키마는 데이터베이스 전체를 정의한 것으로, 데이터 개체, 관계, 제약 조건, 접근 권한, 무결성 규칙 등을 명세한다."}],"keywords":[{"term":"외부 스키마(External Schema)","desc":"사용자 관점에서 본 데이터베이스의 일부, 서브 스키마"},{"term":"개념 스키마(Conceptual Schema)","desc":"조직 전체 관점의 데이터베이스 전체 정의, 데이터베이스당 하나"},{"term":"내부 스키마(Internal Schema)","desc":"물리적 저장 장치 관점의 저장 구조 정의"}],"memo":"'전체'라는 말이 나오면 개념 스키마, '사용자 각자'는 외부, '물리적 저장'은 내부 스키마다."}},{"id":"written-2024-1-46","no":46,"unit":"데이터베이스 구축","q":"조건을 만족하는 릴레이션의 수평적 부분집합을 구성하며, 연산자 기호로 그리스 문자 시그마(σ )를 사용하는 관계대수 연산은?","choices":["Division","Project","Join","Select"],"ans":4,"exp":{"concept":"관계대수의 셀렉트(Select) 연산은 조건을 만족하는 튜플(행)만 골라내는 연산으로, 표를 가로로 잘라내는 수평적 부분집합을 만든다. 기호는 그리스 문자 시그마(σ)를 쓴다. 반면 프로젝트(Project)는 원하는 속성(열)만 골라내는 수직적 부분집합이며 기호는 파이(π)다.","choices":[{"verdict":"오답","why":"디비전(Division, ÷)은 한 릴레이션이 다른 릴레이션의 모든 값을 포함하는 튜플을 구하는 연산이다."},{"verdict":"오답","why":"프로젝트(Project, π)는 원하는 속성만 추출하는 수직적 부분집합 연산이다."},{"verdict":"오답","why":"조인(Join, ⋈)은 공통 속성을 기준으로 두 릴레이션을 하나로 합치는 연산이다."},{"verdict":"정답","why":"셀렉트(Select)는 조건을 만족하는 튜플만 골라내는 수평적 부분집합 연산이며, 기호는 시그마(σ)다."}],"keywords":[{"term":"Select(σ)","desc":"조건에 맞는 튜플을 추출, 수평적 부분집합"},{"term":"Project(π)","desc":"지정한 속성을 추출, 수직적 부분집합"},{"term":"Join(⋈)","desc":"공통 속성으로 두 릴레이션을 합침"},{"term":"Division(÷)","desc":"다른 릴레이션의 모든 값을 포함하는 튜플을 추출"}],"memo":"σ는 영어 s(Select)에 해당하는 그리스 문자, π는 p(Project)에 해당하는 그리스 문자다."}},{"id":"written-2024-1-47","no":47,"unit":"데이터베이스 구축","q":"뷰(View)에 관한 설명 중 옳지 않은 것은?","choices":["뷰는 저장장치 내에 물리적으로 존재하고 있다.","뷰는 데이터의 논리적 독립성을 제공해 준다.","뷰를 제거할 때는 DROP 문을 사용한다.","뷰는 CREATE 문으로 정의한다."],"ans":1,"exp":{"concept":"뷰(View)는 하나 이상의 기본 테이블에서 유도된, 이름을 가진 가상 테이블이다. 실제 데이터를 따로 저장하지 않고 정의(질의문)만 저장해 두었다가 사용할 때 기본 테이블에서 데이터를 가져온다. CREATE로 만들고 DROP으로 지우며, ALTER로 정의를 바꿀 수 없다.","choices":[{"verdict":"정답","why":"뷰는 저장 장치 내에 물리적으로 존재하지 않는 가상 테이블이다. 정의만 저장되고 데이터는 기본 테이블에 있다."},{"verdict":"오답","why":"뷰는 기본 테이블 구조가 바뀌어도 응용 프로그램에 영향을 덜 주므로 데이터의 논리적 독립성을 제공한다. 맞는 설명이다."},{"verdict":"오답","why":"뷰는 DROP VIEW 문으로 제거한다. 맞는 설명이다."},{"verdict":"오답","why":"뷰는 CREATE VIEW 문으로 정의한다. 맞는 설명이다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블, 물리적으로 존재하지 않음"},{"term":"논리적 독립성","desc":"논리 구조가 바뀌어도 응용 프로그램에 영향을 주지 않는 성질"},{"term":"뷰의 특징","desc":"ALTER로 변경 불가, 변경하려면 삭제 후 재생성, 삽입·삭제·갱신 연산에 제약"}],"memo":"뷰는 '가상' 테이블이다. 물리적으로 존재한다는 보기는 틀린다."}},{"id":"written-2024-1-48","no":48,"unit":"데이터베이스 구축","q":"데이터베이스 설계 단계 가운데 저장 레코드 양식 설계, 레코드 집중의 분석 및 설계, 접근 경로 설계와 관련된 단계는?","choices":["물리적 설계","개념적 설계","논리적 설계","요구 조건 분석"],"ans":1,"exp":{"concept":"데이터베이스 설계는 요구 조건 분석, 개념적 설계, 논리적 설계, 물리적 설계, 구현 순으로 진행된다. 물리적 설계는 논리적 구조를 실제 저장 장치에 어떻게 저장할지 정하는 단계로, 저장 레코드 양식, 레코드 집중(클러스터링)의 분석 및 설계, 접근 경로(인덱스) 설계 등을 한다.","choices":[{"verdict":"정답","why":"물리적 설계는 저장 레코드 양식 설계, 레코드 집중의 분석 및 설계, 접근 경로 설계 등 실제 저장 구조를 정하는 단계다."},{"verdict":"오답","why":"개념적 설계는 현실 세계를 추상화해 E-R 다이어그램 같은 개념 스키마를 만드는 단계다."},{"verdict":"오답","why":"논리적 설계는 개념 스키마를 특정 DBMS가 처리할 수 있는 논리 스키마(릴레이션)로 바꾸고 정규화하는 단계다."},{"verdict":"오답","why":"요구 조건 분석은 사용자가 데이터베이스에 바라는 요구 사항을 수집하고 분석해 명세서를 작성하는 단계다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, DBMS에 독립적인 개념 스키마 모델링"},{"term":"논리적 설계","desc":"특정 DBMS에 맞는 논리 스키마 설계, 정규화 수행"},{"term":"물리적 설계","desc":"저장 레코드 양식, 레코드 집중, 접근 경로 설계"},{"term":"구현","desc":"DDL로 데이터베이스 스키마를 생성"}],"memo":"'저장', '접근 경로', '레코드 양식'처럼 실제 디스크와 관련된 말이 나오면 물리적 설계다."}},{"id":"written-2024-1-49","no":49,"unit":"데이터베이스 구축","q":"프로세스와 테이블 사이에 매트릭스를 만들어, 데이터베이스에 영향을 주는 생성, 읽기, 갱신, 삭제 연산으로 트랜잭션을 분석하는 것은?","choices":["일치 분석","CRUD 분석","CASE 분석","연관성 분석"],"ans":2,"exp":{"concept":"CRUD 분석은 프로세스(업무)와 테이블 사이에 매트릭스(표)를 만들고, 각 칸에 생성(Create), 읽기(Read), 갱신(Update), 삭제(Delete) 중 어떤 연산이 일어나는지 표시해 트랜잭션을 분석하는 방법이다. 이를 통해 테이블에 몰리는 부하나 빠진 연산을 찾을 수 있다.","choices":[{"verdict":"오답","why":"일치 분석은 프로세스와 테이블 간 CRUD 매트릭스로 트랜잭션을 분석하는 방법의 이름이 아니다."},{"verdict":"정답","why":"CRUD 분석은 프로세스와 테이블 사이에 매트릭스를 만들어 생성, 읽기, 갱신, 삭제 연산으로 트랜잭션을 분석하는 방법이다."},{"verdict":"오답","why":"CASE(Computer-Aided Software Engineering)는 소프트웨어 개발 과정을 도구로 자동화하는 것으로, 트랜잭션 분석 기법이 아니다."},{"verdict":"오답","why":"연관성 분석은 데이터 항목 간의 연관 규칙을 찾는 데이터 마이닝 기법으로, CRUD 매트릭스 분석이 아니다."}],"keywords":[{"term":"CRUD","desc":"Create(생성), Read(읽기), Update(갱신), Delete(삭제)"},{"term":"CRUD 매트릭스","desc":"프로세스와 테이블 사이에 CRUD 연산을 표시한 표"},{"term":"트랜잭션 분석","desc":"업무 처리에서 발생하는 트랜잭션의 양과 특성을 분석하는 것"}],"memo":"C, R, U, D 네 글자가 문제의 '생성, 읽기, 갱신, 삭제'와 정확히 대응한다."}},{"id":"written-2024-1-50","no":50,"unit":"데이터베이스 구축","q":"데이터 모델에 표시해야 하는 요소와 거리가 먼 것은?","choices":["출력 구조","논리적 데이터 구조","제약 조건","연산"],"ans":1,"exp":{"concept":"데이터 모델은 현실 세계의 정보를 컴퓨터가 다룰 수 있게 단순화해 표현한 것이다. 데이터 모델에 표시해야 할 요소는 논리적으로 표현된 개체 타입과 그 관계인 구조(Structure), 실제 데이터를 처리하는 방법인 연산(Operation), 데이터에 대한 논리적 제약인 제약 조건(Constraint)의 세 가지다.","choices":[{"verdict":"정답","why":"출력 구조는 데이터 모델의 구성 요소가 아니다. 데이터 모델에 표시할 요소는 구조, 연산, 제약 조건이다."},{"verdict":"오답","why":"논리적 데이터 구조는 데이터 모델에 표시해야 하는 요소인 구조(Structure)에 해당한다."},{"verdict":"오답","why":"제약 조건은 저장될 수 있는 실제 데이터의 논리적 제약으로, 데이터 모델에 표시해야 하는 요소다."},{"verdict":"오답","why":"연산은 데이터베이스에 저장된 실제 데이터를 처리하는 방법으로, 데이터 모델에 표시해야 하는 요소다."}],"keywords":[{"term":"구조(Structure)","desc":"개체 타입들 간의 관계, 데이터 구조와 정적 성질 표현"},{"term":"연산(Operation)","desc":"저장된 데이터를 처리하는 작업, 데이터 모델의 동적 성질"},{"term":"제약 조건(Constraint)","desc":"저장될 수 있는 데이터에 대한 논리적 제약"}],"memo":"데이터 모델 3요소는 '구조, 연산, 제약 조건'이다. '출력'은 없다."}},{"id":"written-2024-1-51","no":51,"unit":"데이터베이스 구축","q":"관계 데이터 모델의 무결성 제약 가운데, 기본키를 이루는 속성 값이 널(Null) 값이 아닌 원자 값을 가져야 한다는 성질은?","choices":["개체 무결성","튜플의 유일성","참조 무결성","도메인 무결성"],"ans":1,"exp":{"concept":"무결성(Integrity)은 데이터베이스에 저장된 데이터가 정확하고 일관된 상태를 유지하는 성질이다. 그중 개체 무결성은 기본키를 이루는 속성은 널(Null) 값이나 중복 값을 가질 수 없다는 규칙이다. 학번이 기본키라면 학번이 비어 있는 학생은 등록될 수 없는 것과 같다.","choices":[{"verdict":"정답","why":"개체 무결성(Entity Integrity)은 기본키를 구성하는 속성 값이 널 값이나 중복 값을 가질 수 없다는 제약이다."},{"verdict":"오답","why":"튜플의 유일성은 릴레이션 안의 튜플이 모두 서로 달라야 한다는 릴레이션의 특성으로, 기본키의 널 값 금지를 말하는 무결성 제약의 이름이 아니다."},{"verdict":"오답","why":"참조 무결성(Referential Integrity)은 외래키 값이 참조하는 릴레이션의 기본키 값이거나 널이어야 한다는 제약이다."},{"verdict":"오답","why":"도메인 무결성(Domain Integrity)은 속성 값이 정해진 도메인(허용 범위)에 속해야 한다는 제약이다."}],"keywords":[{"term":"개체 무결성","desc":"기본키는 널 값이나 중복 값을 가질 수 없다"},{"term":"참조 무결성","desc":"외래키 값은 참조 릴레이션의 기본키 값이거나 널이어야 한다"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인에 속한 값이어야 한다"}],"memo":"'기본키'가 나오면 개체 무결성, '외래키'가 나오면 참조 무결성이다."}},{"id":"written-2024-1-52","no":52,"unit":"데이터베이스 구축","q":"데이터베이스에서 하나의 논리적 기능을 수행하기 위한 작업의 단위, 또는 한꺼번에 모두 수행되어야 하는 일련의 연산들을 뜻하는 것은?","choices":["카디널리티","튜플","뷰","트랜잭션"],"ans":4,"exp":{"concept":"트랜잭션(Transaction)은 데이터베이스에서 하나의 논리적 기능을 수행하는 작업 단위로, 그 안의 연산들은 모두 실행되거나 하나도 실행되지 않아야 한다. 계좌 이체에서 '내 계좌 출금'과 '상대 계좌 입금'은 한 묶음이라 둘 중 하나만 처리되면 안 되는 것과 같다.","choices":[{"verdict":"오답","why":"카디널리티(Cardinality)는 릴레이션에 있는 튜플(행)의 개수다."},{"verdict":"오답","why":"튜플(Tuple)은 릴레이션을 구성하는 각각의 행이다."},{"verdict":"오답","why":"뷰(View)는 기본 테이블에서 유도된 가상 테이블이다."},{"verdict":"정답","why":"트랜잭션은 하나의 논리적 기능을 수행하기 위한 작업의 단위이자, 한꺼번에 모두 수행되어야 할 일련의 연산들이다."}],"keywords":[{"term":"트랜잭션(Transaction)","desc":"하나의 논리적 기능을 수행하는 작업 단위"},{"term":"트랜잭션의 특성(ACID)","desc":"원자성(Atomicity), 일관성(Consistency), 독립성(Isolation), 지속성(Durability)"},{"term":"원자성(Atomicity)","desc":"트랜잭션의 연산은 모두 반영되거나 전혀 반영되지 않아야 한다"}],"memo":"'작업 단위', '한꺼번에 모두 수행'이라는 단서는 트랜잭션이다."}},{"id":"written-2024-1-53","no":53,"unit":"데이터베이스 구축","q":"DBA가 사용자 PARK에게 테이블 [STUDENT]의 데이터를 갱신할 수 있는 객체 권한을 부여하는 SQL문을 작성하려고 한다. 다음 SQL문의 빈칸에 들어갈 내용으로 알맞은 것은?<pre class=\"q-sql\"><code>SQL&gt;GRANT <u> ㉠ </u> <u> ㉡ </u> STUDENT TO PARK;</code></pre>","choices":["㉠ ALTER, ㉡ TO","㉠ UPDATE, ㉡ ON","㉠ REPLACE, ㉡ IN","㉠ INSERT, ㉡ INTO"],"ans":2,"exp":{"concept":"GRANT는 사용자에게 권한을 주는 DCL(데이터 제어어) 명령이다. 형식은 'GRANT 권한 ON 대상 TO 사용자'다. 테이블의 데이터를 갱신하는 권한은 UPDATE이므로 GRANT UPDATE ON STUDENT TO PARK; 가 된다.","choices":[{"verdict":"오답","why":"ALTER는 테이블 구조를 변경하는 권한으로 데이터 갱신 권한이 아니며, 대상 앞에는 TO가 아니라 ON이 온다."},{"verdict":"정답","why":"데이터를 갱신하는 권한은 UPDATE이고, 권한을 줄 대상 객체 앞에는 ON을 쓴다. GRANT UPDATE ON STUDENT TO PARK;"},{"verdict":"오답","why":"REPLACE는 GRANT로 부여하는 객체 권한이 아니며, 대상 앞에는 IN이 아니라 ON을 쓴다."},{"verdict":"오답","why":"INSERT는 데이터를 삽입하는 권한이지 갱신 권한이 아니며, 대상 앞에는 INTO가 아니라 ON을 쓴다."}],"keywords":[{"term":"GRANT","desc":"사용자에게 권한을 부여, GRANT 권한 ON 테이블 TO 사용자"},{"term":"REVOKE","desc":"부여한 권한을 회수, REVOKE 권한 ON 테이블 FROM 사용자"},{"term":"WITH GRANT OPTION","desc":"부여받은 권한을 다른 사용자에게 다시 부여할 수 있게 하는 옵션"}],"memo":"GRANT는 ON ~ TO, REVOKE는 ON ~ FROM이다."}},{"id":"written-2024-1-54","no":54,"unit":"데이터베이스 구축","q":"SQL 명령 중 DML에 속하는 것만으로 나열된 것은?","choices":["SELECT, INSERT, DELETE, UPDATE","SELECT, INSERT, DELETE, ALTER","DELETE, UPDATE, CREATE, ALTER","INSERT, DELETE, UPDATE, DROP"],"ans":1,"exp":{"concept":"SQL 명령은 용도에 따라 DDL, DML, DCL로 나눈다. DDL(데이터 정의어)은 테이블 같은 구조를 만들고 바꾸고 지우는 CREATE, ALTER, DROP이고, DML(데이터 조작어)은 테이블 안의 데이터를 다루는 SELECT, INSERT, UPDATE, DELETE다. DCL(데이터 제어어)은 권한과 트랜잭션을 다루는 GRANT, REVOKE, COMMIT, ROLLBACK 등이다.","choices":[{"verdict":"정답","why":"SELECT, INSERT, DELETE, UPDATE는 모두 데이터를 검색, 삽입, 삭제, 갱신하는 DML이다."},{"verdict":"오답","why":"ALTER는 테이블 구조를 변경하는 DDL이다."},{"verdict":"오답","why":"CREATE와 ALTER는 DDL이다."},{"verdict":"오답","why":"DROP은 테이블 등을 제거하는 DDL이다."}],"keywords":[{"term":"DDL(Data Definition Language)","desc":"CREATE, ALTER, DROP"},{"term":"DML(Data Manipulation Language)","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL(Data Control Language)","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"구조(그릇)를 다루면 DDL, 내용물(데이터)을 다루면 DML이다. DELETE는 DML, DROP은 DDL이다."}},{"id":"written-2024-1-55","no":55,"unit":"데이터베이스 구축","q":"관계형 데이터 모델의 릴레이션에 관한 설명 중 틀린 것은?","choices":["한 릴레이션에 포함된 튜플 사이에 순서는 없다.","한 릴레이션을 구성하는 속성 사이에 순서가 존재한다.","한 릴레이션에 포함된 튜플은 모두 서로 상이하다.","모든 속성 값은 원자 값을 가진다."],"ans":2,"exp":{"concept":"릴레이션(Relation)은 데이터를 행(튜플)과 열(속성)로 이루어진 표로 나타낸 것이다. 릴레이션에서는 튜플이 모두 서로 달라야 하고, 튜플 사이에도 속성 사이에도 순서가 없으며, 모든 속성 값은 더 나눌 수 없는 원자 값이어야 한다.","choices":[{"verdict":"오답","why":"릴레이션의 튜플 사이에는 순서가 없다. 맞는 설명이다."},{"verdict":"정답","why":"릴레이션을 구성하는 속성 사이에도 순서가 없다. 열의 순서를 바꿔도 같은 릴레이션이다."},{"verdict":"오답","why":"릴레이션의 튜플은 모두 서로 달라야 하며 중복될 수 없다. 맞는 설명이다."},{"verdict":"오답","why":"모든 속성 값은 논리적으로 더 이상 쪼갤 수 없는 원자 값이다. 맞는 설명이다."}],"keywords":[{"term":"튜플의 유일성","desc":"릴레이션의 튜플은 모두 서로 다르다"},{"term":"튜플의 무순서성","desc":"튜플 사이에 순서가 없다"},{"term":"속성의 무순서성","desc":"속성 사이에 순서가 없다"},{"term":"속성의 원자성","desc":"속성 값은 원자 값이어야 한다"}],"memo":"릴레이션은 '행도 열도 순서가 없다'. 순서가 있다는 보기는 틀린다."}},{"id":"written-2024-1-56","no":56,"unit":"데이터베이스 구축","q":"SQL에 관한 설명 중 틀린 것은?","choices":["REVOKE 키워드를 이용하면 열 이름을 다시 부여할 수 있다.","JOIN을 이용해 여러 테이블의 레코드를 조합하여 표현할 수 있다.","DISTINCT를 사용하여 중복 값을 제거할 수 있다.","데이터 정의어는 기본 테이블, 뷰 테이블 또는 인덱스 등을 생성, 변경, 제거하는 데 쓰이는 명령어이다."],"ans":1,"exp":{"concept":"SQL은 데이터 정의어(DDL), 데이터 조작어(DML), 데이터 제어어(DCL)로 이루어진다. REVOKE는 DCL로, GRANT로 부여한 권한을 다시 빼앗는 명령이다. 열 이름을 바꾸는 것은 권한과 상관없이 ALTER TABLE 등으로 한다.","choices":[{"verdict":"정답","why":"REVOKE는 사용자에게 부여한 권한을 취소(회수)하는 명령이지, 열 이름을 다시 부여하는 명령이 아니다."},{"verdict":"오답","why":"JOIN은 여러 테이블의 레코드를 공통 속성으로 조합해 하나의 결과로 보여 준다. 맞는 설명이다."},{"verdict":"오답","why":"SELECT DISTINCT는 검색 결과에서 중복된 값을 제거한다. 맞는 설명이다."},{"verdict":"오답","why":"데이터 정의어(DDL)는 테이블, 뷰, 인덱스 등을 생성(CREATE), 변경(ALTER), 제거(DROP)한다. 맞는 설명이다."}],"keywords":[{"term":"REVOKE","desc":"부여된 권한을 회수하는 DCL 명령"},{"term":"DISTINCT","desc":"SELECT 결과에서 중복 행을 제거"},{"term":"JOIN","desc":"두 개 이상의 테이블을 연결해 데이터를 검색"}],"memo":"REVOKE는 '취소하다'라는 뜻이다. 권한을 취소하는 명령이지 이름을 붙이는 명령이 아니다."}},{"id":"written-2024-1-57","no":57,"unit":"데이터베이스 구축","q":"아래와 같이 위쪽 릴레이션을 아래쪽 릴레이션으로 정규화하였다면, 이는 어떤 정규화 작업에 해당하는가?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><table class=\"q-tbl is-data\"><thead><tr><th>국가</th><th>도시</th></tr></thead><tbody><tr><td>대한민국</td><td>서울, 부산</td></tr><tr><td>미국</td><td>워싱턴, 뉴욕</td></tr><tr><td>중국</td><td>베이징</td></tr></tbody></table><p>↓</p><table class=\"q-tbl is-data\"><thead><tr><th>국가</th><th>도시</th></tr></thead><tbody><tr><td>대한민국</td><td>서울</td></tr><tr><td>대한민국</td><td>부산</td></tr><tr><td>미국</td><td>워싱턴</td></tr><tr><td>미국</td><td>뉴욕</td></tr><tr><td>중국</td><td>베이징</td></tr></tbody></table></div>","choices":["제1정규형","제2정규형","제3정규형","제4정규형"],"ans":1,"exp":{"concept":"제1정규형(1NF)은 릴레이션의 모든 속성 값이 더 이상 나눌 수 없는 원자 값만 갖도록 하는 정규형이다. 위쪽 표는 한 칸에 '서울, 부산'처럼 여러 값이 들어 있어 원자 값이 아니다. 이를 한 칸에 하나의 값만 들어가도록 행을 나눈 것이 제1정규화다.","choices":[{"verdict":"정답","why":"한 칸에 여러 값이 들어 있던 도시 속성을 원자 값 하나씩으로 나눴으므로 제1정규형으로 만드는 작업이다."},{"verdict":"오답","why":"제2정규형은 제1정규형에서 기본키에 대한 부분 함수적 종속을 제거한 것이다. 이 표는 다중 값을 원자 값으로 나눈 것이라 해당하지 않는다."},{"verdict":"오답","why":"제3정규형은 제2정규형에서 이행적 함수 종속을 제거한 것이다."},{"verdict":"오답","why":"제4정규형은 BCNF에서 다치(다중 값) 종속을 제거한 것이다. 한 칸에 여러 값이 있는 것을 쪼개는 작업은 제1정규형이다."}],"keywords":[{"term":"제1정규형(1NF)","desc":"모든 속성 값이 원자 값"},{"term":"제2정규형(2NF)","desc":"부분 함수적 종속 제거"},{"term":"제3정규형(3NF)","desc":"이행적 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거"},{"term":"제4정규형(4NF)","desc":"다치 종속 제거"}],"memo":"정규화 순서는 '도부이결다조'(도메인이 원자 값, 부분 함수 종속 제거, 이행 함수 종속 제거, 결정자이면서 후보키가 아닌 것 제거, 다치 종속 제거, 조인 종속 제거)로 외운다. 한 칸에 값이 여러 개면 제1정규형이다."}},{"id":"written-2024-1-58","no":58,"unit":"데이터베이스 구축","q":"트랜잭션의 실행이 실패했음을 알리는 연산자로서, 트랜잭션이 수행한 결과를 원래 상태로 되돌리는 연산은?","choices":["BACKUP 연산","ROLLBACK 연산","LOG 연산","COMMIT 연산"],"ans":2,"exp":{"concept":"트랜잭션은 모두 성공하면 COMMIT으로 결과를 확정하고, 중간에 실패하면 ROLLBACK으로 지금까지 한 작업을 모두 취소해 시작 전 상태로 되돌린다. 게임에서 실수했을 때 저장한 시점으로 다시 불러오는 것과 같다.","choices":[{"verdict":"오답","why":"BACKUP은 데이터를 복사해 따로 보관하는 작업으로, 트랜잭션 실패를 알리는 연산이 아니다."},{"verdict":"정답","why":"ROLLBACK은 트랜잭션 실행이 실패했음을 알리고, 트랜잭션이 수행한 결과를 원래 상태로 되돌리는 연산이다."},{"verdict":"오답","why":"LOG는 데이터베이스의 변경 내용을 기록한 것으로, 회복에 쓰이지만 트랜잭션을 취소하는 연산은 아니다."},{"verdict":"오답","why":"COMMIT은 트랜잭션이 성공적으로 끝났음을 알리고 변경 내용을 데이터베이스에 영구히 반영하는 연산이다."}],"keywords":[{"term":"COMMIT","desc":"트랜잭션의 변경 내용을 데이터베이스에 확정 반영"},{"term":"ROLLBACK","desc":"트랜잭션의 변경 내용을 취소하고 이전 상태로 되돌림"},{"term":"SAVEPOINT","desc":"ROLLBACK할 위치를 트랜잭션 중간에 지정"}],"memo":"ROLL(되감다) BACK(뒤로), 되감아서 원래대로 돌린다."}},{"id":"written-2024-1-59","no":59,"unit":"데이터베이스 구축","q":"다른 릴레이션의 기본키를 참조하는 키를 뜻하는 것은?","choices":["외래키","필드키","후보키","슈퍼키"],"ans":1,"exp":{"concept":"키(Key)는 튜플을 구별하거나 다른 릴레이션과 연결하는 데 쓰는 속성이다. 외래키는 다른 릴레이션의 기본키를 참조하는 속성으로, 두 릴레이션을 연결하는 다리 역할을 한다. 예를 들어 수강 테이블의 학번은 학생 테이블의 기본키인 학번을 참조하는 외래키다.","choices":[{"verdict":"정답","why":"외래키(Foreign Key)는 다른 릴레이션의 기본키를 참조하는 속성 또는 속성들의 집합이다."},{"verdict":"오답","why":"필드키는 관계형 데이터베이스의 키 종류가 아니며, 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"후보키(Candidate Key)는 튜플을 유일하게 식별할 수 있는 속성들 중 유일성과 최소성을 모두 만족하는 키다."},{"verdict":"오답","why":"슈퍼키(Super Key)는 튜플을 유일하게 식별할 수 있는 속성의 집합으로, 유일성은 만족하지만 최소성은 만족하지 않을 수 있다."}],"keywords":[{"term":"외래키(Foreign Key)","desc":"다른 릴레이션의 기본키를 참조하는 속성"},{"term":"기본키(Primary Key)","desc":"후보키 중 대표로 선정한 키, 널과 중복 불가"},{"term":"후보키(Candidate Key)","desc":"유일성과 최소성을 모두 만족하는 키"},{"term":"슈퍼키(Super Key)","desc":"유일성은 만족하지만 최소성은 만족하지 않을 수 있는 키"}],"memo":"'다른 릴레이션', '참조'라는 단서가 나오면 외래키다."}},{"id":"written-2024-1-60","no":60,"unit":"데이터베이스 구축","q":"부모 테이블의 행을 DELETE문으로 삭제할 때 이를 참조하는 자식 테이블의 해당 행도 자동으로 삭제되도록 지정하는 옵션은?","choices":["CASCADE","RESTRICTED","SET-NULL","CLUSTER"],"ans":1,"exp":{"concept":"외래키를 정의할 때 부모 테이블의 행이 삭제되면 그 행을 참조하는 자식 테이블의 행을 어떻게 처리할지 옵션으로 정할 수 있다. CASCADE는 자식 행도 함께 삭제하고, SET NULL은 자식 행의 외래키 값을 NULL로 바꾸며, RESTRICT(NO ACTION)는 참조하는 자식 행이 있으면 삭제를 거부한다.","choices":[{"verdict":"정답","why":"ON DELETE CASCADE는 부모 테이블의 행이 삭제되면 이를 참조하는 자식 테이블의 행도 연쇄적으로 자동 삭제한다."},{"verdict":"오답","why":"RESTRICT 계열 옵션은 참조하는 자식 행이 있으면 부모 행의 삭제를 거부한다. 자식 행을 함께 삭제하지 않는다."},{"verdict":"오답","why":"SET NULL은 부모 행이 삭제되면 자식 행을 삭제하지 않고 외래키 값을 NULL로 바꾼다."},{"verdict":"오답","why":"CLUSTER는 데이터를 물리적으로 모아 저장하는 것과 관련된 용어로, 참조 무결성 삭제 옵션이 아니다."}],"keywords":[{"term":"ON DELETE CASCADE","desc":"부모 행 삭제 시 참조하는 자식 행도 함께 삭제"},{"term":"ON DELETE SET NULL","desc":"부모 행 삭제 시 자식 행의 외래키를 NULL로 변경"},{"term":"ON DELETE RESTRICT","desc":"참조하는 자식 행이 있으면 부모 행 삭제를 거부"}],"memo":"CASCADE는 '연쇄', 부모가 지워지면 자식도 줄줄이 지워진다."}},{"id":"written-2024-1-61","no":61,"unit":"프로그래밍 언어 활용","q":"다음 설명에 해당하는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>서버 측에서 동적으로 수행되는 페이지를 만들기 위해 마이크로 소프트 사에서 제작한 언어이다.</li><li>Windows 계열에서만 수행할 수 있는 프로그래밍 언어이다.</li></ul></div>","choices":["자바스크립트(JAVA Script)","JSP(Java Server Page)","ASP(Active Server Page)","파이썬(Python)"],"ans":3,"exp":{"concept":"서버 측 스크립트 언어는 웹 서버에서 실행되어 요청마다 다른 페이지를 만들어 주는 언어다. ASP(Active Server Page)는 마이크로소프트사가 만든 서버 측 동적 페이지 언어로, Windows 계열에서만 수행할 수 있다.","choices":[{"verdict":"오답","why":"자바스크립트는 넷스케이프에서 개발한 언어로, 주로 웹 브라우저(클라이언트 측)에서 동작하며 Windows 전용이 아니다."},{"verdict":"오답","why":"JSP(Java Server Page)는 자바 기반의 서버 측 스크립트 언어로, 다양한 운영체제에서 사용할 수 있다."},{"verdict":"정답","why":"ASP는 마이크로소프트사가 만든 서버 측 동적 웹 페이지 언어로, Windows 계열에서만 수행할 수 있다."},{"verdict":"오답","why":"파이썬은 귀도 반 로섬이 발표한 인터프리터 언어로, 여러 운영체제에서 사용할 수 있다."}],"keywords":[{"term":"ASP(Active Server Page)","desc":"마이크로소프트사가 만든 서버 측 스크립트, Windows 전용"},{"term":"JSP(Java Server Page)","desc":"Java로 만든 서버 측 스크립트, 다양한 운영체제 지원"},{"term":"PHP(PHP: Hypertext Preprocessor)","desc":"Linux, Unix, Windows에서 사용 가능한 서버 측 스크립트"}],"memo":"'마이크로소프트'와 'Windows 전용'이 함께 나오면 ASP다."}},{"id":"written-2024-1-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 중 스크립트 언어에 해당하지 않는 것은?","choices":["VBScript","Cobol","Python","PHP"],"ans":2,"exp":{"concept":"스크립트 언어는 소스 코드를 미리 컴파일하지 않고 실행할 때 바로 해석하는 인터프리터 방식의 언어다. VBScript, Python, PHP, JavaScript, ASP, JSP, Basic 등이 있다. COBOL은 사무 처리용으로 만든 컴파일 언어다.","choices":[{"verdict":"오답","why":"VBScript는 마이크로소프트사가 만든 Visual Basic 기반의 스크립트 언어다."},{"verdict":"정답","why":"COBOL은 사무 처리용으로 개발된 컴파일 언어로, 스크립트 언어가 아니다."},{"verdict":"오답","why":"Python은 인터프리터 방식의 객체지향 스크립트 언어다."},{"verdict":"오답","why":"PHP는 서버 측에서 동작하는 스크립트 언어다."}],"keywords":[{"term":"스크립트 언어","desc":"실행 시점에 해석되는 인터프리터 방식 언어, JavaScript, Python, PHP, VBScript 등"},{"term":"컴파일 언어","desc":"실행 전에 기계어로 번역하는 언어, C, C++, COBOL 등"},{"term":"COBOL","desc":"사무 처리 업무용으로 개발된 고급 언어"}],"memo":"COBOL은 'Common Business Oriented Language', 즉 사무용 컴파일 언어다."}},{"id":"written-2024-1-63","no":63,"unit":"프로그래밍 언어 활용","q":"TCP/IP에서 논리 주소를 물리 주소로 변환해 주는 프로토콜은 무엇인가?","choices":["ARP","FTP","IP","TCP"],"ans":1,"exp":{"concept":"네트워크에서 논리 주소는 IP 주소이고, 물리 주소는 랜카드에 새겨진 MAC 주소다. 같은 네트워크 안에서 실제로 데이터를 보내려면 상대의 MAC 주소를 알아야 하는데, IP 주소를 보고 MAC 주소를 알아내는 프로토콜이 ARP다. 반대로 MAC 주소로 IP 주소를 알아내는 것은 RARP다.","choices":[{"verdict":"정답","why":"ARP(Address Resolution Protocol)는 호스트의 IP 주소(논리 주소)를 물리 주소(MAC 주소)로 변환한다."},{"verdict":"오답","why":"FTP(File Transfer Protocol)는 컴퓨터 간에 파일을 송수신하는 응용 계층 프로토콜이다."},{"verdict":"오답","why":"IP(Internet Protocol)는 패킷의 주소 지정과 경로 설정을 담당하는 네트워크 계층 프로토콜이다."},{"verdict":"오답","why":"TCP(Transmission Control Protocol)는 신뢰성 있는 연결형 전송을 제공하는 전송 계층 프로토콜이다."}],"keywords":[{"term":"ARP","desc":"IP 주소를 MAC 주소로 변환"},{"term":"RARP","desc":"MAC 주소를 IP 주소로 변환"},{"term":"MAC 주소","desc":"네트워크 장치에 부여된 물리 주소, 48비트"}],"memo":"ARP는 IP에서 MAC으로, 앞에 Reverse(R)가 붙은 RARP는 그 반대다."}},{"id":"written-2024-1-64","no":64,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 가운데 네트워크 계층에 관한 설명으로 옳지 않은 것은?","choices":["발신지와 목적지의 논리 주소를 패킷에 추가한다.","라우터나 교환기는 패킷 전달을 위한 경로를 지정하거나 교환 기능을 제공한다.","발신지에서 최종 목적지까지 패킷을 전달하는 책임을 진다.","한 노드에서 다른 노드로 프레임을 전송하는 책임을 진다."],"ans":4,"exp":{"concept":"OSI 7계층 중 네트워크 계층(3계층)은 발신지에서 최종 목적지까지 패킷이 가는 경로를 정하고(라우팅) 전달하는 계층이다. 이를 위해 IP 주소 같은 논리 주소를 패킷에 붙인다. 바로 옆 노드까지 프레임을 전달하는 것은 그 아래 데이터 링크 계층(2계층)의 일이다.","choices":[{"verdict":"오답","why":"네트워크 계층은 발신지와 목적지의 논리 주소(IP 주소)를 패킷에 추가한다. 맞는 설명이다."},{"verdict":"오답","why":"라우터 등은 네트워크 계층에서 패킷 전달 경로를 지정하고 교환 기능을 수행한다. 맞는 설명이다."},{"verdict":"오답","why":"네트워크 계층은 발신지에서 최종 목적지까지 패킷을 전달할 책임을 진다. 맞는 설명이다."},{"verdict":"정답","why":"한 노드에서 인접한 다른 노드로 프레임을 전송하는 것은 데이터 링크 계층의 역할이다."}],"keywords":[{"term":"데이터 링크 계층(2계층)","desc":"인접 노드 간 프레임 전송, 흐름 제어, 오류 제어, MAC 주소"},{"term":"네트워크 계층(3계층)","desc":"패킷의 경로 설정(라우팅)과 종단 간 전달, IP 주소"},{"term":"전송 계층(4계층)","desc":"종단 시스템 간 신뢰성 있는 데이터 전송, TCP와 UDP"},{"term":"계층별 데이터 단위","desc":"2계층 프레임, 3계층 패킷, 4계층 세그먼트"}],"memo":"'프레임'은 2계층, '패킷'은 3계층이다. 데이터 단위 이름만 봐도 계층을 구분할 수 있다."}},{"id":"written-2024-1-65","no":65,"unit":"프로그래밍 언어 활용","q":"C, Java 등의 언어에서 쓰이는 예약어로, 반복문 내에서 뒤의 문장을 실행하지 않고 제어를 반복문의 시작 부분으로 옮기는 명령어는 무엇인가?","choices":["continue","next","release","break"],"ans":1,"exp":{"concept":"반복문 안에서 흐름을 바꾸는 예약어로 continue와 break가 있다. continue는 그 아래 문장을 건너뛰고 반복문의 처음(다음 반복)으로 돌아가고, break는 반복문을 아예 빠져나간다.","choices":[{"verdict":"정답","why":"continue는 반복문 안에서 이후 문장을 실행하지 않고 제어를 반복문의 시작 부분(다음 반복)으로 옮긴다."},{"verdict":"오답","why":"next는 C나 Java의 예약어가 아니다."},{"verdict":"오답","why":"release는 C나 Java의 예약어가 아니다."},{"verdict":"오답","why":"break는 반복문을 완전히 빠져나가는 명령으로, 반복문의 시작으로 돌아가지 않는다."}],"keywords":[{"term":"continue","desc":"남은 문장을 건너뛰고 다음 반복으로 진행"},{"term":"break","desc":"반복문이나 switch 문을 완전히 빠져나감"},{"term":"return","desc":"함수를 종료하고 호출한 곳으로 돌아감"}],"memo":"continue는 '계속한다'(다음 바퀴로), break는 '깨고 나간다'(반복 종료)로 기억한다."}},{"id":"written-2024-1-66","no":66,"unit":"프로그래밍 언어 활용","q":"다음 중 비선점(Non-Preemptive) 스케줄링에 속하지 않는 것은?","choices":["HRN","SJF","FCFS","SRT"],"ans":4,"exp":{"concept":"비선점(Non-Preemptive) 스케줄링은 한 프로세스가 CPU를 차지하면 끝날 때까지 다른 프로세스가 빼앗을 수 없는 방식이고, 선점(Preemptive) 스케줄링은 우선순위가 높은 프로세스가 CPU를 빼앗을 수 있는 방식이다. 비선점에는 FCFS, SJF, HRN, 우선순위, 기한부가 있고, 선점에는 RR, SRT, 선점 우선순위, 다단계 큐, 다단계 피드백 큐가 있다.","choices":[{"verdict":"오답","why":"HRN(Highest Response-ratio Next)은 (대기 시간 + 서비스 시간) / 서비스 시간으로 우선순위를 정하는 비선점 스케줄링이다."},{"verdict":"오답","why":"SJF(Shortest Job First)는 실행 시간이 가장 짧은 작업을 먼저 처리하는 비선점 스케줄링이다."},{"verdict":"오답","why":"FCFS(First Come First Served)는 먼저 도착한 작업을 먼저 처리하는 비선점 스케줄링으로, FIFO라고도 한다."},{"verdict":"정답","why":"SRT(Shortest Remaining Time)는 SJF를 선점 방식으로 바꾼 것으로, 남은 실행 시간이 더 짧은 프로세스가 도착하면 CPU를 빼앗는 선점 스케줄링이다."}],"keywords":[{"term":"비선점 스케줄링","desc":"FCFS, SJF, HRN, 우선순위, 기한부"},{"term":"선점 스케줄링","desc":"RR, SRT, 선점 우선순위, 다단계 큐, 다단계 피드백 큐"},{"term":"SRT(Shortest Remaining Time)","desc":"남은 실행 시간이 가장 짧은 프로세스에 CPU를 할당하는 선점형 SJF"}],"memo":"SRT의 R(Remaining, 남은 시간)은 실행 도중에 계속 비교한다는 뜻이라 선점이다. SJF는 비선점이다."}},{"id":"written-2024-1-67","no":67,"unit":"프로그래밍 언어 활용","q":"Java의 자료형과 그 크기를 연결한 것 중 옳지 않은 것은?","choices":["byte - 1Byte","char - 1Byte","int - 4Byte","double - 8Byte"],"ans":2,"exp":{"concept":"Java의 기본 자료형은 크기가 정해져 있다. 정수형 byte는 1바이트, short는 2바이트, int는 4바이트, long은 8바이트이고, 실수형 float는 4바이트, double은 8바이트다. 문자형 char는 유니코드 문자를 저장하므로 2바이트다. C 언어의 char가 1바이트인 것과 헷갈리기 쉽다.","choices":[{"verdict":"오답","why":"Java의 byte는 1바이트다. 맞는 연결이다."},{"verdict":"정답","why":"Java의 char는 유니코드 문자를 저장하므로 1바이트가 아니라 2바이트다."},{"verdict":"오답","why":"Java의 int는 4바이트다. 맞는 연결이다."},{"verdict":"오답","why":"Java의 double은 8바이트다. 맞는 연결이다."}],"keywords":[{"term":"Java 정수형 크기","desc":"byte 1, short 2, int 4, long 8바이트"},{"term":"Java 실수형 크기","desc":"float 4, double 8바이트"},{"term":"Java char","desc":"유니코드 문자 1개를 저장하는 2바이트 자료형"},{"term":"Java boolean","desc":"true 또는 false를 저장하는 자료형"}],"memo":"C의 char는 1바이트, Java의 char는 유니코드라 2바이트다."}},{"id":"written-2024-1-68","no":68,"unit":"프로그래밍 언어 활용","q":"C언어에서 변수명으로 사용할 수 없는 것은?","choices":["text-color","amount","student2025","_korea"],"ans":1,"exp":{"concept":"C 언어의 변수명은 영문자, 숫자, 밑줄(_)만 쓸 수 있고, 첫 글자는 숫자가 될 수 없다. 공백이나 하이픈(-) 같은 특수 문자는 쓸 수 없고, int, for 같은 예약어도 변수명으로 쓸 수 없다.","choices":[{"verdict":"정답","why":"하이픈(-)은 빼기 연산자로 해석되므로 변수명에 쓸 수 없다. text-color는 'text 빼기 color'가 되어 컴파일 오류가 난다."},{"verdict":"오답","why":"amount는 영문자로만 이루어져 있어 변수명으로 쓸 수 있다."},{"verdict":"오답","why":"student2025는 영문자로 시작하고 숫자가 뒤에 오므로 변수명으로 쓸 수 있다."},{"verdict":"오답","why":"_korea는 밑줄로 시작하는데, 밑줄은 첫 글자로 쓸 수 있으므로 변수명으로 쓸 수 있다."}],"keywords":[{"term":"C 변수명 규칙","desc":"영문자, 숫자, 밑줄(_)만 사용, 첫 글자에 숫자 불가"},{"term":"예약어","desc":"int, for, while처럼 언어가 미리 정한 단어로 변수명으로 쓸 수 없다"},{"term":"대소문자 구분","desc":"C는 대소문자를 구분해 Amount와 amount는 다른 변수다"}],"memo":"변수명에 허용되는 특수 문자는 밑줄(_) 하나뿐이다. 하이픈과 공백은 안 된다."}},{"id":"written-2024-1-69","no":69,"unit":"프로그래밍 언어 활용","q":"IP 버전에 관한 다음 설명 중 옳지 않은 것은?","choices":["IPv4는 네트워크 부분의 길이에 따라 A 클래스부터 E 클래스까지 총 5단계로 구성된다.","IPv4는 각 부분이 옥텟으로 구성되며, 총 32비트로 이루어진다.","IPv6는 IPv4에 비해 자료 전송 속도가 느린 편이다.","IPv6는 각 부분을 콜론으로 구분하여 표기한다."],"ans":3,"exp":{"concept":"IPv4는 32비트 주소를 8비트씩 4부분(옥텟)으로 나눠 점(.)으로 구분하고, A~E의 5개 클래스로 나눈다. IPv6는 주소 부족을 해결하려고 만든 128비트 주소 체계로, 16비트씩 8부분으로 나눠 콜론(:)으로 구분한다. IPv6는 헤더 구조가 단순해져 IPv4보다 처리 속도가 빠르다.","choices":[{"verdict":"오답","why":"IPv4는 네트워크 부분의 길이에 따라 A 클래스부터 E 클래스까지 5단계로 구성된다. 맞는 설명이다."},{"verdict":"오답","why":"IPv4는 8비트씩 4개의 옥텟으로 구성되어 총 32비트다. 맞는 설명이다."},{"verdict":"정답","why":"IPv6는 IPv4보다 자료 전송 속도가 느리지 않고 오히려 빠르다. 헤더가 단순화되어 처리 효율이 좋아졌다."},{"verdict":"오답","why":"IPv6는 16비트씩 8부분으로 나눠 각 부분을 콜론(:)으로 구분하여 표기한다. 맞는 설명이다."}],"keywords":[{"term":"IPv4","desc":"32비트, 8비트씩 4부분을 점(.)으로 구분, A~E 클래스"},{"term":"IPv6","desc":"128비트, 16비트씩 8부분을 콜론(:)으로 구분"},{"term":"IPv6 주소 유형","desc":"유니캐스트, 멀티캐스트, 애니캐스트"}],"memo":"IPv6는 IPv4의 단점을 개선한 것이라 '느리다'는 보기는 틀린다."}},{"id":"written-2024-1-70","no":70,"unit":"프로그래밍 언어 활용","q":"UNIX에 관한 설명 중 옳지 않은 것은?","choices":["두 사람 이상의 사용자가 시스템을 동시에 사용할 수 있으므로 정보와 유틸리티들을 공유하는 편리한 작업 환경을 제공한다.","대부분 C 언어로 작성되어 있어 이식성이 우수하다.","사용자는 하나 이상의 작업을 백그라운드에서 수행할 수 있으므로 여러 개의 작업을 병행 처리할 수 있다.","쉘(Shell)은 프로세스 관리, 기억장치 관리, 입출력 관리 등의 기능을 담당한다."],"ans":4,"exp":{"concept":"UNIX 시스템은 커널, 쉘, 유틸리티 프로그램으로 구성된다. 커널(Kernel)은 하드웨어를 직접 관리하는 핵심으로 프로세스 관리, 기억장치 관리, 파일 관리, 입출력 관리를 맡는다. 쉘(Shell)은 사용자가 입력한 명령어를 해석해 커널에 전달하는 명령어 해석기다.","choices":[{"verdict":"오답","why":"UNIX는 여러 사용자가 동시에 쓰는 다중 사용자(Multi-User) 시스템이다. 맞는 설명이다."},{"verdict":"오답","why":"UNIX는 대부분 C 언어로 작성되어 다른 기종으로 옮기기 쉬운 이식성이 높다. 맞는 설명이다."},{"verdict":"오답","why":"UNIX는 하나 이상의 작업을 백그라운드에서 수행하는 다중 작업(Multi-Tasking)을 지원한다. 맞는 설명이다."},{"verdict":"정답","why":"프로세스 관리, 기억장치 관리, 입출력 관리를 담당하는 것은 커널이다. 쉘은 명령어를 해석해 커널에 전달하는 명령어 해석기다."}],"keywords":[{"term":"커널(Kernel)","desc":"UNIX의 핵심, 프로세스·기억장치·파일·입출력 관리"},{"term":"쉘(Shell)","desc":"사용자 명령어를 해석해 커널에 전달하는 명령어 해석기"},{"term":"유틸리티 프로그램","desc":"에디터, 컴파일러 등 일반 사용자가 쓰는 프로그램"}],"memo":"커널은 '관리', 쉘은 '해석'이다. 쉘은 커널을 감싼 껍데기라 사용자와 커널 사이에서 말을 전한다."}},{"id":"written-2024-1-71","no":71,"unit":"프로그래밍 언어 활용","q":"C언어 라이브러리 가운데 stdlib.h에 관한 설명으로 옳은 것은?","choices":["표준 입출력을 위한 라이브러리이다.","문자열을 수치 데이터로 변환하는 함수와 동적 메모리 할당 및 해제 함수 등을 포함한다.","문자열 처리 함수인 strlen()이 포함되어 있다.","삼각 함수, 제곱근, 지수 같은 수학적인 함수를 내장하고 있다."],"ans":2,"exp":{"concept":"C 언어는 헤더 파일 단위로 라이브러리를 제공한다. stdlib.h는 문자열을 수치로 바꾸는 atoi(), atof(), 동적 메모리를 할당하고 해제하는 malloc(), free(), 난수를 만드는 rand() 등 자주 쓰는 일반 함수를 담고 있다.","choices":[{"verdict":"오답","why":"표준 입출력 라이브러리는 stdio.h로, printf(), scanf() 등이 들어 있다."},{"verdict":"정답","why":"stdlib.h에는 atoi() 같은 자료형 변환 함수와 malloc(), free() 같은 동적 메모리 할당·해제 함수 등이 포함되어 있다."},{"verdict":"오답","why":"strlen() 같은 문자열 처리 함수는 string.h에 들어 있다."},{"verdict":"오답","why":"삼각 함수, 제곱근, 지수 같은 수학 함수는 math.h에 들어 있다."}],"keywords":[{"term":"stdio.h","desc":"표준 입출력 함수, printf, scanf, getchar 등"},{"term":"stdlib.h","desc":"자료형 변환, 동적 메모리 할당, 난수 등, atoi, malloc, free, rand"},{"term":"string.h","desc":"문자열 처리 함수, strlen, strcpy, strcmp 등"},{"term":"math.h","desc":"수학 함수, sqrt, pow, sin 등"}],"memo":"std(표준) + lib(라이브러리)는 '잡다한 일반 함수 모음'이다. 입출력은 io, 문자열은 string, 수학은 math로 이름에 드러난다."}},{"id":"written-2024-1-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 표에 제시된 시점의 HRN 응답률을 기준으로 작업의 우선순위를 높은 순서부터 나열한 것은?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><table class=\"q-tbl is-data\"><thead><tr><th>작업</th><th>대기 시간</th><th>서비스(실행)시간</th></tr></thead><tbody><tr><td>A</td><td>5</td><td>20</td></tr><tr><td>B</td><td>40</td><td>20</td></tr><tr><td>C</td><td>15</td><td>45</td></tr><tr><td>D</td><td>20</td><td>2</td></tr></tbody></table></div>","choices":["D → A → B → C","A → B → C → D","D → B → C → A","A → C → B → D"],"ans":3,"exp":{"concept":"HRN(Highest Response-ratio Next)은 대기 시간이 긴 작업이 계속 밀리는 문제를 줄이려고, 응답률(우선순위) = (대기 시간 + 서비스 시간) / 서비스 시간을 계산해 값이 큰 작업부터 처리하는 방식이다. 오래 기다릴수록, 실행 시간이 짧을수록 응답률이 커진다.","choices":[{"verdict":"오답","why":"A의 응답률은 1.25로 가장 낮아 두 번째가 아니라 마지막이어야 한다. 올바른 순서는 D(11) → B(3) → C(약 1.33) → A(1.25)다."},{"verdict":"오답","why":"A가 가장 먼저 올 수 없다. A는 응답률 1.25로 가장 낮고, D가 11로 가장 높다."},{"verdict":"정답","why":"A=(5+20)/20=1.25, B=(40+20)/20=3, C=(15+45)/45≈1.33, D=(20+2)/2=11이다. 큰 순서대로 D → B → C → A다."},{"verdict":"오답","why":"A가 가장 먼저 오고 D가 마지막인 것은 거꾸로다. 응답률이 가장 큰 D(11)가 먼저, 가장 작은 A(1.25)가 마지막이다."}],"keywords":[{"term":"HRN 우선순위","desc":"(대기 시간 + 서비스 시간) / 서비스 시간, 값이 클수록 먼저"},{"term":"SJF(Shortest Job First)","desc":"실행 시간이 짧은 작업을 먼저 처리, 긴 작업이 밀리는 문제가 있음"},{"term":"에이징(Aging)","desc":"오래 기다린 작업의 우선순위를 높여 무한 대기를 막는 기법"}],"memo":"분모는 '서비스 시간' 하나뿐이다. 분모에 대기 시간을 넣는 실수를 조심한다."}},{"id":"written-2024-1-73","no":73,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램을 실행했을 때 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nmain() {\n    int sum = 0;\n    for (int i = 1; i &lt; 20; i *= 2)\n        sum += i;\n    printf(\"%d\", sum);\n}</code></pre>","choices":["31","32","100","190"],"ans":1,"exp":{"concept":"for 문은 초기식, 조건식, 증감식으로 반복을 제어한다. 이 코드는 i가 1부터 시작해 매번 2배가 되고, i가 20보다 작을 동안 sum에 i를 더한다.","choices":[{"verdict":"정답","why":"i가 1, 2, 4, 8, 16일 때 더해져 sum = 1+2+4+8+16 = 31이다. 다음 i는 32가 되어 조건 i < 20이 거짓이므로 반복이 끝난다."},{"verdict":"오답","why":"32는 반복이 끝날 때의 i 값으로, sum에는 더해지지 않는다."},{"verdict":"오답","why":"100은 이 코드의 sum 값과 관계없다. i는 1씩이 아니라 2배씩 늘어난다."},{"verdict":"오답","why":"190은 i가 1부터 19까지 1씩 증가하며 더했을 때의 합이다. 이 코드는 i *= 2이므로 2배씩 늘어난다."}],"keywords":[{"term":"i *= 2","desc":"i = i * 2와 같은 복합 대입 연산자"},{"term":"for 문 실행 순서","desc":"초기식 → 조건식 검사 → 본문 실행 → 증감식 → 조건식 검사 반복"},{"term":"누적 합","desc":"sum += i처럼 반복할 때마다 값을 더해 나가는 것"}],"memo":"증감식이 i++인지 i *= 2인지 먼저 확인한다. 2배씩 늘면 1, 2, 4, 8, 16처럼 값이 빠르게 커진다."}},{"id":"written-2024-1-74","no":74,"unit":"프로그래밍 언어 활용","q":"라이브러리의 개념 및 구성에 관한 설명으로 옳지 않은 것은?","choices":["라이브러리는 모듈과 패키지를 총칭하는 것으로, 모듈이 개별 파일이라면 패키지는 파일들을 모아 둔 폴더라고 볼 수 있다.","프로그래밍 언어에 따라 일반적으로 도움말, 설치 파일, 샘플 코드 등이 제공된다.","라이브러리란 필요할 때 찾아 쓸 수 있도록 모듈화하여 제공되는 프로그램을 말한다.","외부 라이브러리는 프로그래밍 언어가 기본적으로 갖추고 있는 라이브러리를 뜻하며, 표준 라이브러리는 별도의 파일 설치가 필요한 라이브러리를 뜻한다."],"ans":4,"exp":{"concept":"라이브러리는 자주 쓰는 기능을 모듈화해 필요할 때 가져다 쓸 수 있게 만든 프로그램 모음이다. 개별 파일인 모듈과 이를 폴더로 모은 패키지를 통틀어 라이브러리라고 한다. 언어에 기본으로 들어 있는 것은 표준 라이브러리, 따로 내려받아 설치해야 하는 것은 외부 라이브러리다.","choices":[{"verdict":"오답","why":"라이브러리는 모듈과 패키지를 총칭하며, 모듈은 개별 파일, 패키지는 파일들을 모아 둔 폴더에 해당한다. 맞는 설명이다."},{"verdict":"오답","why":"라이브러리에는 일반적으로 도움말, 설치 파일, 샘플 코드 등이 함께 제공된다. 맞는 설명이다."},{"verdict":"오답","why":"라이브러리는 필요할 때 찾아 쓸 수 있도록 모듈화해 제공되는 프로그램이다. 맞는 설명이다."},{"verdict":"정답","why":"설명이 서로 바뀌었다. 언어가 기본으로 갖추고 있는 것이 표준 라이브러리이고, 별도 설치가 필요한 것이 외부 라이브러리다."}],"keywords":[{"term":"라이브러리(Library)","desc":"필요할 때 찾아 쓸 수 있게 모듈화된 프로그램 모음"},{"term":"표준 라이브러리","desc":"프로그래밍 언어에 기본으로 포함된 라이브러리"},{"term":"외부 라이브러리","desc":"별도로 설치해서 쓰는 라이브러리"},{"term":"모듈과 패키지","desc":"모듈은 개별 파일, 패키지는 모듈을 모은 폴더"}],"memo":"'표준'은 기본 장착, '외부'는 바깥에서 가져와 설치한다."}},{"id":"written-2024-1-75","no":75,"unit":"프로그래밍 언어 활용","q":"페이지 프레임이 3개인 시스템에서 페이지 참조 순서가 1, 2, 1, 0, 4, 1, 3 일 때, FIFO 알고리즘으로 페이지 교체를 수행한 후 프레임의 최종 상태는?","choices":["1, 2, 0","2, 4, 3","1, 4, 2","4, 1, 3"],"ans":4,"exp":{"concept":"FIFO(First In First Out) 페이지 교체는 프레임이 꽉 찬 상태에서 새 페이지가 필요하면, 가장 먼저 들어온 페이지를 내보내는 방식이다. 줄을 먼저 선 사람이 먼저 나가는 것과 같다. 이미 프레임에 있는 페이지를 참조하면(적중) 아무것도 바뀌지 않는다.","choices":[{"verdict":"오답","why":"1, 2, 0은 참조 0까지 처리했을 때의 상태다. 이후 4, 1, 3이 차례로 들어오며 교체가 일어난다."},{"verdict":"오답","why":"2, 4, 3은 FIFO 교체 결과가 아니다. 참조 1이 들어올 때 가장 먼저 들어온 2가 교체되므로 2는 남지 않는다."},{"verdict":"오답","why":"1, 4, 2는 FIFO 교체 결과가 아니다. 마지막 참조 3이 들어와 0을 교체하므로 3이 프레임에 있어야 한다."},{"verdict":"정답","why":"1(부재) [1] → 2(부재) [1,2] → 1(적중) → 0(부재) [1,2,0] → 4(부재, 가장 먼저 들어온 1 교체) [4,2,0] → 1(부재, 2 교체) [4,1,0] → 3(부재, 0 교체) [4,1,3]이므로 최종 상태는 4, 1, 3이다."}],"keywords":[{"term":"FIFO 페이지 교체","desc":"가장 먼저 들어온 페이지를 교체"},{"term":"LRU(Least Recently Used)","desc":"가장 오랫동안 사용하지 않은 페이지를 교체"},{"term":"LFU(Least Frequently Used)","desc":"사용 횟수가 가장 적은 페이지를 교체"},{"term":"페이지 부재(Page Fault)","desc":"참조할 페이지가 주기억장치 프레임에 없는 상태"}],"memo":"FIFO에서는 적중이 나도 순서가 바뀌지 않는다. 참조 1의 적중 때문에 1이 늦게 나간다고 착각하면 LRU처럼 풀게 된다."}},{"id":"written-2024-1-76","no":76,"unit":"프로그래밍 언어 활용","q":"다음 설명에 해당하는 스크립트 언어는?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>서버용 스크립트 언어로서 Linux, Unix, Windows 운영체제에서 사용할 수 있다.</li><li>C, Java 등과 문법이 유사하여 배우기 쉬우므로 웹 페이지 제작에 많이 쓰인다.</li></ul></div>","choices":["Python","PHP","Basic","C#"],"ans":2,"exp":{"concept":"PHP(PHP: Hypertext Preprocessor)는 서버에서 동작해 동적 웹 페이지를 만드는 스크립트 언어다. Linux, Unix, Windows 운영체제에서 모두 쓸 수 있고, 문법이 C, Java와 비슷해 배우기 쉬워 웹 페이지 제작에 많이 쓰인다.","choices":[{"verdict":"오답","why":"Python은 귀도 반 로섬이 발표한 인터프리터 방식의 범용 객체지향 언어다. 'C, Java와 문법이 유사한 서버용 스크립트 언어로 웹 페이지 제작에 많이 쓰인다'는 설명은 PHP의 특징이다."},{"verdict":"정답","why":"PHP는 Linux, Unix, Windows에서 사용 가능한 서버용 스크립트 언어로, C, Java 등과 문법이 유사해 웹 페이지 제작에 많이 쓰인다."},{"verdict":"오답","why":"Basic은 교육용으로 개발된 언어로, 서버용 웹 스크립트 언어가 아니다."},{"verdict":"오답","why":"C#은 마이크로소프트사가 개발한 객체지향 컴파일 언어로, 서버용 스크립트 언어가 아니다."}],"keywords":[{"term":"PHP","desc":"Linux, Unix, Windows에서 동작하는 서버용 스크립트 언어, C·Java와 문법 유사"},{"term":"ASP","desc":"마이크로소프트사가 만든 Windows 전용 서버 측 스크립트"},{"term":"JSP","desc":"Java로 만든 서버 측 스크립트"}],"memo":"'서버용 스크립트'인데 '여러 운영체제 지원'이면 PHP, 'Windows 전용'이면 ASP다."}},{"id":"written-2024-1-77","no":77,"unit":"프로그래밍 언어 활용","q":"IPv6에 관한 설명 중 틀린 것은?","choices":["패킷 크기는 64Kbyte로 고정되어 있다.","IPv6 확장 헤더를 통해 네트워크 기능의 확장이 용이하다.","인증 및 보안 기능을 포함한다.","128비트의 주소 공간을 제공한다."],"ans":1,"exp":{"concept":"IPv6는 128비트 주소 공간을 제공하는 차세대 IP 주소 체계다. 확장 헤더로 기능을 쉽게 늘릴 수 있고, 인증과 보안 기능이 기본으로 들어 있다. IPv4는 패킷 크기가 64KB로 제한되어 있지만, IPv6는 이 제한이 없어 필요하면 더 큰 패킷도 주고받을 수 있다.","choices":[{"verdict":"정답","why":"IPv6는 패킷 크기가 64KB로 고정되어 있지 않다. 64KB 제한은 IPv4의 특징이고, IPv6는 더 큰 패킷도 주고받을 수 있다."},{"verdict":"오답","why":"IPv6는 확장 헤더를 통해 네트워크 기능을 쉽게 확장할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"IPv6는 인증 및 보안 기능(IPSec)을 포함한다. 맞는 설명이다."},{"verdict":"오답","why":"IPv6는 128비트의 주소 공간을 제공한다. 맞는 설명이다."}],"keywords":[{"term":"IPv6","desc":"128비트 주소, 확장 헤더, 인증·보안 기능 내장"},{"term":"IPv4 패킷 크기","desc":"64KB로 제한"},{"term":"IPSec","desc":"IP 계층에서 무결성과 인증을 보장하는 보안 프로토콜"}],"memo":"IPv6는 IPv4의 제약을 풀려고 만든 것이다. '고정', '제한'이 들어간 IPv6 보기는 의심한다."}},{"id":"written-2024-1-78","no":78,"unit":"프로그래밍 언어 활용","q":"Myers가 구분한 응집도(Cohesion)의 정도 중 응집도가 가장 낮은 단계는 다음 중 어느 것인가?","choices":["우연적 응집도(Coincidental Cohesion)","기능적 응집도(Functional Cohesion)","순차적 응집도(Sequential Cohesion)","시간적 응집도(Temporal Cohesion)"],"ans":1,"exp":{"concept":"응집도(Cohesion)는 한 모듈 안의 구성 요소들이 서로 얼마나 관련되어 있는지를 나타내며, 높을수록 좋은 설계다. 높은 것부터 기능적, 순차적, 교환(통신)적, 절차적, 시간적, 논리적, 우연적 응집도 순이다. 우연적 응집도는 서로 관련 없는 요소들이 우연히 한 모듈에 모인 경우다.","choices":[{"verdict":"정답","why":"우연적 응집도는 모듈 내부의 각 구성 요소가 서로 관련 없는 요소로만 구성된 경우로, 응집도가 가장 낮다."},{"verdict":"오답","why":"기능적 응집도는 모듈 내부의 모든 기능 요소가 단일 문제와 연관되어 수행되는 경우로, 응집도가 가장 높다."},{"verdict":"오답","why":"순차적 응집도는 한 활동의 출력이 다음 활동의 입력으로 쓰이는 경우로, 기능적 응집도 다음으로 높다."},{"verdict":"오답","why":"시간적 응집도는 특정 시간에 처리되는 기능들을 모아 놓은 경우로, 우연적 응집도보다 높다."}],"keywords":[{"term":"응집도 순서(높음→낮음)","desc":"기능적 > 순차적 > 교환적 > 절차적 > 시간적 > 논리적 > 우연적"},{"term":"결합도 순서(낮음→높음)","desc":"자료 < 스탬프 < 제어 < 외부 < 공통 < 내용"},{"term":"좋은 모듈 설계","desc":"응집도는 높게, 결합도는 낮게"}],"memo":"응집도는 높은 순서대로 '기순교절시논우'로 외운다. 가장 낮은 것은 '우연적'이다."}},{"id":"written-2024-1-79","no":79,"unit":"프로그래밍 언어 활용","q":"다음 중 교착 상태가 발생하기 위한 필요 조건에 해당하지 않는 것은?","choices":["선점(Preemption)","환형 대기(Circular Wait)","점유와 대기(Hold and Wait)","상호 배제(Mutual Exclusion)"],"ans":1,"exp":{"concept":"교착 상태(Deadlock)는 둘 이상의 프로세스가 서로 상대가 가진 자원을 기다리며 영원히 멈춘 상태다. 교착 상태가 생기려면 상호 배제, 점유와 대기, 비선점, 환형 대기의 네 조건이 모두 동시에 충족되어야 한다. 좁은 다리 양쪽에서 차가 마주 보고 서로 비켜 주지 않는 상황과 같다.","choices":[{"verdict":"정답","why":"교착 상태의 필요 조건은 '비선점(Non-Preemption)'이다. 다른 프로세스의 자원을 강제로 빼앗을 수 있는 선점이 가능하면 교착 상태는 발생하지 않는다."},{"verdict":"오답","why":"환형 대기(Circular Wait)는 프로세스들이 원형으로 서로의 자원을 기다리는 것으로, 교착 상태의 필요 조건이다."},{"verdict":"오답","why":"점유와 대기(Hold and Wait)는 자원을 가진 채 다른 자원을 기다리는 것으로, 교착 상태의 필요 조건이다."},{"verdict":"오답","why":"상호 배제(Mutual Exclusion)는 한 자원을 한 번에 한 프로세스만 쓸 수 있는 것으로, 교착 상태의 필요 조건이다."}],"keywords":[{"term":"상호 배제(Mutual Exclusion)","desc":"한 번에 한 프로세스만 자원을 사용"},{"term":"점유와 대기(Hold and Wait)","desc":"자원을 가진 채 다른 자원을 기다림"},{"term":"비선점(Non-Preemption)","desc":"다른 프로세스의 자원을 강제로 빼앗을 수 없음"},{"term":"환형 대기(Circular Wait)","desc":"프로세스들이 원형으로 서로의 자원을 기다림"}],"memo":"교착 상태 4조건은 '상점비환'(상호 배제, 점유와 대기, 비선점, 환형 대기)이다. '선점'이 아니라 '비선점'이다."}},{"id":"written-2024-1-80","no":80,"unit":"프로그래밍 언어 활용","q":"다음 Python 프로그램을 실행했을 때의 출력 결과는?<pre class=\"qcode\"><code class=\"language-python\">String = 'Conceptual Schema'\nr = String[-4:6:-2]\nprint(r)</code></pre>","choices":["ulSh","hSlu","ShmCnep","penCmhS"],"ans":2,"exp":{"concept":"파이썬 슬라이싱 문자열[시작:끝:간격]은 시작 위치부터 끝 위치 바로 앞까지 간격만큼 건너뛰며 문자를 뽑는다. 간격이 음수이면 오른쪽에서 왼쪽으로 거꾸로 진행하며, 음수 인덱스 -1은 맨 마지막 글자를 뜻한다.","choices":[{"verdict":"오답","why":"ulSh는 정답 글자들을 왼쪽에서 오른쪽 순서로 읽은 것이다. 간격이 -2이므로 뒤에서 앞으로 진행해 hSlu 순서로 나온다."},{"verdict":"정답","why":"'Conceptual Schema'는 17글자(인덱스 0~16)이므로 -4는 인덱스 13('h')이다. 13('h'), 11('S'), 9('l'), 7('u')를 뽑고, 다음 5는 끝 위치 6을 지나므로 멈춘다. 결과는 hSlu다."},{"verdict":"오답","why":"ShmCnep은 이 슬라이싱 결과가 아니다. 끝 위치가 6이라 인덱스 6 이하의 글자는 포함되지 않는다."},{"verdict":"오답","why":"penCmhS는 이 슬라이싱 결과가 아니다. 시작은 인덱스 13의 'h'이고 뒤에서 앞으로 2칸씩 이동한다."}],"keywords":[{"term":"슬라이싱","desc":"문자열[시작:끝:간격], 끝 위치는 포함하지 않음"},{"term":"음수 인덱스","desc":"-1은 마지막 글자, -n은 뒤에서 n번째 글자"},{"term":"음수 간격","desc":"간격이 음수면 오른쪽에서 왼쪽으로 진행"}],"memo":"음수 인덱스는 '길이 + 음수'로 바꿔 계산한다. 17 + (-4) = 13. 공백도 한 글자로 센다."}},{"id":"written-2024-1-81","no":81,"unit":"정보시스템 구축 관리","q":"SSH(Secure Shell)에 관한 설명 중 틀린 것은?","choices":["전송되는 데이터는 암호화된다.","SSH는 기본 네트워크 포트로 25번을 사용한다.","서로 연결된 컴퓨터 간에 원격 명령 실행이나 셀 서비스 등을 수행한다.","키를 통한 인증을 하려면 클라이언트의 공개키를 서버에 등록해야 한다."],"ans":2,"exp":{"concept":"SSH(Secure Shell)는 네트워크로 다른 컴퓨터에 접속해 명령을 실행하거나 파일을 옮길 때 데이터를 암호화해 주는 프로토콜이다. 예전의 텔넷(Telnet)이 데이터를 그대로 보냈던 것을 보완했으며, 기본 포트는 22번이다. 키 인증을 쓰려면 클라이언트의 공개키를 서버에 등록해 둔다.","choices":[{"verdict":"오답","why":"SSH는 전송하는 데이터를 암호화한다. 맞는 설명이다."},{"verdict":"정답","why":"SSH의 기본 포트는 22번이다. 25번은 메일을 보내는 SMTP의 기본 포트다."},{"verdict":"오답","why":"SSH는 서로 연결된 컴퓨터 간에 원격 명령 실행이나 쉘 서비스 등을 수행한다. 맞는 설명이다."},{"verdict":"오답","why":"키를 이용한 인증을 하려면 클라이언트의 공개키를 서버에 등록해야 한다. 맞는 설명이다."}],"keywords":[{"term":"SSH(Secure Shell)","desc":"원격 접속과 명령 실행을 암호화해 수행하는 프로토콜, 포트 22"},{"term":"Telnet","desc":"원격 접속 프로토콜, 암호화 없음, 포트 23"},{"term":"SMTP","desc":"전자우편 전송 프로토콜, 포트 25"}],"memo":"FTP 21, SSH 22, Telnet 23, SMTP 25처럼 번호 순서로 묶어 외운다."}},{"id":"written-2024-1-82","no":82,"unit":"정보시스템 구축 관리","q":"Public 메소드에서 Private 배열이 반환되면 발생하는 문제점으로 가장 옳은 것은?","choices":["동기화 오류가 발생하게 된다.","배열의 주소가 외부에 공개되어 외부에서 접근이 가능해진다.","메소드에 대한 접근이 불가능해진다.","시스템 내부 정보가 노출된다."],"ans":2,"exp":{"concept":"Private 배열은 클래스 안에서만 다루도록 숨겨 둔 데이터다. 그런데 Public 메소드가 이 배열을 그대로 반환하면 배열 자체가 아니라 배열의 주소(참조)가 외부로 넘어가, 외부에서 그 주소로 배열 내용을 마음대로 바꿀 수 있게 된다. 이는 캡슐화 보안 약점에 해당하며, 배열의 복사본을 반환하는 방식으로 막는다.","choices":[{"verdict":"오답","why":"동기화 오류는 여러 스레드가 공유 자원에 동시에 접근할 때 생기는 문제로, Private 배열 반환과는 다른 시간 및 상태 관련 보안 약점이다."},{"verdict":"정답","why":"Private 배열을 Public 메소드가 반환하면 배열의 주소가 외부에 공개되어 외부에서 배열에 접근하고 수정할 수 있게 된다."},{"verdict":"오답","why":"메소드에 대한 접근이 불가능해지는 문제는 생기지 않는다. Public 메소드이므로 오히려 외부에서 호출할 수 있다."},{"verdict":"오답","why":"시스템 내부 정보 노출은 오류 메시지 등으로 시스템 정보가 드러나는 별도의 보안 약점이다. 이 문항의 핵심은 배열 주소가 공개되어 외부에서 접근할 수 있게 되는 것이다."}],"keywords":[{"term":"Public 메소드로부터 반환된 Private 배열","desc":"배열 주소가 외부에 공개되어 외부에서 수정 가능, 복사본 반환으로 해결"},{"term":"Private 배열에 Public 데이터 할당","desc":"Public으로 받은 데이터를 Private 배열에 그대로 저장해 외부에서 접근 가능해지는 약점"},{"term":"캡슐화(Encapsulation)","desc":"데이터와 기능을 묶고 내부 구현을 숨기는 것"}],"memo":"배열은 값이 아니라 '주소'로 전달된다. 주소를 넘기면 집 열쇠를 넘기는 것과 같다."}},{"id":"written-2024-1-83","no":83,"unit":"정보시스템 구축 관리","q":"다음 중 물리적 위협으로 인한 문제에 해당되지 않는 것은?","choices":["하드웨어의 파손이나 고장으로 인한 장애","방화, 테러로 하드웨어와 기록장치를 물리적으로 파괴하는 행위","방화벽 설정을 잘못 조작하여 발생하는 네트워크, 서버 보안 위협","화재, 홍수 등 천재지변에 따른 위협"],"ans":3,"exp":{"concept":"정보 시스템에 대한 위협은 물리적 위협과 기술적(논리적) 위협 등으로 나눌 수 있다. 물리적 위협은 하드웨어 고장, 화재나 홍수 같은 자연재해, 시설을 부수는 파괴 행위처럼 장비나 시설 자체에 직접 피해를 주는 것이다. 설정 실수나 해킹처럼 소프트웨어와 네트워크를 통해 생기는 위협은 물리적 위협이 아니다.","choices":[{"verdict":"오답","why":"하드웨어의 파손이나 고장으로 인한 장애는 장비에 직접 생기는 물리적 위협이다."},{"verdict":"오답","why":"방화나 테러로 하드웨어와 기록 장치를 파괴하는 것은 물리적 위협이다."},{"verdict":"정답","why":"방화벽 설정을 잘못 조작해 생기는 보안 위협은 장비 자체가 손상되는 것이 아니라 설정과 운영의 실수로 생기는 기술적(논리적) 위협이다."},{"verdict":"오답","why":"화재, 홍수 등 천재지변에 따른 위협은 물리적 위협이다."}],"keywords":[{"term":"물리적 위협","desc":"하드웨어 고장, 자연재해, 시설 파괴 등 장비와 시설에 대한 직접 피해"},{"term":"기술적(논리적) 위협","desc":"설정 오류, 해킹, 악성 코드 등 소프트웨어와 네트워크를 통한 위협"},{"term":"방화벽(Firewall)","desc":"내부 네트워크로 들어오는 트래픽을 감시하고 차단하는 보안 시스템"}],"memo":"'불, 물, 부수기, 고장'은 물리적 위협이다. '설정', '조작'은 물리적이 아니다."}},{"id":"written-2024-1-84","no":84,"unit":"정보시스템 구축 관리","q":"무선 랜에서 데이터를 전송할 때 매체가 비어 있는지 확인하고, 충돌을 피하고자 일정 시간 대기한 뒤 데이터를 전송하는 방식은?","choices":["VLAN","L2AN","STP","CSMA/CA"],"ans":4,"exp":{"concept":"여러 장치가 하나의 매체를 함께 쓰면 동시에 보낸 데이터끼리 충돌이 생길 수 있다. 무선 랜은 전송 중에 충돌을 감지하기 어렵기 때문에, 보내기 전에 매체가 비어 있는지 확인하고 일정 시간을 기다린 뒤 전송해 충돌을 미리 피한다. 이 방식이 CSMA/CA다.","choices":[{"verdict":"오답","why":"VLAN(Virtual LAN)은 물리적 배치와 관계없이 논리적으로 LAN을 나누는 기술이다."},{"verdict":"오답","why":"L2AN은 무선 랜 매체 접근 방식이 아니며, 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"STP(Spanning Tree Protocol)는 스위치 네트워크에서 루프(순환 경로)가 생기지 않도록 막는 프로토콜이다."},{"verdict":"정답","why":"CSMA/CA(Carrier Sense Multiple Access with Collision Avoidance)는 무선 랜에서 매체가 비어 있는지 확인하고 일정 시간 대기한 뒤 전송해 충돌을 회피하는 방식이다."}],"keywords":[{"term":"CSMA/CA","desc":"충돌 회피(Collision Avoidance), 무선 랜(IEEE 802.11)에서 사용"},{"term":"CSMA/CD","desc":"충돌 감지(Collision Detection), 유선 이더넷(IEEE 802.3)에서 사용"},{"term":"VLAN","desc":"논리적으로 분리된 가상 LAN"}],"memo":"CA는 Avoidance(회피)로 무선, CD는 Detection(감지)으로 유선이다."}},{"id":"written-2024-1-85","no":85,"unit":"정보시스템 구축 관리","q":"OSI 7 Layer 전 계층의 프로토콜 및 패킷 내부 콘텐츠를 파악해 침입 시도, 해킹 등을 탐지하고 트래픽을 조정하는 데 쓰이는 패킷 분석 기술은?","choices":["Traffic Distributor","PLCP(Packet Level Control Processor)","DPI(Deep Packet Inspection)","Packet Tree"],"ans":3,"exp":{"concept":"DPI(Deep Packet Inspection)는 패킷의 헤더만 보는 일반 검사와 달리, OSI 7계층 전 계층의 프로토콜과 패킷 안의 내용(페이로드)까지 깊이 들여다보는 분석 기술이다. 이를 통해 침입 시도나 해킹을 탐지하고 트래픽을 조정한다. 택배 상자의 송장만 보는 것이 아니라 상자를 열어 내용물까지 확인하는 것과 같다.","choices":[{"verdict":"오답","why":"Traffic Distributor는 패킷 내부 콘텐츠까지 분석하는 기술의 이름이 아니며, 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"PLCP(Packet Level Control Processor)는 OSI 전 계층과 패킷 콘텐츠를 분석하는 기술이 아니며, 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"DPI는 OSI 7계층 전 계층의 프로토콜과 패킷 내부 콘텐츠를 파악해 침입 시도, 해킹 등을 탐지하고 트래픽을 조정하는 패킷 분석 기술이다."},{"verdict":"오답","why":"Packet Tree는 패킷 분석 기술의 이름이 아니며, 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"DPI(Deep Packet Inspection)","desc":"OSI 전 계층과 패킷 내용까지 분석해 침입 탐지와 트래픽 조정"},{"term":"IDS(Intrusion Detection System)","desc":"침입 탐지 시스템, 비정상 사용과 오용을 탐지"},{"term":"IPS(Intrusion Prevention System)","desc":"침입 방지 시스템, 탐지와 함께 차단"}],"memo":"Deep(깊이) Packet(패킷) Inspection(검사), 패킷을 깊이까지 들여다본다는 이름 그대로다."}},{"id":"written-2024-1-86","no":86,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 IT 기술은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>컨테이너 응용프로그램의 배포를 자동화하는 오픈소스 엔진이다.</li><li>소프트웨어 컨테이너 안에 응용 프로그램들을 배치시키는 작업을 자동화해 주는 오픈 소스 프로젝트이자 소프트웨어라고 볼 수 있다.</li></ul></div>","choices":["Stack Guard","Scytale","Docker","Cipher Container"],"ans":3,"exp":{"concept":"컨테이너(Container)는 응용 프로그램과 실행에 필요한 라이브러리, 설정 등을 하나로 묶어 어디서나 똑같이 실행되게 하는 가상화 방식이다. Docker는 이런 컨테이너 응용 프로그램의 배포를 자동화하는 오픈소스 엔진이다. 화물을 규격 컨테이너에 담으면 어느 배나 트럭에도 그대로 싣는 것과 비슷하다.","choices":[{"verdict":"오답","why":"스택 가드(Stack Guard)는 복귀 주소와 변수 사이에 특정 값을 저장해 두고 그 값이 바뀌면 오버플로로 판단해 실행을 중단하는 메모리 보호 기술이다."},{"verdict":"오답","why":"스키테일(Scytale)은 문자열의 위치를 바꾸는 방식의 고대 암호화 기법으로, 컨테이너 배포 자동화와 관계없다."},{"verdict":"정답","why":"Docker는 컨테이너 응용 프로그램의 배포를 자동화하는 오픈소스 엔진으로, 소프트웨어 컨테이너 안에 응용 프로그램을 배치하는 작업을 자동화한다."},{"verdict":"오답","why":"Cipher Container는 컨테이너 배포 자동화 엔진이 아니며, 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"도커(Docker)","desc":"컨테이너 응용 프로그램의 배포를 자동화하는 오픈소스 엔진"},{"term":"쿠버네티스(Kubernetes)","desc":"컨테이너화된 애플리케이션의 배포, 확장, 관리를 자동화하는 오픈소스 플랫폼"},{"term":"스택 가드(Stack Guard)","desc":"복귀 주소 앞에 특정 값을 두어 스택 오버플로를 탐지하는 기술"}],"memo":"'컨테이너 배포 자동화'는 Docker, '컨테이너 운영·관리 자동화(오케스트레이션)'는 쿠버네티스다."}},{"id":"written-2024-1-87","no":87,"unit":"정보시스템 구축 관리","q":"Secure 코딩에서 입력 데이터의 보안 약점에 관한 설명 중 틀린 것은?","choices":["운영체제 명령어 삽입 : 운영체제 명령어 파라미터 입력 값이 적절한 사전검증 없이 사용되어 공격자가 운영체제 명령어를 조작함","SQL 삽입 : 사용자의 입력 값 등 외부 입력 값이 SQL 쿼리에 삽입되어 공격이 이루어짐","자원 삽입 : 사용자가 내부 입력 값을 통해 시스템 내에서 사용이 불가능한 자원을 지속적으로 입력하여 시스템에 과부하가 발생함","크로스사이트 스크립트 : 검증되지 않은 외부 입력 값으로 인해 브라우저에서 악의적인 코드가 실행됨"],"ans":3,"exp":{"concept":"시큐어 코딩에서 입력 데이터 검증 및 표현 약점은 외부에서 들어온 값을 제대로 검사하지 않아서 생기는 보안 약점이다. 자원 삽입(Resource Injection)은 외부 입력 값을 검증 없이 IP, 포트, 파일 같은 시스템 자원의 식별자로 사용해, 공격자가 그 자원을 조작할 수 있게 되는 약점이다.","choices":[{"verdict":"오답","why":"운영체제 명령어 삽입은 외부 입력 값이 사전 검증 없이 운영체제 명령어의 일부로 쓰여 공격자가 명령어를 조작하는 약점이다. 맞는 설명이다."},{"verdict":"오답","why":"SQL 삽입은 외부 입력 값이 SQL 쿼리에 그대로 삽입되어 공격이 이뤄지는 약점이다. 맞는 설명이다."},{"verdict":"정답","why":"자원 삽입은 사용 불가능한 자원을 계속 입력해 과부하를 일으키는 것이 아니라, 외부 입력 값을 검증 없이 시스템 자원 식별자로 사용해 공격자가 자원을 조작할 수 있게 되는 약점이다."},{"verdict":"오답","why":"크로스사이트 스크립트(XSS)는 검증되지 않은 외부 입력 값 때문에 사용자 브라우저에서 악의적인 스크립트가 실행되는 약점이다. 맞는 설명이다."}],"keywords":[{"term":"SQL 삽입(SQL Injection)","desc":"입력 값에 SQL 문을 넣어 DB 정보를 열람하거나 조작"},{"term":"크로스사이트 스크립트(XSS)","desc":"웹 페이지에 악의적인 스크립트를 삽입해 사용자 브라우저에서 실행"},{"term":"운영체제 명령어 삽입","desc":"외부 입력 값으로 운영체제 명령어를 조작"},{"term":"자원 삽입(Resource Injection)","desc":"외부 입력 값을 검증 없이 시스템 자원 식별자로 사용해 자원을 조작"}],"memo":"입력 데이터 약점은 모두 '검증 안 된 외부 입력'이 원인이다. '과부하'는 서비스 거부 공격의 설명이다."}},{"id":"written-2024-1-88","no":88,"unit":"정보시스템 구축 관리","q":"프로젝트의 각 작업이 언제 시작되고 언제 끝나는지를 나타내는 작업 일정을 막대 도표로 표시하는 프로젝트 일정표는 무엇인가?","choices":["임계 경로 기법","WBS","간트 차트","PERT"],"ans":3,"exp":{"concept":"간트 차트(Gantt Chart)는 프로젝트의 각 작업이 언제 시작하고 언제 끝나는지를 가로 막대로 나타낸 일정표다. 가로축은 시간, 세로축은 작업이며, 막대 길이가 작업 기간을 뜻한다. 시간선(Time-Line) 차트라고도 한다.","choices":[{"verdict":"오답","why":"임계 경로 기법(CPM, Critical Path Method)은 노드와 간선으로 작업 간 관계를 나타내고, 가장 오래 걸리는 경로를 찾아 프로젝트 기간을 산정하는 기법이다."},{"verdict":"오답","why":"WBS(Work Breakdown Structure)는 프로젝트의 전체 작업을 계층적으로 잘게 나눈 작업 분할 구조다."},{"verdict":"정답","why":"간트 차트는 각 작업의 시작과 종료 시점을 막대 도표로 표시하는 일정표다."},{"verdict":"오답","why":"PERT(Program Evaluation and Review Technique)는 작업의 일정을 비관치, 중간치, 낙관치의 3점 추정으로 예측하고 네트워크로 표현하는 기법이다."}],"keywords":[{"term":"간트 차트(Gantt Chart)","desc":"작업 일정을 막대로 표시한 시간선 차트"},{"term":"CPM(Critical Path Method)","desc":"임계 경로를 찾아 프로젝트 소요 기간을 산정"},{"term":"PERT","desc":"낙관치, 중간치(최빈치), 비관치의 3점 추정을 이용한 일정 계획"},{"term":"WBS(Work Breakdown Structure)","desc":"프로젝트 작업을 계층적으로 분해한 구조"}],"memo":"'막대'라는 말이 나오면 간트 차트다."}},{"id":"written-2024-1-89","no":89,"unit":"정보시스템 구축 관리","q":"취약점 관리를 위한 응용 프로그램 보안 설정으로 가장 거리가 먼 것은?","choices":["서버 관리실의 출입 통제","운영체제 정보 수집 제한","실행 프로세스의 권한 설정","운영체제 접근 제한"],"ans":1,"exp":{"concept":"취약점 관리를 위한 응용 프로그램 보안 설정은 서버의 운영체제와 응용 프로그램 쪽 설정으로 공격 가능성을 줄이는 것이다. 예를 들어 운영체제 정보가 노출되지 않게 하고, 실행 프로세스에 필요한 권한만 주며, 운영체제 접근을 제한한다. 사람이 서버실에 드나드는 것을 막는 것은 소프트웨어 설정이 아닌 물리적 보안이다.","choices":[{"verdict":"정답","why":"서버 관리실의 출입 통제는 물리적 보안 대책으로, 응용 프로그램의 보안 설정과 거리가 멀다."},{"verdict":"오답","why":"운영체제 정보 수집 제한은 공격자가 시스템 정보를 얻지 못하게 하는 응용 프로그램 보안 설정이다."},{"verdict":"오답","why":"실행 프로세스의 권한 설정은 프로세스에 꼭 필요한 권한만 주어 피해를 줄이는 응용 프로그램 보안 설정이다."},{"verdict":"오답","why":"운영체제 접근 제한은 허가되지 않은 접근을 막는 응용 프로그램 보안 설정이다."}],"keywords":[{"term":"취약점(Vulnerability)","desc":"시스템이나 프로그램에서 보안 위협이 될 수 있는 약점"},{"term":"물리적 보안","desc":"출입 통제, 잠금 장치 등 시설과 장비에 대한 보안"},{"term":"최소 권한 원칙","desc":"프로세스나 사용자에게 필요한 최소한의 권한만 부여"}],"memo":"보기 중 '사람이 드나드는 공간'을 다루는 것은 물리적 보안이다."}},{"id":"written-2024-1-90","no":90,"unit":"정보시스템 구축 관리","q":"다음이 설명하는 것은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>광채널 스위치의 이점인 고속 전송, 장거리 연결 및 멀티 프로토콜 기능을 네트워크상에서 활용</li><li>서로 다른 운영체제를 가진 여러 기종이 네트워크상에서 동일한 저장장치의 데이터를 공유하도록 하여, 여러 개의 저장장치나 백업 장비를 단일화한 시스템</li></ul></div>","choices":["MBR","NIC","NAC","SAN"],"ans":4,"exp":{"concept":"SAN(Storage Area Network)은 서버와 저장 장치를 전용 네트워크로 연결해, 여러 서버가 같은 저장 장치를 공유하도록 만든 저장 장치 구성 방식이다. 광채널(Fibre Channel) 스위치를 이용해 빠르게 데이터를 주고받으며, 서로 다른 운영체제를 쓰는 서버도 저장 장치를 함께 쓸 수 있다.","choices":[{"verdict":"오답","why":"MBR(Master Boot Record)은 저장 장치의 첫 영역에 있는 부팅 정보와 파티션 정보를 담은 기록이다."},{"verdict":"오답","why":"NIC(Network Interface Card)는 컴퓨터를 네트워크에 연결해 주는 랜카드다."},{"verdict":"오답","why":"NAC(Network Access Control)는 네트워크에 접속하는 단말기의 보안 상태를 점검해 접근을 통제하는 보안 솔루션이다."},{"verdict":"정답","why":"SAN은 광채널 스위치로 고속 전송, 장거리 연결, 멀티 프로토콜을 활용하며, 이기종 서버가 동일한 저장 장치의 데이터를 공유하도록 저장 장치와 백업 장비를 단일화한 시스템이다."}],"keywords":[{"term":"SAN(Storage Area Network)","desc":"전용 네트워크(광채널)로 서버와 저장 장치를 연결해 공유"},{"term":"NAS(Network Attached Storage)","desc":"서버와 저장 장치를 일반 네트워크(LAN)로 연결"},{"term":"DAS(Direct Attached Storage)","desc":"서버에 저장 장치를 직접 연결"}],"memo":"'광채널', '저장 장치 공유'가 나오면 SAN이다. 저장 장치 연결 방식은 DAS, NAS, SAN 세 가지로 묶어 외운다."}},{"id":"written-2024-1-91","no":91,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 모델 가운데 나선형 모델의 4가지 주요 활동을 순서대로 나열한 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul class=\"is-labeled\"><li>A. 계획 수립</li><li>B. 고객 평가</li><li>C. 개발 및 검증</li><li>D. 위험 분석</li></ul></div>","choices":["Ⓐ-Ⓑ-Ⓓ-Ⓒ 순으로 반복","Ⓐ-Ⓓ-Ⓒ-Ⓑ 순으로 반복","Ⓐ-Ⓒ-Ⓑ-Ⓓ 순으로 반복","Ⓐ-Ⓑ-Ⓒ-Ⓓ 순으로 반복"],"ans":2,"exp":{"concept":"나선형 모형(Spiral Model)은 개발 과정을 여러 번 반복하며 점점 완성도를 높이는 모형으로, 매 반복마다 위험을 분석해 줄이는 것이 특징이다. 한 바퀴는 계획 수립 → 위험 분석 → 개발 및 검증 → 고객 평가 순서로 돌고, 이를 반복한다.","choices":[{"verdict":"오답","why":"고객 평가는 개발 결과를 보고 하는 것이므로 계획 바로 다음에 올 수 없다. 위험 분석이 계획 다음이다."},{"verdict":"정답","why":"계획 수립(A) → 위험 분석(D) → 개발 및 검증(C) → 고객 평가(B) 순서로 반복하는 것이 나선형 모형의 4가지 주요 활동이다."},{"verdict":"오답","why":"위험 분석이 맨 뒤에 오고 개발이 먼저 오면, 위험을 줄이고 개발한다는 나선형 모형의 핵심과 맞지 않는다."},{"verdict":"오답","why":"고객 평가가 개발보다 앞서고 위험 분석이 맨 뒤에 있어 순서가 맞지 않는다."}],"keywords":[{"term":"나선형 모형(Spiral Model)","desc":"위험 분석을 반복하며 점진적으로 개발하는 모형, 보헴(Boehm)이 제안"},{"term":"나선형 모형 4단계","desc":"계획 수립 → 위험 분석 → 개발 및 검증 → 고객 평가"},{"term":"위험 분석(Risk Analysis)","desc":"프로젝트 위험을 찾아 평가하고 대비책을 세우는 활동"}],"memo":"나선형은 '계획 → 위험 → 개발 → 평가', 계획 바로 다음에 위험 분석이 온다는 점이 핵심이다."}},{"id":"written-2024-1-92","no":92,"unit":"정보시스템 구축 관리","q":"COCOMO Model 가운데 기관 내부에서 개발되는 중·소 규모의 소프트웨어로서, 일괄 자료 처리나 과학기술 계산용, 비즈니스 자료 처리용 등 5만 라인 이하의 소프트웨어를 개발하는 유형은 무엇인가?","choices":["Embeded","Semi-Detached","Semi-Embeded","Organic"],"ans":4,"exp":{"concept":"COCOMO 모형은 원시 코드 라인 수(LOC)를 바탕으로 비용을 산정하며, 소프트웨어를 규모와 성격에 따라 세 유형으로 나눈다. 조직형(Organic)은 기관 내부에서 개발하는 5만 라인 이하의 중소 규모, 반분리형(Semi-Detached)은 30만 라인 이하의 트랜잭션 처리 시스템이나 운영체제 등, 내장형(Embedded)은 30만 라인 이상의 초대형 규모 시스템이다.","choices":[{"verdict":"오답","why":"내장형(Embedded)은 30만 라인 이상의 초대형 규모 소프트웨어 유형이다."},{"verdict":"오답","why":"반분리형(Semi-Detached)은 30만 라인 이하의 트랜잭션 처리 시스템, 운영체제 등 조직형과 내장형의 중간 유형이다."},{"verdict":"오답","why":"Semi-Embedded는 COCOMO의 소프트웨어 개발 유형에 없는 이름이다."},{"verdict":"정답","why":"조직형(Organic)은 기관 내부에서 개발되는 중소 규모 소프트웨어로, 일괄 자료 처리, 과학기술 계산용, 비즈니스 자료 처리용 등 5만 라인 이하의 소프트웨어를 개발하는 유형이다."}],"keywords":[{"term":"조직형(Organic)","desc":"5만 라인 이하, 기관 내부 중소 규모 소프트웨어"},{"term":"반분리형(Semi-Detached)","desc":"30만 라인 이하, 트랜잭션 처리 시스템이나 운영체제 등"},{"term":"내장형(Embedded)","desc":"30만 라인 이상, 초대형 규모의 소프트웨어"},{"term":"COCOMO 모형","desc":"보헴이 제안, LOC 기반 비용 산정, 기본형·중간형·발전형으로 나뉨"}],"memo":"규모가 작은 순서로 '조직형(5만 이하) → 반분리형(30만 이하) → 내장형(30만 이상)'이다."}},{"id":"written-2024-1-93","no":93,"unit":"정보시스템 구축 관리","q":"LOC 기법으로 예측한 총 라인수가 36,000라인이고, 개발에 참여하는 프로그래머가 6명이며, 프로그래머들의 평균 생산성이 월간 300라인일 때 개발에 소요되는 기간은?","choices":["5개월","10개월","15개월","20개월"],"ans":4,"exp":{"concept":"LOC(Line Of Code) 기법은 프로그램의 예상 라인 수로 개발 비용과 기간을 산정한다. 노력(인월) = 총 라인 수 / 1인당 월평균 생산 라인 수이고, 개발 기간 = 노력(인월) / 투입 인원이다.","choices":[{"verdict":"오답","why":"5개월은 계산 결과와 맞지 않는다. 36,000 / (6 × 300) = 20개월이다."},{"verdict":"오답","why":"10개월은 계산 결과와 맞지 않는다. 6명이 한 달에 만드는 라인은 1,800이므로 10개월에는 18,000라인밖에 만들지 못한다."},{"verdict":"오답","why":"15개월은 계산 결과와 맞지 않는다. 15개월이면 27,000라인만 만들 수 있다."},{"verdict":"정답","why":"노력 = 36,000 / 300 = 120인월이고, 개발 기간 = 120 / 6 = 20개월이다."}],"keywords":[{"term":"LOC 기법","desc":"원시 코드 라인 수의 비관치, 낙관치, 기대치로 예측치를 구해 비용을 산정"},{"term":"노력(인월)","desc":"총 라인 수 / 1인당 월평균 생산성"},{"term":"개발 기간","desc":"노력(인월) / 투입 인원"}],"memo":"먼저 '한 달에 팀이 만드는 라인 수'(6 × 300 = 1,800)를 구하고, 전체 라인 수를 그것으로 나누면 바로 기간이 나온다."}},{"id":"written-2024-1-94","no":94,"unit":"정보시스템 구축 관리","q":"구조적 방법론에 관한 설명 중 옳은 것은?","choices":["새로운 기능의 추가가 간단하므로 확장성이 보장된다.","구성 요소로는 객체, 클래스, 메시지 등을 들 수 있다.","분할과 정복(Divide and Conquer) 원리가 적용된다.","자료(Data)를 중심으로 하는 방법론이다."],"ans":3,"exp":{"concept":"구조적 방법론은 처리(절차) 중심으로, 복잡한 문제를 작은 문제로 나눠 하나씩 해결하는 분할과 정복(Divide and Conquer) 원리를 적용한다. 자료 흐름도(DFD), 자료 사전(DD), 소단위 명세서 같은 도구를 쓴다.","choices":[{"verdict":"오답","why":"새 기능을 쉽게 추가해 확장성을 보장하는 것은 상속과 캡슐화를 활용하는 객체지향 방법론의 장점이다."},{"verdict":"오답","why":"객체, 클래스, 메시지는 객체지향 방법론의 구성 요소다."},{"verdict":"정답","why":"구조적 방법론은 복잡한 문제를 작게 나눠 해결하는 분할과 정복 원리를 적용한다."},{"verdict":"오답","why":"자료(Data)를 중심으로 하는 방법론은 정보공학 방법론이다. 구조적 방법론은 처리(절차) 중심이다."}],"keywords":[{"term":"구조적 방법론","desc":"처리(절차) 중심, 분할과 정복, DFD·DD·소단위 명세서 사용"},{"term":"정보공학 방법론","desc":"자료(데이터) 중심, 기업 전체의 정보 시스템 구축에 적합"},{"term":"객체지향 방법론","desc":"객체, 클래스, 메시지를 기반으로 상속과 캡슐화 활용"},{"term":"CBD 방법론","desc":"컴포넌트를 조립해 소프트웨어를 개발"}],"memo":"구조적은 '절차·분할 정복', 정보공학은 '자료', 객체지향은 '객체·클래스·메시지'로 짝짓는다."}},{"id":"written-2024-1-95","no":95,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 IT 기술은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>네트워크를 제어부와 데이터 전달부로 분리하여 네트워크 관리자가 더욱 효율적으로 네트워크를 제어하고 관리할 수 있도록 하는 기술</li><li>기존의 라우터, 스위치 등과 같이 하드웨어에 의존하는 네트워크 체계에서 안정성, 속도, 보안 등을 소프트웨어로 제어하고 관리하기 위해 개발됨</li><li>네트워크 장비의 펌웨어 업그레이드를 통해 사용자가 직접 데이터 전송 경로를 관리할 수 있으며, 기존 네트워크에는 영향을 주지 않은 채 특정 서비스의 전송 경로를 수정하여 인터넷상에서 발생하는 문제를 처리할 수 있음</li></ul></div>","choices":["AOE Network","NFS(Network File System)","Network Mapper","SDN(Software Defined Networking)"],"ans":4,"exp":{"concept":"SDN(Software Defined Networking)은 네트워크 장비에서 경로를 결정하는 제어부와 실제로 데이터를 전달하는 데이터 전달부를 분리하고, 제어부를 소프트웨어로 프로그래밍해 네트워크를 관리하는 기술이다. 하드웨어에 묶여 있던 네트워크 제어를 소프트웨어로 옮겨 유연하게 경로를 바꿀 수 있다.","choices":[{"verdict":"오답","why":"AOE 네트워크(Activity On Edge Network)는 간선에 작업을 표시해 프로젝트 일정을 나타내는 그래프로, 네트워크 제어 기술이 아니다."},{"verdict":"오답","why":"NFS(Network File System)는 네트워크로 연결된 다른 컴퓨터의 파일을 자신의 파일처럼 쓰게 해 주는 파일 공유 시스템이다."},{"verdict":"오답","why":"Network Mapper(Nmap)는 네트워크의 호스트와 열린 포트를 탐색하는 스캐닝 도구다."},{"verdict":"정답","why":"SDN은 네트워크를 제어부와 데이터 전달부로 분리하고, 소프트웨어로 네트워크의 경로와 정책을 제어하고 관리하는 기술이다."}],"keywords":[{"term":"SDN(Software Defined Networking)","desc":"제어부와 데이터 전달부를 분리해 소프트웨어로 네트워크를 제어"},{"term":"NFV(Network Functions Virtualization)","desc":"방화벽, 라우터 등 네트워크 장비 기능을 소프트웨어로 가상화"},{"term":"NFS(Network File System)","desc":"네트워크상의 파일을 공유하는 파일 시스템"}],"memo":"'소프트웨어로 네트워크를 제어'한다는 단서가 이름 Software Defined Networking에 그대로 들어 있다."}},{"id":"written-2024-1-96","no":96,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발에서 정보보안 3요소에 해당하지 않는 설명은 무엇인가?","choices":["휘발성 : 인가된 사용자가 수행한 데이터는 처리가 완료되는 즉시 폐기되어야 한다.","가용성 : 인가된 사용자는 보유한 권한 범위 내에서 언제든지 자원에 접근할 수 있다.","기밀성 : 인가된 사용자만 자원에 접근할 수 있다.","무결성 : 인가된 사용자만 자원을 수정할 수 있으며, 전송 중인 정보는 수정되지 않는다."],"ans":1,"exp":{"concept":"정보 보안의 3요소는 기밀성, 무결성, 가용성(CIA)이다. 기밀성은 허락받은 사람만 볼 수 있게 하는 것, 무결성은 허락받은 사람만 고칠 수 있고 내용이 바뀌지 않게 하는 것, 가용성은 허락받은 사람이 필요할 때 언제든 쓸 수 있게 하는 것이다.","choices":[{"verdict":"정답","why":"휘발성은 정보 보안 3요소가 아니다. 3요소는 기밀성, 무결성, 가용성이다."},{"verdict":"오답","why":"가용성(Availability)은 인가된 사용자가 권한 범위 내에서 언제든 자원에 접근할 수 있게 하는 것으로, 정보 보안 3요소에 해당한다."},{"verdict":"오답","why":"기밀성(Confidentiality)은 인가된 사용자만 자원에 접근할 수 있게 하는 것으로, 정보 보안 3요소에 해당한다."},{"verdict":"오답","why":"무결성(Integrity)은 인가된 사용자만 자원을 수정할 수 있고 전송 중인 정보가 수정되지 않게 하는 것으로, 정보 보안 3요소에 해당한다."}],"keywords":[{"term":"기밀성(Confidentiality)","desc":"인가된 사용자만 정보에 접근"},{"term":"무결성(Integrity)","desc":"인가된 사용자만 수정 가능, 정보가 변조되지 않음"},{"term":"가용성(Availability)","desc":"인가된 사용자가 필요할 때 언제든 사용 가능"},{"term":"인증(Authentication)과 부인 방지(Non-Repudiation)","desc":"3요소에 더해 함께 다루는 보안 요소"}],"memo":"보안 3요소는 영문 첫 글자를 따서 CIA(Confidentiality, Integrity, Availability)로 외운다."}},{"id":"written-2024-1-97","no":97,"unit":"정보시스템 구축 관리","q":"메모리 상에서 프로그램의 복귀 주소와 변수 사이에 특정 값을 저장해 두고, 그 값이 변경되면 오버플로우 상태로 간주하여 프로그램 실행을 중단시키는 기술은?","choices":["모드체크","스택가드","리커버리 통제","시스로그"],"ans":2,"exp":{"concept":"스택 가드(Stack Guard)는 버퍼 오버플로 공격으로부터 복귀 주소를 지키는 기술이다. 함수가 호출될 때 복귀 주소와 변수 사이에 특정 값(카나리아 값)을 넣어 두고, 함수가 끝날 때 이 값이 바뀌었으면 오버플로가 일어났다고 보고 프로그램 실행을 중단한다. 탄광에서 유독 가스를 먼저 알아채도록 카나리아를 두었던 것에서 이름이 왔다.","choices":[{"verdict":"오답","why":"모드체크는 오버플로를 탐지해 실행을 중단하는 기술이 아니며, 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"스택 가드는 복귀 주소와 변수 사이에 특정 값을 저장하고, 그 값이 변경되면 오버플로 상태로 판단해 프로그램 실행을 중단하는 기술이다."},{"verdict":"오답","why":"리커버리 통제는 복귀 주소와 변수 사이에 값을 두어 오버플로를 탐지하는 기술이 아니며, 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"시스로그(Syslog)는 시스템에서 발생하는 이벤트와 로그를 기록하고 관리하는 방식으로, 오버플로 탐지 기술이 아니다."}],"keywords":[{"term":"스택 가드(Stack Guard)","desc":"복귀 주소 앞에 특정 값을 두어 변경 시 오버플로로 판단하고 실행 중단"},{"term":"스택 실드(Stack Shield)","desc":"함수 시작 시 복귀 주소를 별도 영역에 저장해 두었다가 종료 시 비교"},{"term":"ASLR(Address Space Layout Randomization)","desc":"메모리 주소 배치를 무작위로 바꿔 공격을 어렵게 하는 기술"},{"term":"버퍼 오버플로(Buffer Overflow)","desc":"할당된 메모리 범위를 넘어 데이터를 써서 다른 영역을 덮어쓰는 공격"}],"memo":"'복귀 주소와 변수 사이에 값', '값이 바뀌면 중단'이라는 단서는 스택 가드다. 복귀 주소를 따로 복사해 비교하면 스택 실드다."}},{"id":"written-2024-1-98","no":98,"unit":"정보시스템 구축 관리","q":"소프트웨어 비용 산정에 관한 설명 중 옳지 않은 것은 다음 중 어느 것인가?","choices":["소프트웨어 비용 결정 요소로는 프로젝트 요소, 자원 요소, 생산성 요소가 있다.","소프트웨어의 규모와 인력 등의 요소를 바탕으로 개발에 드는 비용을 예측하는 것이다.","소프트웨어 비용을 높게 산정하면 예산 낭비와 일의 효율성 저하를 초래할 수 있다.","소프트웨어 비용 산정 기법으로는 상향식, 하향식, 혼합식 기법이 있다."],"ans":4,"exp":{"concept":"소프트웨어 비용 산정은 개발에 필요한 인원, 기간, 자원 등을 바탕으로 비용을 미리 예측하는 것이다. 비용 결정 요소는 프로젝트 요소, 자원 요소, 생산성 요소이고, 산정 기법은 전문가의 경험에 의존하는 하향식 기법과 세부 작업 단위로 계산해 합하는 상향식 기법으로 나눈다.","choices":[{"verdict":"오답","why":"비용 결정 요소는 프로젝트 요소(제품 복잡도, 시스템 크기, 요구 신뢰도), 자원 요소(인적, 하드웨어, 소프트웨어 자원), 생산성 요소(개발자 능력, 개발 기간)다. 맞는 설명이다."},{"verdict":"오답","why":"비용 산정은 소프트웨어의 규모와 인력 등을 바탕으로 개발 비용을 예측하는 것이다. 맞는 설명이다."},{"verdict":"오답","why":"비용을 너무 높게 산정하면 예산 낭비와 일의 효율성 저하를 부르고, 너무 낮게 산정하면 품질이 떨어진다. 맞는 설명이다."},{"verdict":"정답","why":"소프트웨어 비용 산정 기법은 하향식 기법과 상향식 기법으로 나뉜다. 혼합식 기법은 구분에 포함되지 않는다."}],"keywords":[{"term":"하향식 비용 산정 기법","desc":"전문가 감정 기법, 델파이 기법"},{"term":"상향식 비용 산정 기법","desc":"LOC 기법, 개발 단계별 인월수 기법, 수학적 산정 기법(COCOMO, Putnam, FP)"},{"term":"비용 결정 요소","desc":"프로젝트 요소, 자원 요소, 생산성 요소"}],"memo":"비용 산정 기법은 '하향식(전문가, 델파이)'과 '상향식(LOC, 단계별 인월수, 수학적)' 두 가지뿐이다."}},{"id":"written-2024-1-99","no":99,"unit":"정보시스템 구축 관리","q":"DDoS 공격과 관련이 있는 공격 방법은 무엇인가?","choices":["Nimda","Deadlock","Secure shell","Tribe Flood Network"],"ans":4,"exp":{"concept":"DDoS(분산 서비스 거부) 공격은 여러 대의 감염된 컴퓨터(좀비 PC)를 이용해 한 대상에 대량의 트래픽을 보내 서비스를 마비시키는 공격이다. 이 공격에 쓰이는 대표 도구로 Trinoo, TFN(Tribe Flood Network), TFN2K, Stacheldraht 등이 있다.","choices":[{"verdict":"오답","why":"Nimda는 여러 경로로 스스로 퍼지는 웜(Worm) 악성 코드로, DDoS 공격 도구가 아니다."},{"verdict":"오답","why":"Deadlock(교착 상태)은 프로세스들이 서로의 자원을 기다리며 멈춘 운영체제의 상태로, 공격 방법이 아니다."},{"verdict":"오답","why":"Secure Shell(SSH)은 원격 접속을 암호화해 주는 보안 프로토콜로, 공격 방법이 아니다."},{"verdict":"정답","why":"TFN(Tribe Flood Network)은 많은 소스에서 하나 이상의 목적지로 대량의 패킷을 보내 서비스를 마비시키는 DDoS 공격 도구다."}],"keywords":[{"term":"DDoS(Distributed Denial of Service)","desc":"여러 시스템을 이용해 대상 시스템의 서비스를 마비시키는 공격"},{"term":"DDoS 공격 도구","desc":"Trinoo, TFN, TFN2K, Stacheldraht"},{"term":"좀비 PC","desc":"악성 코드에 감염되어 공격자의 원격 명령을 따르는 컴퓨터"}],"memo":"DDoS 도구는 '트리누, TFN, TFN2K, 슈타첼드라트'로 묶어 외운다. Flood(홍수)라는 이름에서 대량 트래픽을 떠올린다."}},{"id":"written-2024-1-100","no":100,"unit":"정보시스템 구축 관리","q":"Python 기반으로, 컴포넌트의 재사용과 플러그인화를 강조해 신속한 개발이 가능하게 지원하는 프레임워크는?","choices":["Node.js","Spring","Codeigniter","Django"],"ans":4,"exp":{"concept":"프레임워크(Framework)는 개발에 필요한 기본 구조와 기능을 미리 만들어 두어, 개발자가 그 틀 위에서 빠르게 개발할 수 있게 해 주는 반제품 형태의 소프트웨어다. 언어마다 대표 프레임워크가 있는데, Python 기반으로 컴포넌트 재사용과 플러그인화를 강조해 신속한 개발을 지원하는 것은 Django다.","choices":[{"verdict":"오답","why":"Node.js는 JavaScript를 서버에서 실행할 수 있게 해 주는 JavaScript 기반 환경으로, Python 기반이 아니다."},{"verdict":"오답","why":"Spring은 Java 기반 프레임워크로, 전자정부 표준 프레임워크의 기반 기술이다."},{"verdict":"오답","why":"Codeigniter는 PHP 기반 웹 애플리케이션 프레임워크다."},{"verdict":"정답","why":"Django는 Python 기반 프레임워크로, 컴포넌트의 재사용과 플러그인화를 강조해 신속한 개발을 지원한다."}],"keywords":[{"term":"Django","desc":"Python 기반 웹 프레임워크"},{"term":"Spring","desc":"Java 기반 프레임워크, 전자정부 표준 프레임워크의 기반"},{"term":"Node.js","desc":"JavaScript 기반 서버 실행 환경"},{"term":"Codeigniter","desc":"PHP 기반 웹 프레임워크"}],"memo":"언어와 짝지어 외운다. Python은 Django, Java는 Spring, JavaScript는 Node.js, PHP는 Codeigniter다."}}]};